INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站窗口等人。", "corrected_sentence": "她站在窗口等人。", "error_description": "错误在于漏掉了“在”。表示站在某处时要说“站在＋地点”，“站窗口”不通顺；应改为“站在窗口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在站人群前面，看着舞台。", "corrected_sentence": "她站在人群前面，看着舞台。", "error_description": "错误在于“站”和“在”的顺序。应说“站在人群前面”，“在站人群前面”语序错误，不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
