INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85985, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“一种”是说一类东西，不是只有一个。", "primary_collocate": null, "pronunciation": "yì zhǒng", "ipa": "i˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是一种水果。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那是一种鸟。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "熊猫是一种动物。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢喝一种绿色的茶。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一种很甜的苹果，你吃吧。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家旁边有一种小花，很香。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在商店里买了一种新牌子的牛奶。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有一种鱼，只在冬天才能吃到。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给她一种药，一天吃两次。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫爱吃一种竹子。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一种：指某一类具体的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一种", "is_correct": true, "explanation": "正确：“一种水果”表示一类水果，符合“这是___水果”的语境。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对的东西，水果不能用“只”计量。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，水果一般不用“条”计量。"}, {"text": "一位", "is_correct": false, "explanation": "语义：“位”用于指人，水果不是人，不能用“位”计量。"}], "explanations": {"一种": "正确：“一种水果”表示一类水果，符合“这是___水果”的语境。", "一只": "搭配：“只”用于动物或成对的东西，水果不能用“只”计量。", "一条": "搭配：“条”用于细长的东西，水果一般不用“条”计量。", "一位": "语义：“位”用于指人，水果不是人，不能用“位”计量。"}, "sentence_index": 0, "correct_answer": "一种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口站着一种老人，他一直在看我。", "explanation": "这里应该用〈一个〉。“一种”说的是一类，不是只有一个；这里指门口一位具体的老人，用“一个”。"}, {"text": "他昨晚给我写了一种信，就是那封我一直放在抽屉里的信。", "explanation": "这里应该用〈一封〉。“一种”说的是一类；这里指他写给我的那一封具体的信，信要用“封”计量。"}, {"text": "我五岁那年在院子里捡到一种小狗，就是现在的小黑。", "explanation": "这里应该用〈一只〉。“一种”说的是一类；这里指我捡到的那只具体的小狗（就是现在的小黑），小狗要用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一种", "is_correct": true, "explanation": "正确：“买了一种新牌子的牛奶”表示一类牛奶，符合语境。"}, {"text": "一支", "is_correct": false, "explanation": "搭配：“支”用于杆状物或笔等，牛奶不用“支”计量。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物，不能计量牛奶。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”指一次活动或事件，牛奶不是事件，与“买了”不合。"}], "explanations": {"一种": "正确：“买了一种新牌子的牛奶”表示一类牛奶，符合语境。", "一支": "搭配：“支”用于杆状物或笔等，牛奶不用“支”计量。", "一座": "搭配：“座”用于山、房屋等大型固定物，不能计量牛奶。", "一场": "语义：“场”指一次活动或事件，牛奶不是事件，与“买了”不合。"}, "sentence_index": 6, "correct_answer": "一种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家来了一种客人，他很和气。", "explanation": "这里应该用〈一位〉。“一种”说的是一类；这里指一位具体的客人，用“位”计量。"}, {"text": "桌子上放着一种书，就是我昨天买的那本。", "explanation": "这里应该用〈一本〉。“一种”说的是一类；这里指一本具体的书，书要用“本”计量。"}, {"text": "院子门口立着一种树，就是那棵被雷劈过的老槐树。", "explanation": "这里应该用〈一棵〉。“一种”说的是一类；这里指院子门口那一棵具体的老槐树（就是那棵），树要用“棵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一种个香蕉，很甜。", "corrected_sentence": "这是一种香蕉，很甜。", "error_description": "错误：“一种”后面不能再接量词“个”，应直接说“一种香蕉”。正确：“这是一种香蕉，很甜。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一种的鸟，叫做翠鸟。", "corrected_sentence": "这里有一种鸟，叫做翠鸟。", "error_description": "错误：“一种”是数量短语，后面直接接名词，不能加“的”，应说“一种鸟”，不能说“一种的鸟”。正确：“这里有一种鸟，叫做翠鸟。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
