INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85986, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示一个种类。", "primary_collocate": null, "pronunciation": "yì zhǒng", "ipa": "i˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我有一种好办法。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一种好习惯。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学中文是一种快乐。", "target_word": "一种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看到她，我有一种熟悉的感觉。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话的声音有一种特别的力量。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步是一种让人高兴的运动。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着说，这只是一种爱好。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，读书是一种休息的方式。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一种很慢的声音回答了我。", "target_word": "一种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭对她来说是一种放松。", "target_word": "一种", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一种：数量词，指抽象的一个种类、方式或感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一种", "is_correct": true, "explanation": "正确：“一种好办法”说的是一类办法，符合语境。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对的东西，“办法”不能用“只”计量。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物，不能计量“办法”。"}, {"text": "一位", "is_correct": false, "explanation": "语义：“位”用于指人，“办法”不是人，与“好”搭配不当。"}], "explanations": {"一种": "正确：“一种好办法”说的是一类办法，符合语境。", "一只": "搭配：“只”用于动物或成对的东西，“办法”不能用“只”计量。", "一座": "搭配：“座”用于山、房屋等大型固定物，不能计量“办法”。", "一位": "语义：“位”用于指人，“办法”不是人，与“好”搭配不当。"}, "sentence_index": 0, "correct_answer": "一种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口走来一种老师，她是我的班主任。", "explanation": "这里应该用〈一位〉。“一种”说的是一类；这里指一位具体的老师，用“位”计量。"}, {"text": "我昨天看了一种电影，就是我们俩上次一起看的那部。", "explanation": "这里应该用〈一部〉。“一种”说的是一类；这里指我们俩上次一起看的那部具体的电影，电影要用“部”计量。"}, {"text": "我家阳台上趴着一种猫，就是那只一直不肯走的黑猫。", "explanation": "这里应该用〈一只〉。“一种”说的是一类；这里指阳台上那只具体的黑猫，猫要用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一种", "is_correct": true, "explanation": "正确：“这只是一种爱好”表示一类爱好，符合语境。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”指成片的地面或平面，不能计量“爱好”。"}, {"text": "一颗", "is_correct": false, "explanation": "搭配：“颗”用于小而圆的东西，不能计量“爱好”。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”指一次活动或事件，“爱好”不是一次事件，与“只是”不合。"}], "explanations": {"一种": "正确：“这只是一种爱好”表示一类爱好，符合语境。", "一片": "搭配：“片”指成片的地面或平面，不能计量“爱好”。", "一颗": "搭配：“颗”用于小而圆的东西，不能计量“爱好”。", "一场": "语义：“场”指一次活动或事件，“爱好”不是一次事件，与“只是”不合。"}, "sentence_index": 6, "correct_answer": "一种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天吃了一种面，就是妈妈做的那碗。", "explanation": "这里应该用〈一碗〉。“一种”说的是一类；这里指妈妈做的那一碗具体的面，面要用“碗”计量。"}, {"text": "这个房间里住着一种人，就是我的弟弟。", "explanation": "这里应该用〈一个〉。“一种”说的是一类；这里指房间里一个具体的人，用“个”计量。"}, {"text": "门口停着一种汽车，就是爸爸那辆旧的。", "explanation": "这里应该用〈一辆〉。“一种”说的是一类；这里指爸爸那辆具体的旧车，汽车要用“辆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一种个好脾气。", "corrected_sentence": "他有一种好脾气。", "error_description": "错误：“一种”后面不能再接量词“个”，应直接说“一种好脾气”。正确：“他有一种好脾气。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "读书对他来说是一种的乐趣。", "corrected_sentence": "读书对他来说是一种乐趣。", "error_description": "错误：“一种”是数量短语，后面直接接名词，不能加“的”，应说“一种乐趣”，不能说“一种的乐趣”。正确：“读书对他来说是一种乐趣。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
