INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“天”指一昼夜，即二十四小时。", "primary_collocate": null, "pronunciation": "tiān", "ipa": "tʰjɛn˥", "syllable_count": 1, "sentences": [{"text": "我在这儿住三天。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一天吃三次饭。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一天有二十四小时。", "target_word": "天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我下个星期要去北京住五天。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜只能放两天，要快点吃。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他病了三天，没去学校。", "target_word": "天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一个星期学三天中文，很认真。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了好几天，才到那个小山村。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三天没睡觉，看起来非常累。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过完这三天，我们就可以放假了。", "target_word": "天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天天", "label": "重叠"}, {"form": "每天", "label": "复合"}], "register": "中性", "sense_fingerprint": "天：一昼夜，计算时间的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：听到的是 tiān（第一声），即“天”，指一昼夜。"}, {"text": "甜", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是甜。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tiān（第一声）声母相同、韵母相近但声调不同，意思是用舌头舔。"}, {"text": "填", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）只差声调，意思是填入。"}], "explanations": {"天": "正确：听到的是 tiān（第一声），即“天”，指一昼夜。", "甜": "tián（第二声）与 tiān（第一声）声调不同，意思是甜。", "舔": "tiǎn（第三声）与 tiān（第一声）声母相同、韵母相近但声调不同，意思是用舌头舔。", "填": "tián（第二声）与 tiān（第一声）只差声调，意思是填入。"}, "sentence_index": null, "correct_answer": "天"}, "level_3": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：“我在这儿住三天”表示一段时间，符合“住”的语境。"}, {"text": "秒", "is_correct": false, "explanation": "语义：“秒”太短，与“住”需要的较长时间不合。"}, {"text": "分钟", "is_correct": false, "explanation": "语义：“分钟”也太短，与“住”需要的时间长度不合。"}, {"text": "节", "is_correct": false, "explanation": "搭配：“节”是课时单位，不能用来计量住宿的时间。"}], "explanations": {"天": "正确：“我在这儿住三天”表示一段时间，符合“住”的语境。", "秒": "语义：“秒”太短，与“住”需要的较长时间不合。", "分钟": "语义：“分钟”也太短，与“住”需要的时间长度不合。", "节": "搭配：“节”是课时单位，不能用来计量住宿的时间。"}, "sentence_index": 0, "correct_answer": "天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段天他一直很忙，几乎没有休息。", "explanation": "这里应该用〈日子〉。“天”不能与“这段”搭配表示一段时间；说一段时间要用“日子”。"}, {"text": "我们在北京等了一段天，才见到他。", "explanation": "这里应该用〈一段时间〉。“天”不能与“一段”搭配表示时间的长度；应说“一段时间”。"}, {"text": "我们在北京住了两次天，很开心。", "explanation": "这里应该用〈两天〉。“次”是计量次数的量词，不能计量“天”表示的时间；应说“两天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = E