INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86020, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：听到的是 tiān（第一声），即“天”，指一昼夜。"}, {"text": "田", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是田地。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tiān（第一声）只差声调，意思是用舌头舔。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tiān（第一声）只差介音 i，意思是贪心。"}], "explanations": {"天": "正确：听到的是 tiān（第一声），即“天”，指一昼夜。", "田": "tián（第二声）与 tiān（第一声）声调不同，意思是田地。", "舔": "tiǎn（第三声）与 tiān（第一声）只差声调，意思是用舌头舔。", "贪": "tān（第一声）与 tiān（第一声）只差介音 i，意思是贪心。"}, "sentence_index": null, "correct_answer": "天"}, "level_3": {"options": [{"text": "天", "is_correct": true, "explanation": "正确：“她一个星期学三天中文”表示一段时间，与“一个星期”相符。"}, {"text": "年", "is_correct": false, "explanation": "语义：“一个星期”与“三年”的时间跨度矛盾。"}, {"text": "月", "is_correct": false, "explanation": "语义：“一个星期”与“三个月”的时间跨度矛盾。"}, {"text": "届", "is_correct": false, "explanation": "搭配：“届”指一批毕业的学生，不能用来计量学习中文的时间。"}], "explanations": {"天": "正确：“她一个星期学三天中文”表示一段时间，与“一个星期”相符。", "年": "语义：“一个星期”与“三年”的时间跨度矛盾。", "月": "语义：“一个星期”与“三个月”的时间跨度矛盾。", "届": "搭配：“届”指一批毕业的学生，不能用来计量学习中文的时间。"}, "sentence_index": 6, "correct_answer": "天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山里住了一座天，很开心。", "explanation": "这里应该用〈一天〉。“座”用于山、楼等大型固定物，不能计量“天”表示的时间；应说“一天”。"}, {"text": "我们在海边玩了两颗天，很开心。", "explanation": "这里应该用〈两天〉。“颗”用于星星、果实等小而圆的东西，不能计量“天”表示的时间；应说“两天”。"}, {"text": "他在医院躺了一扇天，很无聊。", "explanation": "这里应该用〈一天〉。“扇”用于门窗，不能计量“天”表示的时间；应说“一天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们等了三个天才见到他。", "corrected_sentence": "我们等了三天才见到他。", "error_description": "错误：“天”作时量词，数词后直接接“天”，不加“个”。正确：“我们等了三天才见到他。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山里待了五个天。", "corrected_sentence": "他们在山里待了五天。", "error_description": "错误：“天”作时量词，数词后直接接“天”，不加“个”，应说“待了五天”，不能说“待了五个天”。正确：“他们在山里待了五天。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
