INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主制国家的最高统治者。", "primary_collocate": null, "pronunciation": "guó wáng", "ipa": "kuo˧˥ waŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家的国王很受人民喜爱。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王住在一座很大的城堡里。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国现在有一位国王。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王生病了，王子要当新国王。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令，所有人都要来开会。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位国王统治国家四十年了。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王的儿子将来会成为新国王。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王坐在椅子上，听大臣说话。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写了很多国王的故事。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王和王后一起走进大厅。", "target_word": "国王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老国王", "label": "复合"}, {"form": "國王", "label": "繁体"}], "register": "中性", "sense_fingerprint": "君主制国家的最高统治者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国王", "is_correct": true, "explanation": "正确：国王（guó wáng）指君主制国家的最高统治者。"}, {"text": "国网", "is_correct": false, "explanation": "wǎng（第三声）与 wáng（第二声）声调不同，意思是“国网”（国家电网的简称）。"}, {"text": "过网", "is_correct": false, "explanation": "guò（第四声）与 guó 声调不同，wǎng 与 wáng 声调也不同，意思是“过网”（球越过球网）。"}, {"text": "狗王", "is_correct": false, "explanation": "gǒu（第三声）与 guó 的韵母不同（ou 与 uo），意思是“狗王”（狗中的王）。"}, {"text": "鬼王", "is_correct": false, "explanation": "guǐ（第三声）与 guó 的韵母不同（uei 与 uo），意思是“鬼王”（鬼怪之王）。"}], "explanations": {"国王": "正确：国王（guó wáng）指君主制国家的最高统治者。", "国网": "wǎng（第三声）与 wáng（第二声）声调不同，意思是“国网”（国家电网的简称）。", "过网": "guò（第四声）与 guó 声调不同，wǎng 与 wáng 声调也不同，意思是“过网”（球越过球网）。", "狗王": "gǒu（第三声）与 guó 的韵母不同（ou 与 uo），意思是“狗王”（狗中的王）。", "鬼王": "guǐ（第三声）与 guó 的韵母不同（uei 与 uo），意思是“鬼王”（鬼怪之王）。"}, "sentence_index": null, "correct_answer": "国王"}, "level_3": {"options": [{"text": "国王", "is_correct": true, "explanation": "正确：“国王”是君主，句中说“很受人民喜爱”，符合语境。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱不会成为人民喜爱的对象，与“很受人民喜爱”的句意不合。"}, {"text": "税收", "is_correct": false, "explanation": "搭配：“很受……喜爱”的对象通常是人或事物，“税收”不能与之搭配。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不会受人民喜爱，句子读起来不通。"}], "explanations": {"国王": "正确：“国王”是君主，句中说“很受人民喜爱”，符合语境。", "监狱": "语义：监狱不会成为人民喜爱的对象，与“很受人民喜爱”的句意不合。", "税收": "搭配：“很受……喜爱”的对象通常是人或事物，“税收”不能与之搭配。", "垃圾": "语义：垃圾不会受人民喜爱，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "国王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国王被将死了。", "explanation": "这里的“国王”指国际象棋中的棋子，是另一个义项，不是君主制国家的最高统治者。"}, {"text": "这位国王是女的，统治了三十年。", "explanation": "这里应该用〈女王〉。“国王”指男性君主，女性君主要说“女王”，“国王”不能指女性。"}, {"text": "我们班来了一只国王。", "explanation": "“国王”指人，应该用量词“位”；“只”用于动物等，不能用于国王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国王", "is_correct": true, "explanation": "正确：“国王”的儿子将来成为国王，符合继承关系的语境。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师的儿子成为国王与君主继承的常识不合，句子读起来不通。"}, {"text": "大臣", "is_correct": false, "explanation": "语义：大臣的儿子成为国王与君主继承的常识不合，句子读起来不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“……的儿子”要求人，“花园”不能与之搭配。"}], "explanations": {"国王": "正确：“国王”的儿子将来成为国王，符合继承关系的语境。", "老师": "语义：老师的儿子成为国王与君主继承的常识不合，句子读起来不通。", "大臣": "语义：大臣的儿子成为国王与君主继承的常识不合，句子读起来不通。", "花园": "搭配：“……的儿子”要求人，“花园”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "国王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国王很大，有很多人口。", "explanation": "这里应该用〈国家〉。“国王”指君主，不指国土；说国土大、人口多要用“国家”。"}, {"text": "他继承了国王。", "explanation": "这里应该用〈王位〉。“继承”的对象是“王位”，国王是人，不能被继承。"}, {"text": "宫殿里走出了一匹国王。", "explanation": "“国王”指人，应该用量词“位”；“匹”用于马等牲畜，不能用于国王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个古老的国家有一只国王。", "corrected_sentence": "这个古老的国家有一位国王。", "error_description": "量词用错。“国王”指人，应用量词“位”；“只”用于动物等，不能用于国王。错误形式是“一只国王”，正确形式是“一位国王”。正确句：这个古老的国家有一位国王。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王地宫殿非常华丽。", "corrected_sentence": "国王的宫殿非常华丽。", "error_description": "修饰名词要用“的”，不用“地”。“地”用于修饰动词、形容词。错误形式是“国王地宫殿”，正确形式是“国王的宫殿”，表示宫殿属于国王。正确句：国王的宫殿非常华丽。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
