INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86025, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“总”是说一直这样，每次都这样。", "primary_collocate": null, "pronunciation": "zǒng", "ipa": "tsʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我每次找他，他总不在家。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一下雨，路上总堵车。", "target_word": "总", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给他打电话，他总说没时间。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开会的时候，总坐在最后一排。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每到周末，爸爸总去公园跑步。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前，她总紧张得吃不下饭。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一说到工作，他总皱着眉头。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次见面，奶奶总给我做好吃的。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们吵架后，他总先说对不起。", "target_word": "总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去外地出差，我总带着那本书。", "target_word": "总", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总是", "label": "复合"}, {"form": "总得", "label": "复合"}], "register": "口语", "sense_fingerprint": "总：副词，每次遇到同样情况都这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea339396-6baf-4360-8d3a-df8539a24aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86025, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：总，zǒng（第三声），意思是每次都这样。"}, {"text": "宗", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是宗族。"}, {"text": "纵", "is_correct": false, "explanation": "zòng（第四声）与 zǒng（第三声）声调不同，意思是放纵。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng 与 zǒng 声母不同（zh/z），意思是种类。"}, {"text": "走", "is_correct": false, "explanation": "zǒu 与 zǒng 韵母不同（ou/ong），意思是行走。"}], "explanations": {"总": "正确：总，zǒng（第三声），意思是每次都这样。", "宗": "zōng（第一声）与 zǒng（第三声）声调不同，意思是宗族。", "纵": "zòng（第四声）与 zǒng（第三声）声调不同，意思是放纵。", "种": "zhǒng 与 zǒng 声母不同（zh/z），意思是种类。", "走": "zǒu 与 zǒng 韵母不同（ou/ong），意思是行走。"}, "sentence_index": null, "correct_answer": "总"}, "level_3": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：“总”表示每次都这样，与“每次”相符。"}, {"text": "突然", "is_correct": false, "explanation": "体貌：“突然”表示事情忽然发生，与“每次”所表示的反复、习惯不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指少有发生，与“每次”所表示的反复情况相冲突。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要接本人动手的动作，不能修饰“不在家”这种状态。"}], "explanations": {"总": "正确：“总”表示每次都这样，与“每次”相符。", "突然": "体貌：“突然”表示事情忽然发生，与“每次”所表示的反复、习惯不合。", "偶尔": "语义：“偶尔”指少有发生，与“每次”所表示的反复情况相冲突。", "亲自": "搭配：“亲自”要接本人动手的动作，不能修饰“不在家”这种状态。"}, "sentence_index": 0, "correct_answer": "总"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总一下子还清了所有欠款。", "explanation": "这里不能用“总”。“总”表示每次都这样，“一下子还清”是只发生一次的事，两者矛盾。"}, {"text": "我们总刚刚见过面了。", "explanation": "这里不能用“总”。“总”表示每次都这样，“刚刚见过面”指不久前的一次，两者矛盾。"}, {"text": "他总在去年冬天去世了。", "explanation": "这里不能用“总”。“总”表示每次都这样，“去年冬天去世”是一次性的事，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86025, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：总，zǒng（第三声），意思是每次都这样。"}, {"text": "综", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是综合。"}, {"text": "粽", "is_correct": false, "explanation": "zòng（第四声）与 zǒng（第三声）声调不同，意思是粽子。"}, {"text": "棕", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是棕色。"}], "explanations": {"总": "正确：总，zǒng（第三声），意思是每次都这样。", "综": "zōng（第一声）与 zǒng（第三声）声调不同，意思是综合。", "粽": "zòng（第四声）与 zǒng（第三声）声调不同，意思是粽子。", "棕": "zōng（第一声）与 zǒng（第三声）声调不同，意思是棕色。"}, "sentence_index": null, "correct_answer": "总"}, "level_3": {"options": [{"text": "总", "is_correct": true, "explanation": "正确：“总”表示每次都这样，与“一说到工作就”的惯常反应相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“一说到工作就”这种惯常反应的意思不合。"}, {"text": "猛然", "is_correct": false, "explanation": "体貌：“猛然”表示突然发生的一次动作，与“一……就”所表示的反复情况不合。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言副词，与这句口语叙述不协调。"}], "explanations": {"总": "正确：“总”表示每次都这样，与“一说到工作就”的惯常反应相符。", "竟然": "语义：“竟然”表示出乎意料，与“一说到工作就”这种惯常反应的意思不合。", "猛然": "体貌：“猛然”表示突然发生的一次动作，与“一……就”所表示的反复情况不合。", "遂": "语域：“遂”是文言副词，与这句口语叙述不协调。"}, "sentence_index": 6, "correct_answer": "总"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总在上个月换了工作。", "explanation": "这里不能用“总”。“总”表示每次都这样，“上个月换了工作”是一次性的事，两者矛盾。"}, {"text": "我总第一次去外地出差。", "explanation": "这里不能用“总”。“总”表示每次都这样，“第一次”只发生一次，两者矛盾。"}, {"text": "他总在我到的那一刻离开了。", "explanation": "这里不能用“总”。“总”表示每次都这样，“在我到的那一刻离开”是一次性的事，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每次去找他，总他不在家。", "corrected_sentence": "我每次去找他，他总不在家。", "error_description": "错误在于“总”的位置。“总”要放在主语“他”之后、动词之前，应说“他总不在家”；“总他不在家”把副词放在主语前，语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每次出差，我带总着那本书。", "corrected_sentence": "每次出差，我总带着那本书。", "error_description": "错误在于“总”的位置。“总”是副词，应放在动词“带”之前，说“总带着”；“带总着”把副词插进了“带着”中间，语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
