INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86033, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“一次”是说做了一回。", "primary_collocate": null, "pronunciation": "yī cì", "ipa": "i⁵⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "这件事我只做过一次。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你就帮我一次吧。", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次就成功了，真不容易。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只哭了一次，后来再也没哭过。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来过一次，没有再来。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我写错了一次。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐过一次飞机，有点紧张。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我做了一次饭。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起玩一次吧。", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骗了我一次，我不会再信他了。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一次：做了一回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea339396-6baf-4360-8d3a-df8539a24aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次是数量词，表示做了一回。"}, {"text": "一词", "is_correct": false, "explanation": "一词（yī cí）与 yī cì 第二音节声调不同，cí 是第二声，意思是一个词语。"}, {"text": "一字", "is_correct": false, "explanation": "一字（yī zì）与 yī cì 声母不同（z 与 c），意思是一个字。"}, {"text": "亿次", "is_correct": false, "explanation": "亿次（yì cì）与 yī cì 第一音节声调不同，yì 是第四声，意思是一亿次。"}, {"text": "一丝", "is_correct": false, "explanation": "一丝（yī sī）与 yī cì 声母不同（s 与 c），意思是极少的一点。"}], "explanations": {"一次": "正确答案。一次是数量词，表示做了一回。", "一词": "一词（yī cí）与 yī cì 第二音节声调不同，cí 是第二声，意思是一个词语。", "一字": "一字（yī zì）与 yī cì 声母不同（z 与 c），意思是一个字。", "亿次": "亿次（yì cì）与 yī cì 第一音节声调不同，yì 是第四声，意思是一亿次。", "一丝": "一丝（yī sī）与 yī cì 声母不同（s 与 c），意思是极少的一点。"}, "sentence_index": null, "correct_answer": "一次"}, "level_3": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次表示做过的次数，与“只做过一次”相符。"}, {"text": "一趟", "is_correct": false, "explanation": "搭配：“趟”用于往返的行程，“做这件事”不说“做过一趟”。"}, {"text": "一顿", "is_correct": false, "explanation": "搭配：“顿”用于饭食或责骂，不能用来说“做过一顿这件事”。"}, {"text": "一手", "is_correct": false, "explanation": "语义：“手”表示技能或本领，这里说的是做的次数，不是技能。"}], "explanations": {"一次": "正确答案。一次表示做过的次数，与“只做过一次”相符。", "一趟": "搭配：“趟”用于往返的行程，“做这件事”不说“做过一趟”。", "一顿": "搭配：“顿”用于饭食或责骂，不能用来说“做过一顿这件事”。", "一手": "语义：“手”表示技能或本领，这里说的是做的次数，不是技能。"}, "sentence_index": 0, "correct_answer": "一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支铅笔一次很短。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能直接作谓语描述状态；应说“很短”。"}, {"text": "她一次很漂亮。", "explanation": "这里不能用“一次”。“一次”只计动作的次数，不能用来描述人的外貌；应说“很漂亮”。"}, {"text": "这袋米一次很重。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86033, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次是数量词，表示做了一回。"}, {"text": "一事", "is_correct": false, "explanation": "一事（yī shì）与 yī cì 声母不同（sh 与 c），意思是一件事。"}, {"text": "一世", "is_correct": false, "explanation": "一世（yī shì）与 yī cì 声母不同（sh 与 c），意思是一辈子。"}, {"text": "一册", "is_correct": false, "explanation": "一册（yī cè）与 yī cì 韵母不同（e 与 i），意思是一本书。"}], "explanations": {"一次": "正确答案。一次是数量词，表示做了一回。", "一事": "一事（yī shì）与 yī cì 声母不同（sh 与 c），意思是一件事。", "一世": "一世（yī shì）与 yī cì 声母不同（sh 与 c），意思是一辈子。", "一册": "一册（yī cè）与 yī cì 韵母不同（e 与 i），意思是一本书。"}, "sentence_index": null, "correct_answer": "一次"}, "level_3": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次表示坐飞机的次数，与“坐过一次飞机”相符。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”多用于动物，不能用来数“飞机”。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，飞机不能用它来计数。"}, {"text": "一封", "is_correct": false, "explanation": "语义：“封”用于信件，飞机不能用它来计数。"}], "explanations": {"一次": "正确答案。一次表示坐飞机的次数，与“坐过一次飞机”相符。", "一只": "搭配：“只”多用于动物，不能用来数“飞机”。", "一条": "搭配：“条”用于细长的东西，飞机不能用它来计数。", "一封": "语义：“封”用于信件，飞机不能用它来计数。"}, "sentence_index": 6, "correct_answer": "一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个面包一次很好吃。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很好吃”。"}, {"text": "这场比赛一次很精彩。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很精彩”。"}, {"text": "天气一次很热。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很热”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_er