INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86034, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示动作发生一回。", "primary_collocate": null, "pronunciation": "yī cì", "ipa": "i⁵⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "我去过一次北京。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我只去了一次图书馆。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年回一次老家。", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你再说一次，好吗？", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们试一次。", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影我看了一次就不想看了。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一周游一次泳，对身体很好。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了一次电话，他没接。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一个月开一次会。", "target_word": "一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这家店吃过一次饭。", "target_word": "一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一次", "label": "复合"}, {"form": "一次性", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量词：动作发生一回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea339396-6baf-4360-8d3a-df8539a24aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_