INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次是数量词，表示动作发生一回。"}, {"text": "一词", "is_correct": false, "explanation": "一词（yī cí）与 yī cì 第二音节声调不同，cí 是第二声，意思是一个词语。"}, {"text": "一字", "is_correct": false, "explanation": "一字（yī zì）与 yī cì 声母不同（z 与 c），意思是一个字。"}, {"text": "亿次", "is_correct": false, "explanation": "亿次（yì cì）与 yī cì 第一音节声调不同，yì 是第四声，意思是一亿次。"}, {"text": "一丝", "is_correct": false, "explanation": "一丝（yī sī）与 yī cì 声母不同（s 与 c），意思是极少的一点。"}], "explanations": {"一次": "正确答案。一次是数量词，表示动作发生一回。", "一词": "一词（yī cí）与 yī cì 第二音节声调不同，cí 是第二声，意思是一个词语。", "一字": "一字（yī zì）与 yī cì 声母不同（z 与 c），意思是一个字。", "亿次": "亿次（yì cì）与 yī cì 第一音节声调不同，yì 是第四声，意思是一亿次。", "一丝": "一丝（yī sī）与 yī cì 声母不同（s 与 c），意思是极少的一点。"}, "sentence_index": null, "correct_answer": "一次"}, "level_3": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次表示去北京的次数，与“去过一次北京”相符。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、楼等大型固定物，不能说“一座北京”。"}, {"text": "一句", "is_correct": false, "explanation": "语义：“句”用来数句子或话语，北京不是可以用句来计数的内容。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来计数“北京”这样的地点。"}], "explanations": {"一次": "正确答案。一次表示去北京的次数，与“去过一次北京”相符。", "一座": "搭配：“座”用于山、桥、楼等大型固定物，不能说“一座北京”。", "一句": "语义：“句”用来数句子或话语，北京不是可以用句来计数的内容。", "一本": "搭配：“本”用于书册，不能用来计数“北京”这样的地点。"}, "sentence_index": 0, "correct_answer": "一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋一次很舒服。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能直接作谓语描述状态；应说“很舒服”。"}, {"text": "他一次很聪明。", "explanation": "这里不能用“一次”。“一次”只计动作的次数，不能用来描述人的性质；应说“很聪明”。"}, {"text": "这个房间一次很大。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次是数量词，表示动作发生一回。"}, {"text": "一事", "is_correct": false, "explanation": "一事（yī shì）与 yī cì 声母不同（sh 与 c），意思是一件事。"}, {"text": "一世", "is_correct": false, "explanation": "一世（yī shì）与 yī cì 声母不同（sh 与 c），意思是一辈子。"}, {"text": "一册", "is_correct": false, "explanation": "一册（yī cè）与 yī cì 韵母不同（e 与 i），意思是一本书。"}], "explanations": {"一次": "正确答案。一次是数量词，表示动作发生一回。", "一事": "一事（yī shì）与 yī cì 声母不同（sh 与 c），意思是一件事。", "一世": "一世（yī shì）与 yī cì 声母不同（sh 与 c），意思是一辈子。", "一册": "一册（yī cè）与 yī cì 韵母不同（e 与 i），意思是一本书。"}, "sentence_index": null, "correct_answer": "一次"}, "level_3": {"options": [{"text": "一次", "is_correct": true, "explanation": "正确答案。一次表示游泳的次数，与“一周游一次泳”相符。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于有柄的器具，不能说“一把泳”。"}, {"text": "一封", "is_correct": false, "explanation": "语义：“封”用于信件，游泳不能用它来计数。"}, {"text": "一朵", "is_correct": false, "explanation": "语义：“朵”用于花朵，不能用于游泳。"}], "explanations": {"一次": "正确答案。一次表示游泳的次数，与“一周游一次泳”相符。", "一把": "搭配：“把”用于有柄的器具，不能说“一把泳”。", "一封": "语义：“封”用于信件，游泳不能用它来计数。", "一朵": "语义：“朵”用于花朵，不能用于游泳。"}, "sentence_index": 6, "correct_answer": "一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书一次很厚。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很厚”。"}, {"text": "风一次很大。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很大”。"}, {"text": "这封信一次很长。", "explanation": "这里不能用“一次”。“一次”表示动作的次数，不能作谓语描述状态；应说“很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在那里住着一次。", "corrected_sentence": "我在那里住过一次。", "error_description": "错误形式：“住过”写成了“住着”。“着”表示动作的持续状态，与表示次数的“一次”搭配不通；应说“住过一次”，表示有过一次这样的经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每周去的一次健身房。", "corrected_sentence": "我每周去一次健身房。", "error_description": "错误形式：“一次”前面多加了“的”。“去一次健身房”中的“一次”是动作的次数，前面不能加“的”。正确形式为“我每周去一次健身房”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
