INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86036, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很高，常用于感叹句。", "primary_collocate": null, "pronunciation": "duō me", "ipa": "tuɔ˥ mɤ", "syllable_count": 2, "sentences": [{"text": "今天的天气多么好啊！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子多么可爱！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱得多么好听啊！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多么大的房子啊！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的山多么美！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我多么想回家看看！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到你，我多么高兴！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多么好的朋友啊！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路多么长啊！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我们多么好！", "target_word": "多么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多麼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多么：感叹句中表示程度很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f931a9f9-e62e-44dc-9fd3-572b2af66ba9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多么", "is_correct": true, "explanation": "正确。感叹句中“多么”表示程度很高，与“……啊！”配合。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，需要带宾语组成处置式，不能放在主语与形容词之间。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是句末疑问语气词，不能放在主语与形容词之间。"}, {"text": "稍微", "is_correct": false, "explanation": "语义：“稍微”表示程度轻，与感叹句“程度很高”的意思相反。"}], "explanations": {"多么": "正确。感叹句中“多么”表示程度很高，与“……啊！”配合。", "把": "语法：“把”是介词，需要带宾语组成处置式，不能放在主语与形容词之间。", "吗": "语法：“吗”是句末疑问语气词，不能放在主语与形容词之间。", "稍微": "语义：“稍微”表示程度轻，与感叹句“程度很高”的意思相反。"}, "sentence_index": 0, "correct_answer": "多么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你有多么钱？", "explanation": "这里应该用〈多少〉。多么表示程度，问钱的数量要用“多少”。"}, {"text": "你们班有多么学生？", "explanation": "这里应该用〈多少〉。多么表示程度，问人数要用“多少”。"}, {"text": "你家多么大？", "explanation": "“多么”不用于一般询问大小，问大小应说“多大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多么", "is_correct": true, "explanation": "正确。感叹句中“多么”表示程度很高，与“……！”配合。"}, {"text": "再", "is_correct": false, "explanation": "语义：“再”表示重复或继续，与“看到你”后的情感表达不符。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能在主语与形容词之间表示程度。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是句末疑问语气词，不能放在“我”与形容词之间。"}], "explanations": {"多么": "正确。感叹句中“多么”表示程度很高，与“……！”配合。", "再": "语义：“再”表示重复或继续，与“看到你”后的情感表达不符。", "的": "语法：“的”是结构助词，不能在主语与形容词之间表示程度。", "吗": "语法：“吗”是句末疑问语气词，不能放在“我”与形容词之间。"}, "sentence_index": 6, "correct_answer": "多么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题是多么算出来的？", "explanation": "这里应该用〈怎么〉。多么只表示程度，问方式要用“怎么”。"}, {"text": "你的书包多么重？", "explanation": "“多么”不用于一般询问轻重，问轻重应说“多重”。"}, {"text": "他去过多么次北京？", "explanation": "这里应该用〈几〉。多么表示程度，问次数要用“几”或“多少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵花多么很漂亮啊！", "corrected_sentence": "这朵花多么漂亮啊！", "error_description": "错误形式是“多么很漂亮”，正确形式是“多么漂亮”。“多么”已表示程度很高，不能再与“很”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，我多么很激动！", "corrected_sentence": "听到这个消息，我多么激动！", "error_description": "错误形式是“我多么很激动”，正确形式是“我多么激动”。“多么”已表示程度很高，不能再与“很”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
