INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领导是带着大家做事的人。", "primary_collocate": null, "pronunciation": "lǐng dǎo", "ipa": "liŋ˨˩ taʊ̯˨˩", "syllable_count": 2, "sentences": [{"text": "我们的领导对工作要求很高。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导今天上午不在办公室。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司的领导，大家都很尊重他。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领导对员工特别好。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请领导看一下这个计划。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导让我明天把文件交给他。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的领导很年轻。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上表扬了我，领导也笑了。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都说，这位领导很公平。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导正在开会，请你等一下。", "target_word": "领导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位领导", "label": "量词（位）"}, {"form": "领导人", "label": "复合"}, {"form": "领导者", "label": "复合"}, {"form": "領導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "领导｜名词｜带着大家做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c60b75e-2343-4e04-9358-7c28ad6f9510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导", "is_correct": true, "explanation": "正确：“领导”指带着大家做事的人，可以对工作提出要求。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是物件，不会对工作提出要求。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“要求”需要人作施事，“天气”不能对工作提要求。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物没有对工作提出要求的能力，句意不通。"}], "explanations": {"领导": "正确：“领导”指带着大家做事的人，可以对工作提出要求。", "工具": "语义：工具是物件，不会对工作提出要求。", "天气": "搭配：“要求”需要人作施事，“天气”不能对工作提要求。", "植物": "语义：植物没有对工作提出要求的能力，句意不通。"}, "sentence_index": 0, "correct_answer": "领导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的领导很结实，坐上去不晃。", "explanation": "这里应该用〈腿〉。“领导”指带着大家做事的人，不能指桌子的部件，桌子的腿应说“腿”。"}, {"text": "我爸爸是出租车领导，每天开车很辛苦。", "explanation": "这里应该用〈司机〉。“领导”指带着大家做事的人，开车的人是司机，不能叫领导。"}, {"text": "这块石头的领导很重，两个人才搬得动。", "explanation": "这里应该用〈分量〉。“领导”指人，不能指石头的属性，石头的重量应说“分量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导", "is_correct": true, "explanation": "正确：“领导”指人，可以“新来”，也可以“很年轻”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，没有年龄，不能用“很年轻”来形容。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能说“很年轻”，句中说的是人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“年轻”用于人或生物，不用于桌子。"}], "explanations": {"领导": "正确：“领导”指人，可以“新来”，也可以“很年轻”。", "石头": "语义：石头是无生命的物体，没有年龄，不能用“很年轻”来形容。", "空气": "语义：空气不是人，不能说“很年轻”，句中说的是人。", "桌子": "搭配：“年轻”用于人或生物，不用于桌子。"}, "sentence_index": 6, "correct_answer": "领导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的领导很有力，开起来很稳。", "explanation": "这里应该用〈发动机〉。“领导”指人，不能指汽车的部件，应说“发动机”。"}, {"text": "这本书的领导很有名，大家都读过。", "explanation": "这里应该用〈作者〉。“领导”指带着大家做事的人，写书的人要叫作者。"}, {"text": "这块蛋糕的领导很甜，大家都爱吃。", "explanation": "这里应该用〈味道〉。“领导”指人，不能指蛋糕的属性，应说“味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司来了一把新领导。", "corrected_sentence": "我们公司来了一位新领导。", "error_description": "量词错误：“把”用于有把手的物品，指人的“领导”应该用量词“位”，写作“一位新领导”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位刚调来领导很和气。", "corrected_sentence": "那位刚调来的领导很和气。", "error_description": "定语后缺“的”：“刚调来”修饰“领导”时要加“的”，应写作“刚调来的领导”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
