INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：jiān，量词“间”，用于教室、办公室等有隔断的空间"}, {"text": "姜", "is_correct": false, "explanation": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是生姜"}, {"text": "千", "is_correct": false, "explanation": "qiān 与 jiān 声母不同（q 与 j），意思是一千"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是剪刀"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiān 声调不同，意思是看见"}, {"text": "鲜", "is_correct": false, "explanation": "xiān 与 jiān 声母不同（x 与 j），意思是新鲜"}], "explanations": {"间": "正确：jiān，量词“间”，用于教室、办公室等有隔断的空间", "姜": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是生姜", "千": "qiān 与 jiān 声母不同（q 与 j），意思是一千", "剪": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是剪刀", "见": "jiàn（第四声）与 jiān 声调不同，意思是看见", "鲜": "xiān 与 jiān 声母不同（x 与 j），意思是新鲜"}, "sentence_index": null, "correct_answer": "间"}, "level_3": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：“间”用于教室等有隔断的空间，“学校有二十间教室”"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能数教室"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于画、布等平面的东西，不能数教室"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”指诗、歌，不指教室"}], "explanations": {"间": "正确：“间”用于教室等有隔断的空间，“学校有二十间教室”", "辆": "搭配：“辆”用于车辆，不能数教室", "幅": "搭配：“幅”用于画、布等平面的东西，不能数教室", "首": "语义：“首”指诗、歌，不指教室"}, "sentence_index": 0, "correct_answer": "间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一间书架。", "explanation": "这里应该用〈座〉。“间”用于房间，书架要用“座”来数"}, {"text": "我在一间学校教书。", "explanation": "这里应该用〈所〉。“所”用于学校、医院等机构，“间”用于有隔断的空间"}, {"text": "教室里摆着一间桌子。", "explanation": "这里应该用〈张〉。桌子用“张”来数，“间”用于有隔断的空间"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：jiān，量词“间”，用于有隔断的空间"}, {"text": "将", "is_correct": false, "explanation": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是将要"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 jiān 声母不同（x 与 j），意思是先后"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是减少"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiān 声调不同，意思是建造"}], "explanations": {"间": "正确：jiān，量词“间”，用于有隔断的空间", "将": "jiāng 与 jiān 韵尾不同（-ng 与 -n），意思是将要", "先": "xiān 与 jiān 声母不同（x 与 j），意思是先后", "减": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是减少", "建": "jiàn（第四声）与 jiān 声调不同，意思是建造"}, "sentence_index": null, "correct_answer": "间"}, "level_3": {"options": [{"text": "间", "is_correct": true, "explanation": "正确：“间”用于房间，“一楼有两间洗手间”"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物等，不能数洗手间"}, {"text": "扇", "is_correct": false, "explanation": "语义：“扇”指门窗，不指房间"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器等，不能数洗手间"}], "explanations": {"间": "正确：“间”用于房间，“一楼有两间洗手间”", "只": "搭配：“只”用于动物等，不能数洗手间", "扇": "语义：“扇”指门窗，不指房间", "台": "搭配：“台”用于机器等，不能数洗手间"}, "sentence_index": 6, "correct_answer": "间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一间花。", "explanation": "这里应该用〈朵〉。“间”用于房间，花要用“朵”来数"}, {"text": "他在一间公司上班。", "explanation": "这里应该用〈家〉。“家”用于公司、商店等，“间”用于房间"}, {"text": "我们唱了一间歌。", "explanation": "这里应该用〈首〉。歌用“首”来数，“间”用于有隔断的空间"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校新建了三个间实验室。", "corrected_sentence": "学校新建了三间实验室。", "error_description": "量词叠用。数词“三”后已有量词“间”，不能再加“个”，应为“三间实验室”，“间”用于有隔断的空间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有间两机房。", "corrected_sentence": "我们学校有两间机房。", "error_description": "语序错误。数词“两”要放在量词“间”前面，应为“两间机房”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
