INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "爱情是两个人互相很喜欢，想在一起的感情。", "primary_collocate": null, "pronunciation": "ài qíng", "ipa": "aɪ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他们俩的爱情很甜蜜。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的爱情是互相照顾，互相支持。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了爱情，她搬到了另一个城市。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的爱情经过了很多困难。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不相信没有钱的爱情。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对她的爱情，一直没有变。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十几岁的孩子还不太懂爱情。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找一份有爱情的婚姻。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的爱情让我也想谈恋爱了。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱情让这两个人在一起生活得很快乐。", "target_word": "爱情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "爱情片", "label": "复合"}, {"form": "愛情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个人互相喜欢、想在一起生活的感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e787e97-1e72-4215-97db-ad41e99b5a31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不能形容感情，“很甜蜜”说不通。"}, {"text": "爱情", "is_correct": true, "explanation": "爱情：两个人互相喜欢的感情，可以说“很甜蜜”，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能指人与人之间的感情，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“很甜蜜”用来形容感情或关系，厨房不能与它搭配。"}], "explanations": {"书架": "语义：书架是放书的家具，不能形容感情，“很甜蜜”说不通。", "爱情": "爱情：两个人互相喜欢的感情，可以说“很甜蜜”，与句意相符。", "冰箱": "语义：冰箱是家电，不能指人与人之间的感情，句子说不通。", "厨房": "搭配：“很甜蜜”用来形容感情或关系，厨房不能与它搭配。"}, "sentence_index": 0, "correct_answer": "爱情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和朋友之间有很深的爱情，多年来都没变。", "explanation": "这里应该用〈友情〉。爱情专指男女相爱的感情，朋友之间应说友情。"}, {"text": "他买了一张爱情，准备送给女朋友。", "explanation": "这里应该用〈一段〉。爱情的量词是“段”，“张”不用于爱情。"}, {"text": "妈妈是我最亲近的爱情。", "explanation": "这里应该用〈亲人〉。爱情指男女相爱的感情，家人应说亲人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车场", "is_correct": false, "explanation": "语义：停车场不能与“很甜蜜”搭配，句子指的是感情，句意不通。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放垃圾的器具，不能是可以“很甜蜜”的对象，句子说不通。"}, {"text": "饭桌", "is_correct": false, "explanation": "配价：“懂”的宾语要是道理或感情，饭桌不能作为“懂”的对象，句子说不通。"}, {"text": "爱情", "is_correct": true, "explanation": "爱情：两个人互相喜欢的感情，十几岁的孩子还不太懂这种感情，与句意相符。"}], "explanations": {"停车场": "语义：停车场不能与“很甜蜜”搭配，句子指的是感情，句意不通。", "垃圾桶": "语义：垃圾桶是盛放垃圾的器具，不能是可以“很甜蜜”的对象，句子说不通。", "饭桌": "配价：“懂”的宾语要是道理或感情，饭桌不能作为“懂”的对象，句子说不通。", "爱情": "爱情：两个人互相喜欢的感情，十几岁的孩子还不太懂这种感情，与句意相符。"}, "sentence_index": 6, "correct_answer": "爱情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她对小猫有很深的爱情，常常喂它吃东西。", "explanation": "这里应该用〈爱心〉。爱情指男女之间的感情，对动物的喜爱应说爱心。"}, {"text": "他是我的爱情，每天在工厂里上班。", "explanation": "这里应该用〈工人〉。爱情指男女相爱的感情，不能指身份；在工厂上班的人应说“工人”。"}, {"text": "他在花园里养了一只爱情。", "explanation": "这里应该用〈一段〉。爱情的量词是“段”，“只”不能用于爱情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我相信他们之间有一只真诚的爱情。", "corrected_sentence": "我相信他们之间有一段真诚的爱情。", "error_description": "量词错误：“爱情”的量词要用“段”，说“一段爱情”；“只”是动物的量词，不能用于爱情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们爱情很甜蜜。", "corrected_sentence": "我们的爱情很甜蜜。", "error_description": "结构错误：代词“我们”修饰抽象名词“爱情”时通常要加“的”，应说“我们的爱情”；“我们爱情”语感不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
