INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“名”是与“姓”相对的人的名字。", "primary_collocate": null, "pronunciation": "míng", "ipa": "miŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我姓王，我的名只有一个字。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人的姓在前，名在后。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先写你的姓，再写你的名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她姓林，名是美玉。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格里有两行：一行写姓，一行写名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师只记住了我的姓，没记住我的名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名是爷爷给起的。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名是爸爸给我起的。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的名里有一个“明”字。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的姓我知道，你的名是什么？", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名字", "label": "复合"}, {"form": "名称", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，与姓相对的人名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字，与姓相对的人名。"}, {"text": "命", "is_correct": false, "explanation": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。"}, {"text": "民", "is_correct": false, "explanation": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。"}, {"text": "平", "is_correct": false, "explanation": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字，与姓相对的人名。", "命": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。", "民": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。", "平": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。", "停": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“只有一个字”说的是字数，不能用来说身高。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“我的名只有一个字”指名字只有一个字。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不以字数计，与“只有一个字”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是字，不能说只有一个字。"}], "explanations": {"身高": "搭配：“只有一个字”说的是字数，不能用来说身高。", "名": "正确答案。“我的名只有一个字”指名字只有一个字。", "年龄": "语义：年龄是岁数，不以字数计，与“只有一个字”矛盾。", "手机": "语义：手机不是字，不能说只有一个字。"}, "sentence_index": 0, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她讲了一个名，大家都笑了。", "explanation": "这里应该用〈笑话〉。名指名字，不能指逗人发笑的话，“讲”要搭配“笑话”。"}, {"text": "这只名很好听。", "explanation": "量词用错。名字不用“只”计量（“只”多用于动物），应说“这个名”。"}, {"text": "她起了一张名，很好听。", "explanation": "量词用错。“名”用“个”计量，不用“张”（“张”用于纸张等）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86057, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字，与姓相对的人名。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字，与姓相对的人名。", "情": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。", "形": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。", "晴": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指考试或学习的结果，不是可以起的名称。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“他的名是爷爷给起的”指名字由爷爷取。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不是可以由人取的称呼。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的形状，不是可以起的称呼。"}], "explanations": {"成绩": "语义：“成绩”指考试或学习的结果，不是可以起的名称。", "名": "正确答案。“他的名是爷爷给起的”指名字由爷爷取。", "脾气": "语义：脾气是性格特点，不是可以由人取的称呼。", "身材": "体貌：“身材”指身体的形状，不是可以起的称呼。"}, "sentence_index": 6, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她获得了“最佳员工”的名。", "explanation": "这里应该用〈称号〉。获得荣誉的头衔要说称号，名指人的称呼。"}, {"text": "大家都叫她林老师，这是对她的名。", "explanation": "这里应该用〈称呼〉。“林老师”是称呼，名指名字，不能用来说称呼。"}, {"text": "这个班只有五个名，我没抢到。", "explanation": "这里应该用〈名额〉。“五个名”不能表示班里的人数限额，应说“五个名额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我起了一只名，很有意义。", "corrected_sentence": "奶奶给我起了一个名，很有意义。", "error_description": "“名”的量词应用“个”，不用“只”（“只”多用于动物）。应说“起了一个名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外婆给我起名很好听。", "corrected_sentence": "外婆给我起的名很好听。", "error_description": "“名”前面要有定语“起的”，应说“外婆给我起的名”，不能省掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
