INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名字，人或事物的称呼。", "primary_collocate": null, "pronunciation": "míng", "ipa": "miŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我想给小狗起个名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的名很好记。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想给新公司起个什么名？", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给孩子起个好名并不容易。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名听起来很好听。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给孩子换了个名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的名很特别。", "target_word": "名", "complexity_tier": "T3", "furigana": "zhè bù diànyǐng de míng hěn tèbié", "sentence_source": "generated"}, {"text": "这个名我不太喜欢。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给自己的小猫起了一个可爱的名。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名太长了，不好记。", "target_word": "名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名字", "label": "复合"}, {"form": "名称", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，人或事物的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字、称呼。"}, {"text": "命", "is_correct": false, "explanation": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。"}, {"text": "民", "is_correct": false, "explanation": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。"}, {"text": "平", "is_correct": false, "explanation": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 míng 声母不同（l 与 m），意思是零、没有。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字、称呼。", "命": "mìng（第四声）与 míng（第二声）声调不同，意思是生命、命令。", "民": "mín（第二声）与 míng 韵母不同（-n 与 -ng），意思是人民。", "平": "píng（第二声）与 míng 声母不同（p 与 m），意思是平安、平坦。", "停": "tíng（第二声）与 míng 声母不同（t 与 m），意思是停止。", "零": "líng（第二声）与 míng 声母不同（l 与 m），意思是零、没有。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "搭配：“起”说的是给事物取名字，不能说给小狗起玩具。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“起个名”指给小狗取一个称呼。"}, {"text": "项圈", "is_correct": false, "explanation": "语义：项圈是戴在脖子上的东西，不是可以起的称呼。"}, {"text": "狗窝", "is_correct": false, "explanation": "搭配：“起”不用于搭建窝，要说“搭”或“买”狗窝。"}], "explanations": {"玩具": "搭配：“起”说的是给事物取名字，不能说给小狗起玩具。", "名": "正确答案。“起个名”指给小狗取一个称呼。", "项圈": "语义：项圈是戴在脖子上的东西，不是可以起的称呼。", "狗窝": "搭配：“起”不用于搭建窝，要说“搭”或“买”狗窝。"}, "sentence_index": 0, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一个名，大家都笑了。", "explanation": "这里应该用〈笑话〉。名指人或事物的称呼，不能指讲出来逗人笑的故事，“讲”要搭配“笑话”。"}, {"text": "班上的名贴在墙上。", "explanation": "这里应该用〈名单〉。名指称呼，不指写着名字的单子，贴在墙上的要说名单。"}, {"text": "这本名很特别。", "explanation": "量词用错。名不用“本”来计量（“本”用于书籍），应说“这个名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名", "is_correct": true, "explanation": "正确答案。míng（第二声），意思是名字、称呼。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}], "explanations": {"名": "正确答案。míng（第二声），意思是名字、称呼。", "情": "qíng（第二声）与 míng 声母不同（q 与 m），意思是感情。", "形": "xíng（第二声）与 míng 声母不同（x 与 m），意思是形状。", "晴": "qíng（第二声）与 míng 声母不同（q 与 m），意思是天气晴朗。"}, "sentence_index": null, "correct_answer": "名"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的高矮，不能用来形容电影。"}, {"text": "名", "is_correct": true, "explanation": "正确答案。“电影的名”指电影的名称。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，电影没有身材。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不能用于电影。"}], "explanations": {"身高": "搭配：“身高”指人的高矮，不能用来形容电影。", "名": "正确答案。“电影的名”指电影的名称。", "身材": "体貌：“身材”指人的体形，电影没有身材。", "体重": "搭配：“体重”指人或动物的重量，不能用于电影。"}, "sentence_index": 6, "correct_answer": "名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他获得了“最佳员工”的名。", "explanation": "这里应该用〈称号〉。获得荣誉的头衔要说称号，名指人或事物的称呼。"}, {"text": "这家店起了一扇名，很好记。", "explanation": "量词用错。“名”用“个”计量，不用“扇”（“扇”用于门窗）。"}, {"text": "这次比赛只有十张名。", "explanation": "量词用错。“名”用“个”计量，不用“张”（“张”用于纸张等）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我起了一只好听的名。", "corrected_sentence": "妈妈给我起了一个好听的名。", "error_description": "“名”的量词应用“个”，不能用“只”（“只”多用于动物）。应说“起了一个好听的名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
