INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86061, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“本”用来数书和本子，比如一本书。", "primary_collocate": null, "pronunciation": "běn", "ipa": "pən˨˩˦", "syllable_count": 1, "sentences": [{"text": "我买了三本书。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一本字典。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说很好看。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借了两本漫画。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月看四本书。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们每人一本书。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志你看过吗？", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上有几本旧书。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在读一本关于中国的书。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这本书还给图书馆。", "target_word": "本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本本", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，数书、本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86061, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本", "is_correct": true, "explanation": "正确：běn，量词“本”，用于书、本子"}, {"text": "奔", "is_correct": false, "explanation": "bēn（第一声）与 běn 声调不同，意思是奔跑"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 běn 声调不同，意思是笨拙"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 běn 韵母不同（-an 与 -en），意思是木板"}], "explanations": {"本": "正确：běn，量词“本”，用于书、本子", "奔": "bēn（第一声）与 běn 声调不同，意思是奔跑", "笨": "bèn（第四声）与 běn 声调不同，意思是笨拙", "板": "bǎn 与 běn 韵母不同（-an 与 -en），意思是木板"}, "sentence_index": null, "correct_answer": "本"}, "level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "正确：“本”用于书，“我买了三本书”"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物和成对东西中的一个，不能数书"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的东西，不能数书"}, {"text": "块", "is_correct": false, "explanation": "语义：“块”指成块的东西，不指书册"}], "explanations": {"本": "正确：“本”用于书，“我买了三本书”", "只": "搭配：“只”用于动物和成对东西中的一个，不能数书", "把": "搭配：“把”用于有柄的东西，不能数书", "块": "语义：“块”指成块的东西，不指书册"}, "sentence_index": 0, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家装了一本窗户。", "explanation": "这里应该用〈扇〉。窗户用“扇”来数，“本”用于书籍、本子"}, {"text": "他写了一本文章。", "explanation": "这里应该用〈篇〉。“篇”用于文章、论文，“本”用于装订成册的书"}, {"text": "他戴着一本手表。", "explanation": "这里应该用〈块〉。手表用“块”来数，“本”用于书籍、本子"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86061, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本", "is_correct": true, "explanation": "正确：běn，量词“本”，用于书、本子"}, {"text": "粉", "is_correct": false, "explanation": "fěn 与 běn 声母不同（f 与 b），意思是粉末"}, {"text": "很", "is_correct": false, "explanation": "hěn 与 běn 声母不同（h 与 b），意思是很"}, {"text": "版", "is_correct": false, "explanation": "bǎn 与 běn 韵母不同（-an 与 -en），意思是版本"}], "explanations": {"本": "正确：běn，量词“本”，用于书、本子", "粉": "fěn 与 běn 声母不同（f 与 b），意思是粉末", "很": "hěn 与 běn 声母不同（h 与 b），意思是很", "版": "bǎn 与 běn 韵母不同（-an 与 -en），意思是版本"}, "sentence_index": null, "correct_answer": "本"}, "level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "正确：“本”用于书，“这本杂志”"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能数杂志"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于画等平面的东西，不能数杂志"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”指诗、歌，不指杂志"}], "explanations": {"本": "正确：“本”用于书，“这本杂志”", "辆": "搭配：“辆”用于车辆，不能数杂志", "幅": "搭配：“幅”用于画等平面的东西，不能数杂志", "首": "语义：“首”指诗、歌，不指杂志"}, "sentence_index": 6, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有五本房子。", "explanation": "这里应该用〈套〉。房子用“套”来数，“本”用于书册"}, {"text": "我每天买一本报纸。", "explanation": "这里应该用〈份〉。报纸用“份”来数，“本”用于书籍、本子"}, {"text": "妈妈做了一本鱼。", "explanation": "这里应该用〈条〉。鱼用“条”来数，“本”用于书籍、本子"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了两个本练习册。", "corrected_sentence": "她买了两本练习册。", "error_description": "量词叠用。数词“两”后已有量词“本”，不能再加“个”，应为“两本练习册”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想借一本本杂志。", "corrected_sentence": "我想借一本杂志。", "error_description": "量词叠用。“本”后不能再重复一个“本”，应为“一本杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
