INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86063, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "投票是大家在纸上写下想选的人或事，放进箱子里。", "primary_collocate": null, "pronunciation": "tóu piào", "ipa": "tʰoʊ˧˥ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "同学们在纸上写下名字，然后去投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们排好队，一个一个地走到箱子前投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发了小纸条，请大家写好后投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上写下班长的名字，再去投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天上午，全班同学都要在教室投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把纸条折好，到前面的箱子那里投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选班花的时候，同学们用小纸条投票。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我们写下想去的地方，再投票决定。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票以前，请先在纸上写好你的选择。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸放进箱子里，投票就结束了。", "target_word": "投票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投了票", "label": "体标（了）"}, {"form": "投过票", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "在纸上写下选择，放进箱子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投票", "is_correct": true, "explanation": "正确：“去投票”指在纸上写下选择后投进箱子，与前句的“写下名字”相呼应。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”指停止抵抗、认输，与选举场景不符。"}, {"text": "投篮", "is_correct": false, "explanation": "语义：“投篮”指把球投进篮筐，与纸条和箱子无关。"}, {"text": "投影", "is_correct": false, "explanation": "搭配：“投影”指把影像投射到屏幕或墙上，不用于写纸条、投进箱子的场景。"}], "explanations": {"投票": "正确：“去投票”指在纸上写下选择后投进箱子，与前句的“写下名字”相呼应。", "投降": "语义：“投降”指停止抵抗、认输，与选举场景不符。", "投篮": "语义：“投篮”指把球投进篮筐，与纸条和箱子无关。", "投影": "搭配：“投影”指把影像投射到屏幕或墙上，不用于写纸条、投进箱子的场景。"}, "sentence_index": 0, "correct_answer": "投票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他投票投进了篮筐里。", "explanation": "这里应该用〈投篮〉。“投票”指在纸上写下选择后放进箱子，不能指把球投进篮筐。"}, {"text": "他投票投得很远。", "explanation": "这里应该用〈扔〉。“投票”只指选举时表达意愿，不能指把东西抛向远处。"}, {"text": "他投票很准。", "explanation": "这里应该用〈投篮〉。“投票”不能用于投球，投球要说“投篮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投票", "is_correct": true, "explanation": "正确：“用小纸条投票”指写好选择后投进箱子，与“选班花”的语境相符。"}, {"text": "投稿", "is_correct": false, "explanation": "语义：“投稿”指把文章寄给报刊，与选班花的情境不符。"}, {"text": "投标", "is_correct": false, "explanation": "语义：“投标”指参加竞标，与用小纸条选人的情境不符。"}, {"text": "投射", "is_correct": false, "explanation": "语域：“投射”偏书面和专业，口语叙述“用小纸条……”中不用。"}], "explanations": {"投票": "正确：“用小纸条投票”指写好选择后投进箱子，与“选班花”的语境相符。", "投稿": "语义：“投稿”指把文章寄给报刊，与选班花的情境不符。", "投标": "语义：“投标”指参加竞标，与用小纸条选人的情境不符。", "投射": "语域：“投射”偏书面和专业，口语叙述“用小纸条……”中不用。"}, "sentence_index": 6, "correct_answer": "投票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把纸团投票进了纸篓。", "explanation": "这里不能用〈投票〉。“投票”只指选举或表决时表达意愿，此处是把纸团丢进纸篓的动作，与选举无关。"}, {"text": "我把信投票进了信箱。", "explanation": "这里不能用〈投票〉。“投票”只用于选举或表决，此处是把信件放进信箱，与选举无关。"}, {"text": "他把钱投票到了股市里。", "explanation": "这里不能用〈投票〉。此处是把钱用于获利，与选举或表决无关，“投票”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天投票了票。", "corrected_sentence": "我昨天投了票。", "error_description": "“投票”是离合词，中间可插入“了”，宾语“票”已包含在“投票”中，不能再加“票”。应说“投了票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天都投票他了。", "corrected_sentence": "我们昨天都投票给他了。", "error_description": "“投票”是不及物的离合词，不能直接带人作宾语，指人时要在前面加“给”，应说“投票给他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
