INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86069, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“一点”是说很少很少的一些。", "primary_collocate": null, "pronunciation": "yì diǎn", "ipa": "i˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "我只会说一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤太多了，我只喝了一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碗里就剩一点了。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这件事，我只知道一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你饿吗？我只想吃一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕很好吃，请给我留一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，只吃了一点就睡了。", "target_word": "一点", "complexity_tier": "T3", "furigana": "tā tài lèi le, zhǐ chī le yì diǎn jiù shuì le.", "sentence_source": "generated"}, {"text": "我的钱不多，只能花一点。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我懂一点，但不太多。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜太辣了，我只敢吃一点。", "target_word": "一点", "complexity_tier": "T3", "furigana": "zhè ge cài tài là le, wǒ zhǐ gǎn chī yì diǎn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "单独作宾语：指很少的一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86069, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确答案。“一点”指很少的一些。"}, {"text": "一脸", "is_correct": false, "explanation": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。"}, {"text": "一眼", "is_correct": false, "explanation": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。"}, {"text": "衣店", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，意思是卖衣服的店。"}], "explanations": {"一点": "正确答案。“一点”指很少的一些。", "一脸": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。", "一眼": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。", "衣店": "diàn（第四声）与 diǎn（第三声）声调不同，意思是卖衣服的店。"}, "sentence_index": null, "correct_answer": "一点"}, "level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“只会说一点”表示懂得很少，与“只”呼应。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”与“只”意思相反，“只会说全部”前后矛盾。"}, {"text": "所有", "is_correct": false, "explanation": "搭配：“会说”一般接具体的语言，不接“所有”，且“所有”与“只”矛盾。"}, {"text": "一切", "is_correct": false, "explanation": "语义：“一切”指全部，与“只”的限定意思冲突。"}], "explanations": {"一点": "正确：“只会说一点”表示懂得很少，与“只”呼应。", "全部": "语义：“全部”与“只”意思相反，“只会说全部”前后矛盾。", "所有": "搭配：“会说”一般接具体的语言，不接“所有”，且“所有”与“只”矛盾。", "一切": "语义：“一切”指全部，与“只”的限定意思冲突。"}, "sentence_index": 0, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一点笔。", "explanation": "这里应该用〈一支〉。“一点”只修饰少量的不可数事物；“笔”是可数的，要用量词“支”计数，说“一支笔”。"}, {"text": "这栋楼一点高，有五十层。", "explanation": "这里应该用〈很〉。“一点”表示少量，不用来形容很高的楼房，要说“很高”。"}, {"text": "这次作业班上一点学生没交，老师很生气。", "explanation": "这里应该用〈几名〉。“一点”不能修饰表示人的可数名词“学生”，要用“几名”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“只吃了一点”表示吃得很少，与“太累”和“只”呼应。"}, {"text": "很多", "is_correct": false, "explanation": "搭配：“只吃了”后接“很多”，与“只”冲突，前后语义不一致。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”与“只”冲突，“只吃了全部”前后矛盾。"}, {"text": "好多", "is_correct": false, "explanation": "语义：“好多”表示数量很大，与“只吃了”的少量含义相反。"}], "explanations": {"一点": "正确：“只吃了一点”表示吃得很少，与“太累”和“只”呼应。", "很多": "搭配：“只吃了”后接“很多”，与“只”冲突，前后语义不一致。", "全部": "语义：“全部”与“只”冲突，“只吃了全部”前后矛盾。", "好多": "语义：“好多”表示数量很大，与“只吃了”的少量含义相反。"}, "sentence_index": 6, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一点两本书，我全都看完了。", "explanation": "这里应该用〈两本〉。“一点”表示不定的少量，不能与具体数量“两本”同时修饰“书”，去掉“一点”即可。"}, {"text": "我昨天吃了一点很多饭，撑得不行。", "explanation": "这里应该用〈很多〉或〈一点〉二选一。“一点”表示少量，与“很多”的多量意思相反，不能同时使用。"}, {"text": "我买了一点只鸡。", "explanation": "这里应该用〈只〉。“一点”不能充当量词，“鸡”要用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只喝了汤一点。", "corrected_sentence": "他只喝了一点。", "error_description": "语序错误：“一点”单独作宾语时，前面不能加名词“汤”，应说“他只喝了一点”，“汤一点”不成话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喝了一点个汤就出门了。", "corrected_sentence": "我喝了一点汤就出门了。", "error_description": "量词错误：“一点”表示不定的少量，后面不能再直接加量词“个”，应说“喝了一点汤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
