INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示少量，不多。", "primary_collocate": null, "pronunciation": "yì diǎn", "ipa": "i˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "杯子里只有一点水。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一点时间。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会说一点中文。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有一点牛奶。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天只吃了一点米饭。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在汤里放一点盐。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上只剩一点面包了。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请再给我一点糖。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点问题想问老师。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只有一点时间了。", "target_word": "一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "数量词：修饰名词，表示少量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确答案。“一点”表示少量。"}, {"text": "一脸", "is_correct": false, "explanation": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。"}, {"text": "一眼", "is_correct": false, "explanation": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。"}, {"text": "衣店", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，意思是卖衣服的店。"}], "explanations": {"一点": "正确答案。“一点”表示少量。", "一脸": "liǎn（第三声）与 diǎn（第三声）只差声母 l 和 d，意思是“满脸”，不表示少量。", "一眼": "yǎn 与 diǎn 只差声母（有无 d），意思是“看一下”，与少量无关。", "衣店": "diàn（第四声）与 diǎn（第三声）声调不同，意思是卖衣服的店。"}, "sentence_index": null, "correct_answer": "一点"}, "level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“杯子里只有一点水”表示水很少，与“只有”呼应。"}, {"text": "很多", "is_correct": false, "explanation": "语义：“很多”与“只有”矛盾，不符合句意。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量水”与“只有”及杯子的容量不协调，前后矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”与“只有”意思相反，不符合句意。"}], "explanations": {"一点": "正确：“杯子里只有一点水”表示水很少，与“只有”呼应。", "很多": "语义：“很多”与“只有”矛盾，不符合句意。", "大量": "搭配：“大量水”与“只有”及杯子的容量不协调，前后矛盾。", "全部": "语义：“全部”与“只有”意思相反，不符合句意。"}, "sentence_index": 0, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一点本子。", "explanation": "这里应该用〈几本〉。“一点”只修饰少量的不可数事物，“本子”是可数的，要用量词“本”计数。"}, {"text": "这栋楼一点高，有五十层。", "explanation": "这里应该用〈很〉。“一点”表示少量，不用来形容很高的楼房，要说“很高”。"}, {"text": "我家养了一点三只猫。", "explanation": "这里应该用〈三只〉。“一点”表示不定的少量，不能与具体数量“三只”同时修饰“猫”，去掉“一点”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一点", "is_correct": true, "explanation": "正确：“桌上只剩一点面包了”表示剩下的很少，与“只剩”呼应。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”与“只剩”冲突，“只剩全部”前后矛盾。"}, {"text": "许多", "is_correct": false, "explanation": "语义：“许多”表示数量多，与“只剩”的少量含义相反。"}, {"text": "所有", "is_correct": false, "explanation": "搭配：“只剩”后接“所有”，语义冲突，前后不一致。"}], "explanations": {"一点": "正确：“桌上只剩一点面包了”表示剩下的很少，与“只剩”呼应。", "全部": "语义：“全部”与“只剩”冲突，“只剩全部”前后矛盾。", "许多": "语义：“许多”表示数量多，与“只剩”的少量含义相反。", "所有": "搭配：“只剩”后接“所有”，语义冲突，前后不一致。"}, "sentence_index": 6, "correct_answer": "一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想吃一点一个苹果。", "explanation": "这里应该用〈一个〉。“一点”表示不定的少量，不能与具体数量“一个”同时修饰“苹果”，应说“一个苹果”。"}, {"text": "这个菜一点辣。", "explanation": "这里应该用〈有点〉。“一点”不能直接作谓语修饰形容词，要说“有点辣”。"}, {"text": "我买了一点只鸡。", "explanation": "这里应该用〈只〉。“一点”不能充当量词，“鸡”要用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子里只有一个果汁。", "corrected_sentence": "杯子里只有一点果汁。", "error_description": "量词错误：「果汁」是液体，不可数，不能用量词「个」计量；「一个果汁」不通，应说「一点果汁」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上只有一点个蛋糕。", "corrected_sentence": "桌上只有一点蛋糕。", "error_description": "量词错误：“一点”表示不定的少量，本身不是数量结构，后面不能再加量词“个”，应说“一点蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和睦", "is_correct": true, "explanation": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。"}, {"text": "香甜", "is_correct": false, "explanation": "“香甜”形容味道或睡眠，与“不和”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“不和”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容物体坚固或人体健壮，与“不和”没有反义关系。"}], "correct_answer": "和睦", "explanations": {"和睦": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。", "香甜": "“香甜”形容味道或睡眠，与“不和”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“不和”没有反义关系。", "结实": "“结实”形容物体坚固或人体健壮，与“不和”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和睦", "is_correct": true, "explanation": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作或做法敏捷、不呆板，与“不和”没有反义关系。"}, {"text": "冷清", "is_correct": false, "explanation": "“冷清”形容场所没有人气，与“不和”没有反义关系。"}, {"text": "圆滑", "is_correct": false, "explanation": "“圆滑”形容处世手法老练，与“不和”没有反义关系。"}], "correct_answer": "和睦", "explanations": {"和睦": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。", "灵活": "“灵活”形容动作或做法敏捷、不呆板，与“不和”没有反义关系。", "冷清": "“冷清”形容场所没有人气，与“不和”没有反义关系。", "圆滑": "“圆滑”形容处世手法老练，与“不和”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“不和”是说两个人关系不好，常常吵架。", "primary_collocate": null, "pronunciation": "bù hé", "ipa": "pu⁵¹ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "他们俩不和，一见面就吵架。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李不和，常常吵起来。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈最近不和，常常吵架。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个邻居不和多年，从不来往。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和室友不和，每天都吵。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐妹俩不和，为了小事吵了一晚上。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不和的事，全公司都知道。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他们两口子不和，总是大声吵。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为钱的事，兄弟两人不和了。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都知道他和老板不和。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不和：两人关系不好，常吵架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea339396-6baf-4360-8d3a-df8539a24aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指两人关系不好、常吵架，与后句“一见面就吵架”相呼应。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”说关系好，与后句“一见面就吵架”矛盾。"}, {"text": "亲密", "is_correct": false, "explanation": "语义：“亲密”说关系很近，与“一见面就吵架”矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "体貌：“安静”形容神态或环境，不能说两人关系，且与“吵架”矛盾。"}], "explanations": {"不和": "“不和”指两人关系不好、常吵架，与后句“一见面就吵架”相呼应。", "友好": "语义：“友好”说关系好，与后句“一见面就吵架”矛盾。", "亲密": "语义：“亲密”说关系很近，与“一见面就吵架”矛盾。", "安静": "体貌：“安静”形容神态或环境，不能说两人关系，且与“吵架”矛盾。"}, "sentence_index": 0, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的大小不和我的脚。", "explanation": "这里应该用〈不合〉。“不和”说人与人之间合不来；鞋的大小与脚是否相合要用“不合”。"}, {"text": "这两份报告的数据互相不和。", "explanation": "这里应该用〈矛盾〉。“不和”说人际关系不好；数据之间的抵触要用“矛盾”。"}, {"text": "这个决定不和，需要重新考虑。", "explanation": "这里应该用〈不妥〉。“不和”只形容人际关系；决定是否恰当要用“不妥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指关系不好，用作定语修饰“的事”，与“全公司都知道”相呼应。"}, {"text": "隐蔽", "is_correct": false, "explanation": "语义：“隐蔽”指不让人看见，与“全公司都知道”矛盾。"}, {"text": "隐秘", "is_correct": false, "explanation": "语义：“隐秘”指不公开，与“全公司都知道”矛盾。"}, {"text": "偏僻", "is_correct": false, "explanation": "搭配：“偏僻”形容地方，不能修饰“事”。"}], "explanations": {"不和": "“不和”指关系不好，用作定语修饰“的事”，与“全公司都知道”相呼应。", "隐蔽": "语义：“隐蔽”指不让人看见，与“全公司都知道”矛盾。", "隐秘": "语义：“隐秘”指不公开，与“全公司都知道”矛盾。", "偏僻": "搭配：“偏僻”形容地方，不能修饰“事”。"}, "sentence_index": 6, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很不和，大家都躲着他。", "explanation": "这里应该用〈不友好〉。“不和”说的是人与人之间合不来，不能直接用来形容脾气；脾气恶劣要用“不友好”。"}, {"text": "这个方案的预算很不和，需要重新核算。", "explanation": "这里应该用〈不合理〉。“不和”只形容人与人之间的关系；预算是否恰当要用“不合理”。"}, {"text": "这个数字很不和，需要核对。", "explanation": "这里应该用〈不准确〉。“不和”只形容人与人之间的关系，不能用来形容数字；数字是否准确要用“不准确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和室友了不和，但是我们都很忍让。", "corrected_sentence": "我和室友不和，但是我们都很忍让。", "error_description": "错误形式：“不和”前多加了“了”。“不和”前不能加“了”，这里只是说明两人关系不好，应说“我和室友不和”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板和我了不和，所以我换了工作。", "corrected_sentence": "老板和我不和，所以我换了工作。", "error_description": "“了”不能放在“不和”前，“了不和”不成词。去掉“了”即可（老板和我不和），也可说“老板和我不和了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和睦", "is_correct": true, "explanation": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“不和”的人际关系义没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容卫生状况，与“不和”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价格低，与“不和”没有反义关系。"}], "correct_answer": "和睦", "explanations": {"和睦": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。", "聪明": "“聪明”形容人的智力，与“不和”的人际关系义没有反义关系。", "干净": "“干净”形容卫生状况，与“不和”没有反义关系。", "便宜": "“便宜”形容价格低，与“不和”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和睦", "is_correct": true, "explanation": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容事理明白，与“不和”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“不和”的人际关系义没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度庄重，与“不和”没有反义关系。"}], "correct_answer": "和睦", "explanations": {"和睦": "“和睦”指关系融洽，与“不和”（关系不好）意思相反，是该义项的反义词。", "清楚": "“清楚”形容事理明白，与“不和”没有反义关系。", "高兴": "“高兴”形容心情愉快，与“不和”的人际关系义没有反义关系。", "严肃": "“严肃”形容态度庄重，与“不和”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指彼此感情不好，合不来。", "primary_collocate": null, "pronunciation": "bù hé", "ipa": "pu⁵¹ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "他们两个人一直不和。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对夫妻不和，常常分开住。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和姐姐从小就不和。", "target_word": "不和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家人因为一件小事不和了。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们不和，工作很难做好。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，家里不和，孩子也不开心。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居不和，见面也不说话。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现两个同学不和。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩曾经不和过一阵子，现在很好。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里领导不和，大家都很担心。", "target_word": "不和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不和：彼此感情不好，合不来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea339396-6baf-4360-8d3a-df8539a24aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指彼此感情不好、合不来，与“一直”搭配，说明关系长期如此。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面人多、喧闹，不能用来描述两个人之间的关系。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多、空间窄，不能用来形容“两个人”的关系。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容地方没有人或物，与“他们两个人”的关系无关。"}], "explanations": {"不和": "“不和”指彼此感情不好、合不来，与“一直”搭配，说明关系长期如此。", "热闹": "语义：“热闹”形容场面人多、喧闹，不能用来描述两个人之间的关系。", "拥挤": "搭配：“拥挤”说人多、空间窄，不能用来形容“两个人”的关系。", "空旷": "语义：“空旷”形容地方没有人或物，与“他们两个人”的关系无关。"}, "sentence_index": 0, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套的尺寸不和我的身材。", "explanation": "这里应该用〈不合〉。“不和”说人与人之间合不来；衣服尺寸与身材是否相合要用“不合”。"}, {"text": "他们俩的说法互相不和。", "explanation": "这里应该用〈矛盾〉。“不和”说人际关系不好；说法之间互相抵触要用“矛盾”。"}, {"text": "这台电脑的零件和主板不和，装不上。", "explanation": "这里应该用〈不合〉。“不和”只形容人与人之间合不来；零件是否相合要用“不合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不和", "is_correct": true, "explanation": "“不和”指两人关系不好，与后句“见面也不说话”相呼应。"}, {"text": "亲密", "is_correct": false, "explanation": "语义：“亲密”指关系很近，与后句“见面也不说话”矛盾。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”指感情好、往来多，与“见面也不说话”矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容对人的态度，常说“对…热情”，不说“和…热情”。"}], "explanations": {"不和": "“不和”指两人关系不好，与后句“见面也不说话”相呼应。", "亲密": "语义：“亲密”指关系很近，与后句“见面也不说话”矛盾。", "亲近": "语义：“亲近”指感情好、往来多，与“见面也不说话”矛盾。", "热情": "搭配：“热情”形容对人的态度，常说“对…热情”，不说“和…热情”。"}, "sentence_index": 6, "correct_answer": "不和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的态度很不和，别人都不喜欢他。", "explanation": "这里应该用〈不友好〉。“不和”说的是人与人之间合不来，不能直接用来形容态度；态度恶劣要用“不友好”。"}, {"text": "这个箱子和门不和，关不上。", "explanation": "这里应该用〈不合〉。“不和”只形容人与人之间合不来；箱子与门是否相合要用“不合”。"}, {"text": "这个办法不和，需要修改。", "explanation": "这里应该用〈不妥〉。“不和”只形容人际关系，办法是否恰当要用“不妥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩一直不不和，见面就吵。", "corrected_sentence": "他们俩一直不和，见面就吵。", "error_description": "「不和」前多写了一个「不」，构成双重否定，意思与「不和」相反，也与后句「见面就吵」矛盾；删去多余的「不」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和邻居不和着，所以不再一起吃饭。", "corrected_sentence": "他和邻居不和了，所以不再一起吃饭。", "error_description": "“不和”后应用“了”表示关系已经变坏，写成“不和着”是体标用错，应改为“不和了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9030264-244c-49e4-963a-6887d9612926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
