INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86077, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "某些是说有一些，但不说是哪几个。", "primary_collocate": null, "pronunciation": "mǒu xiē", "ipa": "mou˨˩˦ ɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "我们班某些同学会说法语。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些菜太辣，我不能吃。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天某些客人没有来。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事只有某些人知道。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里某些花已经开了。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些歌我听了很多次。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只想问他某些事情。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些动物晚上才出来找吃的。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月某些天会下雨。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些衣服要用手洗。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有一些，但不说是哪几个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”指班里不确定的一部分同学，符合句意。"}, {"text": "某个", "is_correct": false, "explanation": "语义：“某个”指单个不确定的人，与句中指几位同学的意思不符。"}, {"text": "这些", "is_correct": false, "explanation": "语义：“这些”指说话双方都清楚的具体几位同学，与“某些”的不确定义冲突。"}, {"text": "其余", "is_correct": false, "explanation": "配价：“其余”要以已知的全班同学为前提，句中没有前文，无法构成“班里其余同学”。"}], "explanations": {"某些": "正确：“某些”指班里不确定的一部分同学，符合句意。", "某个": "语义：“某个”指单个不确定的人，与句中指几位同学的意思不符。", "这些": "语义：“这些”指说话双方都清楚的具体几位同学，与“某些”的不确定义冲突。", "其余": "配价：“其余”要以已知的全班同学为前提，句中没有前文，无法构成“班里其余同学”。"}, "sentence_index": 0, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班某些同学是李明和王芳。", "explanation": "这里应该去掉“某些”，直接说具体的人。“某些”只指不确定的一部分，不能说是哪几个，后面也不能列出具体名字。"}, {"text": "这件事只有某些人知道，也就是全公司的所有人。", "explanation": "这里应该用〈全体〉。“某些”只指不确定的一部分，与“也就是全公司的所有人”指全体的说法矛盾。"}, {"text": "我们班某些人是班长。", "explanation": "这里应该用〈一个人〉。“某些人”指几个不确定的人，不能指一个特定身份的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”表示不确定的一部分事情，符合“只想问他”的语境。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指所有事情，与“只想问”的部分意思冲突。"}, {"text": "每件", "is_correct": false, "explanation": "搭配：“每件”要求逐一，与“只想问他”的少量意思不搭配。"}, {"text": "整件", "is_correct": false, "explanation": "搭配：“整件”指一整件，不能修饰表示不确定数量的“事情”。"}], "explanations": {"某些": "正确：“某些”表示不确定的一部分事情，符合“只想问他”的语境。", "全部": "语义：“全部”指所有事情，与“只想问”的部分意思冲突。", "每件": "搭配：“每件”要求逐一，与“只想问他”的少量意思不搭配。", "整件": "搭配：“整件”指一整件，不能修饰表示不确定数量的“事情”。"}, "sentence_index": 6, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某些衣服正好三件，要用手洗。", "explanation": "这里应该去掉“正好三件”。“某些”不说具体数量，与精确的数量矛盾。"}, {"text": "某些衣服是这件外套。", "explanation": "这里应该用〈这件衣服〉。“某些”指不确定的一部分，不能指明是哪一件。"}, {"text": "某些衣服是唯一一件要用手洗的。", "explanation": "这里应该去掉“唯一一件”。“某些”表示不确定的几件，不能与特指一件的说法并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试某些三道题很难。", "corrected_sentence": "这次考试某些题很难。", "error_description": "“某些”表示不确定的一部分，修饰名词时前面不能再加具体数量。错误形式是“某些三道题”，正确形式是“某些题”。正确句：这次考试某些题很难。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "某些的菜我不太喜欢吃。", "corrected_sentence": "某些菜我不太喜欢吃。", "error_description": "“某些”后面直接接名词，不能加“的”。错误形式是“某些的菜”，正确形式是“某些菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
