INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指不确定的少数。", "primary_collocate": null, "pronunciation": "mǒu xiē", "ipa": "mou˨˩˦ ɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "某些人喜欢早上跑步。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店某些东西很贵。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些问题老师现在还不能回答。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些时候，我也会觉得很累。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只喜欢某些颜色。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些地方冬天不下雪。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里某些句子我看不懂。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些学生每天都迟到。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些水果在冬天很便宜。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某些国家的人喜欢喝茶。", "target_word": "某些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指示代词，指不确定的少数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id 