INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”指不确定的一部分人，符合句意。"}, {"text": "某个", "is_correct": false, "explanation": "语义：“某个”指单个不确定的人，与句中指几类人的“某些人”不符。"}, {"text": "这些", "is_correct": false, "explanation": "语义：“这些”指说话双方都清楚的具体一群人，与“某些”的不确定义冲突。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个人”指逐一的全体，与表示一部分的“某些人”意思相反。"}], "explanations": {"某些": "正确：“某些”指不确定的一部分人，符合句意。", "某个": "语义：“某个”指单个不确定的人，与句中指几类人的“某些人”不符。", "这些": "语义：“这些”指说话双方都清楚的具体一群人，与“某些”的不确定义冲突。", "每个": "语义：“每个人”指逐一的全体，与表示一部分的“某些人”意思相反。"}, "sentence_index": 0, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班某些同学是王明和李华。", "explanation": "这里应该去掉“某些”，直接说具体的人。“某些”只指不确定的一部分，不能说是哪几个，后面也不能列出具体名字。"}, {"text": "某些同学全部到齐了，我们班一共三十人。", "explanation": "这里应该用〈所有〉。“某些”表示不确定的一部分，与“全部到齐”和“一共三十人”指全体的说法矛盾。"}, {"text": "某些人是我的弟弟。", "explanation": "这里应该用〈这个〉。“某些人”指几个不确定的人，不能指一个特定的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某些", "is_correct": true, "explanation": "正确：“某些”指书中不确定的一部分句子，符合句意。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指所有句子，与“某些”表示一部分的意思冲突。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指单个特定的一个，不能修饰多个句子中不确定的一部分。"}, {"text": "其余", "is_correct": false, "explanation": "配价：“其余”要以已知的全体为前提，句中没有前文，无法构成“书里其余句子”。"}], "explanations": {"某些": "正确：“某些”指书中不确定的一部分句子，符合句意。", "全部": "语义：“全部”指所有句子，与“某些”表示一部分的意思冲突。", "这个": "语义：“这个”指单个特定的一个，不能修饰多个句子中不确定的一部分。", "其余": "配价：“其余”要以已知的全体为前提，句中没有前文，无法构成“书里其余句子”。"}, "sentence_index": 6, "correct_answer": "某些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某些国家的人正好三个，我都认识。", "explanation": "这里应该去掉“正好三个”。“某些”不说具体数量，与精确的数量矛盾。"}, {"text": "某些国家是中国，它在亚洲。", "explanation": "这里应该用〈这个国家〉。“某些”指不确定的一部分，不能指明某一个国家。"}, {"text": "某些国家是唯一一个喜欢喝茶的。", "explanation": "这里应该去掉“唯一一个”。“某些”表示不确定的几个，不能与特指一个的说法并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "某些的同学今天没来上课。", "corrected_sentence": "某些同学今天没来上课。", "error_description": "“某些”是代词，后面直接接名词，不能加“的”。错误形式是“某些的同学”，正确形式是“某些同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "某些三个学生都迟到了。", "corrected_sentence": "某些学生都迟到了。", "error_description": "“某些”表示不确定的一部分，后面不能再加具体数量。错误形式是“某些三个学生”，正确形式是“某些学生”。正确句：某些学生都迟到了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浑", "is_correct": true, "explanation": "反义：“清”指水干净见底，反义是“浑”，即水浑浊。"}, {"text": "甜", "is_correct": false, "explanation": "无反义关系：“甜”说味道，与“清”的见底义没有对立。"}, {"text": "快", "is_correct": false, "explanation": "无反义关系：“快”说速度，与“清”没有对应关系。"}, {"text": "重", "is_correct": false, "explanation": "无反义关系：“重”说重量，与“清”没有对立。"}], "correct_answer": "浑", "explanations": {"浑": "反义：“清”指水干净见底，反义是“浑”，即水浑浊。", "甜": "无反义关系：“甜”说味道，与“清”的见底义没有对立。", "快": "无反义关系：“快”说速度，与“清”没有对应关系。", "重": "无反义关系：“重”说重量，与“清”没有对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浑", "is_correct": true, "explanation": "反义：“清”指水干净见底，反义是“浑”，即水浑浊。"}, {"text": "高", "is_correct": false, "explanation": "无反义关系：“高”说高度或位置，与“清”没有对立。"}, {"text": "厚", "is_correct": false, "explanation": "无反义关系：“厚”说厚度，与“清”没有对立。"}, {"text": "远", "is_correct": false, "explanation": "无反义关系：“远”说距离，与“清”没有对应关系。"}], "correct_answer": "浑", "explanations": {"浑": "反义：“清”指水干净见底，反义是“浑”，即水浑浊。", "高": "无反义关系：“高”说高度或位置，与“清”没有对立。", "厚": "无反义关系：“厚”说厚度，与“清”没有对立。", "远": "无反义关系：“远”说距离，与“清”没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "清是水很干净，能看到底。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "这个湖的水很清，一眼就能看到底。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的水特别清，我们看得见小鱼。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水清得能看见底下的石头。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水不太深，也很清。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水不清，我们看不到水底。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在水很清的小河边玩水。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小溪清得看得见每一块石头。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泳池里的水又清又蓝，一眼就看到底。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水真清，我们都想下去游泳。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水清的地方，常常有很多小鱼。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清清的", "label": "重叠"}], "register": "中性", "sense_fingerprint": "水干净见底、清澈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清", "is_correct": true, "explanation": "清（qīng）：水干净、见底，即本条词义。"}, {"text": "请", "is_correct": false, "explanation": "请（qǐng，第三声）与 qīng（第一声）声调不同，意思是请求、邀请。"}, {"text": "情", "is_correct": false, "explanation": "情（qíng，第二声）与 qīng（第一声）声调不同，意思是感情。"}, {"text": "亲", "is_correct": false, "explanation": "亲（qīn）与 qīng 韵尾不同（n 与 ng），意思是亲近、亲人。"}, {"text": "庆", "is_correct": false, "explanation": "庆（qìng，第四声）与 qīng（第一声）声调不同，意思是庆祝。"}], "explanations": {"清": "清（qīng）：水干净、见底，即本条词义。", "请": "请（qǐng，第三声）与 qīng（第一声）声调不同，意思是请求、邀请。", "情": "情（qíng，第二声）与 qīng（第一声）声调不同，意思是感情。", "亲": "亲（qīn）与 qīng 韵尾不同（n 与 ng），意思是亲近、亲人。", "庆": "庆（qìng，第四声）与 qīng（第一声）声调不同，意思是庆祝。"}, "sentence_index": null, "correct_answer": "清"}, "level_3": {"options": [{"text": "清", "is_correct": true, "explanation": "正确：“很清，一眼就能看到底”说水清澈，只有“清”符合。"}, {"text": "浑", "is_correct": false, "explanation": "语义：水浑浊时看不到底，与后半句“一眼就能看到底”矛盾。"}, {"text": "深", "is_correct": false, "explanation": "语义：水深时看不到底，与“一眼就能看到底”矛盾。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”多指具体的污物，湖水一般说浑，不说脏；且与“看到底”矛盾。"}], "explanations": {"清": "正确：“很清，一眼就能看到底”说水清澈，只有“清”符合。", "浑": "语义：水浑浊时看不到底，与后半句“一眼就能看到底”矛盾。", "深": "语义：水深时看不到底，与“一眼就能看到底”矛盾。", "脏": "搭配：“脏”多指具体的污物，湖水一般说浑，不说脏；且与“看到底”矛盾。"}, "sentence_index": 0, "correct_answer": "清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块冰很清，能看见里面的气泡。", "explanation": "这里应该用〈透明〉。清指液体纯净；冰这类固体的透亮要说透明，不能说很清。"}, {"text": "这只箱子很清，我一个人就能抬起来。", "explanation": "这里应该用〈轻〉。清指水纯净见底，不表示物体的轻重；箱子的轻重要说轻，不能说很清。"}, {"text": "这双鞋刷得很清，一点灰都没有。", "explanation": "这里应该用〈干净〉。清用于水等液体的纯净，鞋子的洁净要说干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "清", "is_correct": true, "explanation": "清（qīng）：水干净、见底，即本条词义。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng，第二声）与 qīng（第一声）声调不同，意思是天气晴朗。"}, {"text": "惊", "is_correct": false, "explanation": "惊（jīng）与 qīng 声母不同（j 与 q），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经（jīng）与 qīng 声母不同（j 与 q），意思是经过、经验。"}, {"text": "京", "is_correct": false, "explanation": "京（jīng）与 qīng 声母不同（j 与 q），意思是首都、北京。"}], "explanations": {"清": "清（qīng）：水干净、见底，即本条词义。", "晴": "晴（qíng，第二声）与 qīng（第一声）声调不同，意思是天气晴朗。", "惊": "惊（jīng）与 qīng 声母不同（j 与 q），意思是惊讶。", "经": "经（jīng）与 qīng 声母不同（j 与 q），意思是经过、经验。", "京": "京（jīng）与 qīng 声母不同（j 与 q），意思是首都、北京。"}, "sentence_index": null, "correct_answer": "清"}, "level_3": {"options": [{"text": "黑", "is_correct": false, "explanation": "语义：水黑时看不见石头，与“看得见每一块石头”矛盾。"}, {"text": "清", "is_correct": true, "explanation": "正确：“清得看得见每一块石头”描写溪水见底，只有“清”符合。"}, {"text": "灰", "is_correct": false, "explanation": "语义：灰色的水同样看不清石头，与后半句矛盾。"}, {"text": "臭", "is_correct": false, "explanation": "搭配：“臭”说气味，溪水不说臭，且与“看得见石头”矛盾。"}], "explanations": {"黑": "语义：水黑时看不见石头，与“看得见每一块石头”矛盾。", "清": "正确：“清得看得见每一块石头”描写溪水见底，只有“清”符合。", "灰": "语义：灰色的水同样看不清石头，与后半句矛盾。", "臭": "搭配：“臭”说气味，溪水不说臭，且与“看得见石头”矛盾。"}, "sentence_index": 6, "correct_answer": "清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间病房很清，床单都换过了。", "explanation": "这里应该用〈洁净〉。清用于水等液体的纯净，病房的整洁要说洁净。"}, {"text": "他这个人很清，从不占别人便宜。", "explanation": "这里的“清”指为人廉洁，是另一义项，不是水纯净见底，不能这样用于这个词义。"}, {"text": "这条街晚上很清，很少有人走动。", "explanation": "这里的“清”指地方清静，是另一义项，与水的纯净见底无关，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山里的溪水清地能看见石头。", "corrected_sentence": "山里的溪水清得能看见石头。", "error_description": "错在补语标记：“清得能看见石头”中的“得”引出结果补语，写成“地”不成立，应改为“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖的水清很，我们都想下去游泳。", "corrected_sentence": "这个湖的水清得很，我们都想下去游泳。", "error_description": "错在补语：表示程度的补语前要用“得”，“清很”应为“清得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浑", "is_correct": true, "explanation": "反义：“清”指水纯净，反义是“浑”，即浑浊、有杂质。"}, {"text": "甜", "is_correct": false, "explanation": "无反义关系：“甜”说味道，与“清”的纯净义没有对立。"}, {"text": "深", "is_correct": false, "explanation": "无反义关系：“深”说深度，不与“清”构成反义。"}, {"text": "快", "is_correct": false, "explanation": "无反义关系：“快”说速度，与“清”没有对应关系。"}], "correct_answer": "浑", "explanations": {"浑": "反义：“清”指水纯净，反义是“浑”，即浑浊、有杂质。", "甜": "无反义关系：“甜”说味道，与“清”的纯净义没有对立。", "深": "无反义关系：“深”说深度，不与“清”构成反义。", "快": "无反义关系：“快”说速度，与“清”没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
