INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有杂质；纯净透明。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "山里的泉水又清又甜。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的水很清，能看见水底的鱼。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里的水很清，一点脏东西也没有。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，河水没有以前那么清了。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的水清得像一面镜子。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一条水更清的小溪洗菜。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那口井里的水又凉又清，夏天大家都爱喝。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的水真清，我们都喝了几口。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水本来很清，现在却有点黄了。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过滤以后，桶里的水变清了。", "target_word": "清", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清清的", "label": "重叠"}], "register": "中性", "sense_fingerprint": "液体（多指水）纯净透明、没有杂质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清", "is_correct": true, "explanation": "清（qīng）：没有杂质、纯净透明，即本条词义。"}, {"text": "请", "is_correct": false, "explanation": "请（qǐng，第三声）与 qīng（第一声）声调不同，意思是请求、邀请。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng，第二声）与 qīng（第一声）声调不同，意思是天气晴朗。"}, {"text": "亲", "is_correct": false, "explanation": "亲（qīn）与 qīng 韵尾不同（n 与 ng），意思是亲近、亲人。"}, {"text": "庆", "is_correct": false, "explanation": "庆（qìng，第四声）与 qīng（第一声）声调不同，意思是庆祝。"}], "explanations": {"清": "清（qīng）：没有杂质、纯净透明，即本条词义。", "请": "请（qǐng，第三声）与 qīng（第一声）声调不同，意思是请求、邀请。", "晴": "晴（qíng，第二声）与 qīng（第一声）声调不同，意思是天气晴朗。", "亲": "亲（qīn）与 qīng 韵尾不同（n 与 ng），意思是亲近、亲人。", "庆": "庆（qìng，第四声）与 qīng（第一声）声调不同，意思是庆祝。"}, "sentence_index": null, "correct_answer": "清"}, "level_3": {"options": [{"text": "清", "is_correct": true, "explanation": "正确：“又清又甜”描写泉水纯净和甜味，只有“清”符合。"}, {"text": "咸", "is_correct": false, "explanation": "语义：泉水又咸又甜自相矛盾，与“甜”冲突。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”指污秽，一般不用来形容泉水，且与“甜”矛盾。"}, {"text": "臭", "is_correct": false, "explanation": "语义：“又臭又甜”自相矛盾，泉水不会有臭味。"}], "explanations": {"清": "正确：“又清又甜”描写泉水纯净和甜味，只有“清”符合。", "咸": "语义：泉水又咸又甜自相矛盾，与“甜”冲突。", "脏": "搭配：“脏”指污秽，一般不用来形容泉水，且与“甜”矛盾。", "臭": "语义：“又臭又甜”自相矛盾，泉水不会有臭味。"}, "sentence_index": 0, "correct_answer": "清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃很清，能看到后面的人。", "explanation": "这里应该用〈透明〉。清指液体纯净、没有杂质；玻璃这类固体的透亮要说透明，不能说很清。"}, {"text": "这个包很清，拿在手上一点也不沉。", "explanation": "这里应该用〈轻〉。清指水纯净透明，不表示物体的轻重；包的轻重要说轻，不能说很清。"}, {"text": "他把桌子擦得很清，一点灰都没有。", "explanation": "这里应该用〈干净〉。清用于水等液体的纯净透明，擦桌子等洁净要说干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "清", "is_correct": true, "explanation": "清（qīng）：没有杂质、纯净透明，即本条词义。"}, {"text": "情", "is_correct": false, "explanation": "情（qíng，第二声）与 qīng（第一声）声调不同，意思是感情。"}, {"text": "惊", "is_correct": false, "explanation": "惊（jīng）与 qīng 声母不同（j 与 q），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经（jīng）与 qīng 声母不同（j 与 q），意思是经过、经验。"}, {"text": "京", "is_correct": false, "explanation": "京（jīng）与 qīng 声母不同（j 与 q），意思是首都、北京。"}], "explanations": {"清": "清（qīng）：没有杂质、纯净透明，即本条词义。", "情": "情（qíng，第二声）与 qīng（第一声）声调不同，意思是感情。", "惊": "惊（jīng）与 qīng 声母不同（j 与 q），意思是惊讶。", "经": "经（jīng）与 qīng 声母不同（j 与 q），意思是经过、经验。", "京": "京（jīng）与 qīng 声母不同（j 与 q），意思是首都、北京。"}, "sentence_index": null, "correct_answer": "清"}, "level_3": {"options": [{"text": "热", "is_correct": false, "explanation": "语义：“又凉又热”自相矛盾，与前面的“凉”冲突。"}, {"text": "清", "is_correct": true, "explanation": "正确：“又凉又清”描写井水凉和纯净，只有“清”符合。"}, {"text": "烫", "is_correct": false, "explanation": "语义：水又凉又烫自相矛盾，与“凉”冲突。"}, {"text": "苦", "is_correct": false, "explanation": "搭配：井水一般不说苦，且与“夏天大家都爱喝”矛盾。"}], "explanations": {"热": "语义：“又凉又热”自相矛盾，与前面的“凉”冲突。", "清": "正确：“又凉又清”描写井水凉和纯净，只有“清”符合。", "烫": "语义：水又凉又烫自相矛盾，与“凉”冲突。", "苦": "搭配：井水一般不说苦，且与“夏天大家都爱喝”矛盾。"}, "sentence_index": 6, "correct_answer": "清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间厨房很清，每个角落都亮亮的。", "explanation": "这里应该用〈洁净〉。清用于水等液体的纯净透明，环境的整洁要说洁净。"}, {"text": "这位法官很清，从不收别人的礼物。", "explanation": "这里的“清”指为人廉洁，是另一义项，不是水纯净透明，不能这样用于这个词义。"}, {"text": "这个小镇很清，晚上没有人来打扰。", "explanation": "这里的“清”指地方清静，是另一义项，与水的纯净透明无关，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水清地能看见鱼。", "corrected_sentence": "这条河的水清得能看见鱼。", "error_description": "错在补语标记：“清得能看见鱼”中的“得”引出结果补语，写成“地”（状语标记）不成立，应改为“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河的水清很，夏天很多人来游泳。", "corrected_sentence": "这条河的水清得很，夏天很多人来游泳。", "error_description": "错在补语：表示程度的补语前要用“得”，“清很”应为“清得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "巨大", "is_correct": false, "explanation": "“巨大”形容体积或规模大，与数量多少无关，不是“众多”的反义词。"}, {"text": "寥寥", "is_correct": true, "explanation": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容好看，与数量多少无关，不是“众多”的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容没有声音或喧闹，与数量多少无关，不是“众多”的反义词。"}], "correct_answer": "寥寥", "explanations": {"巨大": "“巨大”形容体积或规模大，与数量多少无关，不是“众多”的反义词。", "寥寥": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。", "美丽": "“美丽”形容好看，与数量多少无关，不是“众多”的反义词。", "安静": "“安静”形容没有声音或喧闹，与数量多少无关，不是“众多”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与数量多少无关，不是“众多”的反义词。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”形容品性好，与数量多少无关，不是“众多”的反义词。"}, {"text": "稀少", "is_correct": true, "explanation": "正确：“稀少”指数量少，与“众多”数量很多的意思相反，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与数量多少无关，不是“众多”的反义词。"}], "correct_answer": "稀少", "explanations": {"明亮": "“明亮”形容光线充足或颜色鲜亮，与数量多少无关，不是“众多”的反义词。", "善良": "“善良”形容品性好，与数量多少无关，不是“众多”的反义词。", "稀少": "正确：“稀少”指数量少，与“众多”数量很多的意思相反，是反义词。", "清楚": "“清楚”形容明白、不模糊，与数量多少无关，不是“众多”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "众多是说有很多很多。", "primary_collocate": null, "pronunciation": "zhòng duō", "ipa": "ʈʂʊŋ˥˩ tuo˥", "syllable_count": 2, "sentences": [{"text": "中国有众多的城市。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上聚集着众多游客。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山上有众多美丽的花。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来看比赛的人数众多。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有众多员工。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里的书众多，我看不完。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "众多朋友来参加他的生日。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有众多的小鱼。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有众多老师和学生。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天海边的游客众多。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "眾多", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有很多很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "众多", "is_correct": true, "explanation": "正确：“众多”修饰“城市”，表示数量很多，符合句意。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量少，与“中国有……的城市”强调多的意思相反。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”指只有一个，与表示数量多的“众多”意思相反。"}, {"text": "幼小", "is_correct": false, "explanation": "搭配：“幼小”形容年龄小，不能用来修饰“城市”。"}], "explanations": {"众多": "正确：“众多”修饰“城市”，表示数量很多，符合句意。", "稀少": "语义：“稀少”指数量少，与“中国有……的城市”强调多的意思相反。", "唯一": "语义：“唯一”指只有一个，与表示数量多的“众多”意思相反。", "幼小": "搭配：“幼小”形容年龄小，不能用来修饰“城市”。"}, "sentence_index": 0, "correct_answer": "众多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料含有众多的糖。", "explanation": "这里应该用〈大量〉。“众多”用于可数的人或事物，“糖”是不可数的物质，要用“大量”。"}, {"text": "来看比赛的人很众多。", "explanation": "这里应该用〈多〉。“众多”是书面语，本身已表示数量多，不能再受程度副词“很”修饰。"}, {"text": "我住在一座众多的城市里。", "explanation": "这里应该去掉“一座”。“众多”指多个，不能与表示单个的“一座”连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "众多", "is_correct": true, "explanation": "正确：“众多”修饰“朋友”，表示人数很多，符合句意。"}, {"text": "寥寥", "is_correct": false, "explanation": "语义：“寥寥”指很少，与“来参加生日”的热闹语境相反。"}, {"text": "整个", "is_correct": false, "explanation": "搭配：“整个”指全体，不能修饰可数的“朋友”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，修饰“朋友”时指个子，与句中表示人数的意思不符。"}], "explanations": {"众多": "正确：“众多”修饰“朋友”，表示人数很多，符合句意。", "寥寥": "语义：“寥寥”指很少，与“来参加生日”的热闹语境相反。", "整个": "搭配：“整个”指全体，不能修饰可数的“朋友”。", "高大": "体貌：“高大”形容身材，修饰“朋友”时指个子，与句中表示人数的意思不符。"}, "sentence_index": 6, "correct_answer": "众多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里冷清得很，只有众多游客来过。", "explanation": "这里应该用〈稀少〉。“众多”表示数量很多，与“冷清”及“只有”限定的少数矛盾。"}, {"text": "这座城市的人众多，正好三百个。", "explanation": "这里应该去掉“众多”。“众多”表示数量很多，不能与“正好三百个”这样的精确数字并列。"}, {"text": "他的身高众多。", "explanation": "这里应该用〈高〉。“众多”用于可数的人或事物，“身高”不是可数的事物，不能用“众多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有众多们大学。", "corrected_sentence": "这个城市有众多大学。", "error_description": "“众多”后面不能加“们”。“众多”直接修饰名词，应说“众多大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边有众多个游客在散步。", "corrected_sentence": "海边有众多游客在散步。", "error_description": "“众多”已表示数量多，后面不能再加量词“个”。应说“众多游客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86086, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或建筑高而大，与数量多少无关，不是“众多”的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑灵活，与数量多少无关，不是“众多”的反义词。"}, {"text": "寥寥", "is_correct": true, "explanation": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污物，与数量多少无关，不是“众多”的反义词。"}], "correct_answer": "寥寥", "explanations": {"高大": "“高大”形容身材或建筑高而大，与数量多少无关，不是“众多”的反义词。", "聪明": "“聪明”形容头脑灵活，与数量多少无关，不是“众多”的反义词。", "寥寥": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。", "干净": "“干净”形容没有污物，与数量多少无关，不是“众多”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86086, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冰冷", "is_correct": false, "explanation": "“冰冷”形容温度低或态度冷淡，与数量多少无关，不是“众多”的反义词。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或气候平和，与数量多少无关，不是“众多”的反义词。"}, {"text": "寥寥", "is_correct": true, "explanation": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”形容质地结实不易变形，与数量多少无关，不是“众多”的反义词。"}], "correct_answer": "寥寥", "explanations": {"冰冷": "“冰冷”形容温度低或态度冷淡，与数量多少无关，不是“众多”的反义词。", "温和": "“温和”形容性情或气候平和，与数量多少无关，不是“众多”的反义词。", "寥寥": "正确：“寥寥”指很少，与“众多”数量很多的意思相反，是反义词。", "坚硬": "“坚硬”形容质地结实不易变形，与数量多少无关，不是“众多”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86086, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量很多。", "primary_collocate": null, "pronunciation": "zhòng duō", "ipa": "ʈʂʊŋ˥˩ tuo˥", "syllable_count": 2, "sentences": [{"text": "这里的人口众多。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有众多爱好，比如画画和唱歌。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "众多顾客在商店门口排队。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的动物种类众多。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有众多公园。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加会议的人员众多。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "众多学生在操场上跑步。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的朋友众多，到哪儿都有人认识。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里图书众多，选书很难。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛有众多观众。", "target_word": "众多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "眾多", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "众多", "is_correct": true, "explanation": "正确：“众多”作谓语，说明人口数量很多，符合句意。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”形容地方热闹，不说“人口繁华”。"}, {"text": "合适", "is_correct": false, "explanation": "语义：“合适”指适宜、恰当，与说人口数量的语境不符。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌好看，不用来说人口的多少。"}], "explanations": {"众多": "正确：“众多”作谓语，说明人口数量很多，符合句意。", "繁华": "搭配：“繁华”形容地方热闹，不说“人口繁华”。", "合适": "语义：“合适”指适宜、恰当，与说人口数量的语境不符。", "漂亮": "语义：“漂亮”形容外貌好看，不用来说人口的多少。"}, "sentence_index": 0, "correct_answer": "众多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "森林里有众多的水。", "explanation": "这里应该用〈大量〉。“众多”用于可数的人或事物，“水”是不可数的物质，要用“大量”。"}, {"text": "森林里的动物很众多。", "explanation": "这里应该用〈多〉。“众多”是书面语，本身已表示数量多，不能再受程度副词“很”修饰。"}, {"text": "森林里的动物种类众多，一共只有两种。", "explanation": "这里应该用〈很少〉。“众多”表示数量很多，与“一共只有两种”的少数矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "众多", "is_correct": true, "explanation": "正确：“众多”修饰“学生”，表示人数很多，符合句意。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量少，与句中“在操场上跑步”的多人场景相反。"}, {"text": "整个", "is_correct": false, "explanation": "搭配：“整个”指全体，不能修饰可数的“学生”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，修饰“学生”时指个子，与句中表示人数的意思不符。"}], "explanations": {"众多": "正确：“众多”修饰“学生”，表示人数很多，符合句意。", "稀少": "语义：“稀少”指数量少，与句中“在操场上跑步”的多人场景相反。", "整个": "搭配：“整个”指全体，不能修饰可数的“学生”。", "高大": "体貌：“高大”形容身材，修饰“学生”时指个子，与句中表示人数的意思不符。"}, "sentence_index": 6, "correct_answer": "众多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛有一位众多的观众。", "explanation": "这里应该去掉“一位”。“众多”指多个，不能与表示单个人的量词“一位”连用。"}, {"text": "这场比赛的热情众多。", "explanation": "这里应该用〈热烈〉。“众多”用于可数的人或事物，“热情”是抽象的情感，不能数。"}, {"text": "这场比赛观众众多，却没有一个人。", "explanation": "这里应该用〈冷清〉。“众多”表示数量很多，与“却没有一个人”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
