INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "制造或加工产品的场所。", "primary_collocate": null, "pronunciation": "chǎng", "ipa": "tʂʰɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这家厂专门生产汽车零件。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在厂里负责检查产品。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个厂每天生产一万双鞋。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们厂新买了几台机器。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在厂里加工金属。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家厂做的玩具很受欢迎。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把新厂建在城外。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里的机器声很大。", "target_word": "厂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个厂用木头做家具。", "target_word": "厂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂里每个月给工人发工资。", "target_word": "厂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "廠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "制造或加工产品的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厂", "is_correct": true, "explanation": "正确：厂指制造或加工产品的场所。"}, {"text": "长", "is_correct": false, "explanation": "声调不同：厂（chǎng，第三声）与长（cháng，第二声）声调不同，长的意思是长短。"}, {"text": "唱", "is_correct": false, "explanation": "声调不同：厂（chǎng）与唱（chàng，第四声）声调不同，唱的意思是唱歌。"}, {"text": "产", "is_correct": false, "explanation": "韵母不同：厂（-ǎng）与产（-ǎn）韵母不同，产的意思是生产。"}, {"text": "宠", "is_correct": false, "explanation": "韵母不同：厂（-ǎng）与宠（-ǒng）韵母不同，宠的意思是宠爱或宠物。"}], "explanations": {"厂": "正确：厂指制造或加工产品的场所。", "长": "声调不同：厂（chǎng，第三声）与长（cháng，第二声）声调不同，长的意思是长短。", "唱": "声调不同：厂（chǎng）与唱（chàng，第四声）声调不同，唱的意思是唱歌。", "产": "韵母不同：厂（-ǎng）与产（-ǎn）韵母不同，产的意思是生产。", "宠": "韵母不同：厂（-ǎng）与宠（-ǒng）韵母不同，宠的意思是宠爱或宠物。"}, "sentence_index": null, "correct_answer": "厂"}, "level_3": {"options": [{"text": "厂", "is_correct": true, "explanation": "正确：厂是制造或加工产品的场所，“这家厂专门生产汽车零件”成立。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅是供人吃饭的地方，不生产汽车零件，句意矛盾。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教书育人的地方，不生产汽车零件，句意矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园用来种花观赏，不生产汽车零件，句意矛盾。"}], "explanations": {"厂": "正确：厂是制造或加工产品的场所，“这家厂专门生产汽车零件”成立。", "餐厅": "语义：餐厅是供人吃饭的地方，不生产汽车零件，句意矛盾。", "学校": "语义：学校是教书育人的地方，不生产汽车零件，句意矛盾。", "花园": "语义：花园用来种花观赏，不生产汽车零件，句意矛盾。"}, "sentence_index": 0, "correct_answer": "厂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们附近新开了一家厂，专门卖玩具。", "explanation": "这里应该用〈商店〉。厂负责生产产品，卖玩具要用商店。"}, {"text": "这家厂专门治疗小孩子的病。", "explanation": "这里应该用〈医院〉。厂是生产场所，治病要去医院。"}, {"text": "这家厂的老师每天教我们画画。", "explanation": "这里应该用〈画室〉。厂是生产产品的场所，教画画要在画室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86102, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "厂", "is_correct": true, "explanation": "正确：厂指制造或加工产品的场所。"}, {"text": "常", "is_correct": false, "explanation": "声调不同：厂（chǎng）与常（cháng，第二声）声调不同，常的意思是经常。"}, {"text": "畅", "is_correct": false, "explanation": "声调不同：厂（chǎng）与畅（chàng，第四声）声调不同，畅的意思是畅快、通畅。"}, {"text": "铲", "is_correct": false, "explanation": "韵母不同：厂（-ǎng）与铲（-ǎn）韵母不同，铲的意思是铲子。"}, {"text": "掌", "is_correct": false, "explanation": "声母不同：厂（ch-）与掌（zh-）声母不同，掌的意思是手掌。"}], "explanations": {"厂": "正确：厂指制造或加工产品的场所。", "常": "声调不同：厂（chǎng）与常（cháng，第二声）声调不同，常的意思是经常。", "畅": "声调不同：厂（chǎng）与畅（chàng，第四声）声调不同，畅的意思是畅快、通畅。", "铲": "韵母不同：厂（-ǎng）与铲（-ǎn）韵母不同，铲的意思是铲子。", "掌": "声母不同：厂（ch-）与掌（zh-）声母不同，掌的意思是手掌。"}, "sentence_index": null, "correct_answer": "厂"}, "level_3": {"options": [{"text": "厂", "is_correct": true, "explanation": "正确：厂是可以在城外建造的大型生产场所，“公司把新厂建在城外”成立。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“建”用于厂房、楼房等建筑，树木要说「种」，不说「建」。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻是消息，不能搬到城外去建造，句意不通。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是用来唱的，不是建筑物，不能建在城外。"}], "explanations": {"厂": "正确：厂是可以在城外建造的大型生产场所，“公司把新厂建在城外”成立。", "树": "搭配：“建”用于厂房、楼房等建筑，树木要说「种」，不说「建」。", "新闻": "语义：新闻是消息，不能搬到城外去建造，句意不通。", "歌": "语义：歌是用来唱的，不是建筑物，不能建在城外。"}, "sentence_index": 6, "correct_answer": "厂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村东头新开了一家厂，每天教孩子们读书。", "explanation": "这里应该用〈学校〉。厂是生产产品的场所，教孩子读书要在学校。"}, {"text": "晚上我们全家在这家厂里看电影。", "explanation": "这里应该用〈电影院〉。厂是生产产品的场所，看电影要去电影院。"}, {"text": "妈妈每天早上在这家厂里做饭。", "explanation": "这里应该用〈厨房〉。厂是生产产品的场所，做饭要在厨房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥在一只厂里找到了工作。", "corrected_sentence": "我哥哥在一家厂里找到了工作。", "error_description": "错误：「一只厂」用错了量词。厂的量词应为「家」，「只」用于动物等成对的东西。正确说法是「一家厂」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我叔叔厂吗？", "corrected_sentence": "这是我叔叔的厂吗？", "error_description": "错误：「我叔叔厂」漏了定语标记「的」。表示厂属于谁，要说「我叔叔的厂」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
