INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86103, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“您”是对年纪大的人说话时，很有礼貌地叫“你”。", "primary_collocate": null, "pronunciation": "nín", "ipa": "nin˧˥", "syllable_count": 1, "sentences": [{"text": "奶奶，您身体好吗？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王奶奶，您请坐。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷，您想喝茶吗？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张阿姨，您今天去哪儿？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老奶奶，我想问您一个问题。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆，您今天想出去走走吗？", "target_word": "您", "complexity_tier": "T3", "furigana": "wài pó, nín jīntiān xiǎng chūqù zǒu zou ma?", "sentence_source": "generated"}, {"text": "大爷，您慢点儿走。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张奶奶，谢谢您的帮助。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人上车了，我请您坐这儿。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李奶奶，您住在哪儿？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌", "sense_fingerprint": "对年纪大的人有礼貌地称呼“你”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "您", "is_correct": true, "explanation": "正确答案。“您”是对年长或尊敬的人的礼貌称呼。"}, {"text": "妮", "is_correct": false, "explanation": "nī 与 nín 差韵尾 n 且声调不同，“妮”指女孩（如“妮子”），与敬称无关。"}, {"text": "林", "is_correct": false, "explanation": "lín 与 nín 只差声母（l 和 n），意思是树林。"}, {"text": "宁", "is_correct": false, "explanation": "níng 与 nín 只差韵尾（ng 和 n），意思是“安宁”。"}, {"text": "尼", "is_correct": false, "explanation": "ní 与 nín 只差韵尾 n，意思是“尼”（如尼姑）。"}], "explanations": {"您": "正确答案。“您”是对年长或尊敬的人的礼貌称呼。", "妮": "nī 与 nín 差韵尾 n 且声调不同，“妮”指女孩（如“妮子”），与敬称无关。", "林": "lín 与 nín 只差声母（l 和 n），意思是树林。", "宁": "níng 与 nín 只差韵尾（ng 和 n），意思是“安宁”。", "尼": "ní 与 nín 只差韵尾 n，意思是“尼”（如尼姑）。"}, "sentence_index": null, "correct_answer": "您"}, "level_3": {"options": [{"text": "您", "is_correct": true, "explanation": "正确：“您”是对老人的敬称，与“奶奶”呼应。"}, {"text": "他们", "is_correct": false, "explanation": "语义：对面前的奶奶应当用第二人称，不能用第三人称“他们”。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人，不指对话的奶奶。"}, {"text": "它", "is_correct": false, "explanation": "搭配：“它”指事物或动物，不能用来指人。"}], "explanations": {"您": "正确：“您”是对老人的敬称，与“奶奶”呼应。", "他们": "语义：对面前的奶奶应当用第二人称，不能用第三人称“他们”。", "咱们": "语义：“咱们”包括说话人，不指对话的奶奶。", "它": "搭配：“它”指事物或动物，不能用来指人。"}, "sentence_index": 0, "correct_answer": "您"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们俩，您今天去哪儿？", "explanation": "这里应该用〈你们俩〉。“您”是单数敬称，不能用来称呼两个人，应说“你们俩今天去哪儿？”"}, {"text": "同学们，您今天去哪儿？", "explanation": "这里应该用〈你们〉。“您”是单数敬称，不能用来称呼一群人。"}, {"text": "小弟弟，您们今天去哪儿？", "explanation": "这里应该用〈你〉。“您们”不规范，“您”是单数敬称，不能加“们”；对小孩子也应说“你”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "您", "is_correct": true, "explanation": "正确：“您”是对老人的敬称，与“大爷”呼应。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，不是对大爷说话。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”包括说话人，不指对话的大爷。"}, {"text": "他", "is_correct": false, "explanation": "搭配：当面称呼老人时不用第三人称“他”。"}], "explanations": {"您": "正确：“您”是对老人的敬称，与“大爷”呼应。", "我": "语义：“我”指说话人自己，不是对大爷说话。", "我们": "语义：“我们”包括说话人，不指对话的大爷。", "他": "搭配：当面称呼老人时不用第三人称“他”。"}, "sentence_index": 6, "correct_answer": "您"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗，您叫什么名字？", "explanation": "这里不能用〈您〉。“您”只用于尊敬的人，不能称呼动物。"}, {"text": "我的书，您在哪儿？", "explanation": "这里不能用〈您〉。“您”是对人的敬称，不能用来称呼物品。"}, {"text": "空调，您开一下。", "explanation": "这里不能用〈您〉。“您”只用于尊敬的人，不能称呼物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷，您们吃饭了吗？", "corrected_sentence": "爷爷，您吃饭了吗？", "error_description": "错误形式：“您们”。“您”是单数敬称，不能加“们”，应说“您”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "陈奶奶，早上您好。", "corrected_sentence": "陈奶奶，您早。", "error_description": "语序错误：“早上您好”不成话，“您”作主语应放在“早”之前，应说“陈奶奶，您早。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
