INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86104, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第二人称代词，“你”的敬称。", "primary_collocate": null, "pronunciation": "nín", "ipa": "nin˧˥", "syllable_count": 1, "sentences": [{"text": "先生，您要喝点什么？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎您来我们公司。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理，这是给您的信。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您贵姓？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女士，您的电话响了。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢您今天来看我们。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人，您想住几天？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您好，请问您找谁？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王总，我明天给您打电话。", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，这本书是您的吗？", "target_word": "您", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌", "sense_fingerprint": "第二人称“你”的敬称，用于客人、上级等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "您", "is_correct": true, "explanation": "正确答案。“您”是“你”的敬称，用于客人、上级等。"}, {"text": "妮", "is_correct": false, "explanation": "nī 与 nín 差韵尾 n 且声调不同，“妮”指女孩（如“妮子”），与敬称无关。"}, {"text": "林", "is_correct": false, "explanation": "lín 与 nín 只差声母（l 和 n），意思是树林。"}, {"text": "尼", "is_correct": false, "explanation": "ní 与 nín 只差韵尾 n，意思是“尼”（如尼姑）。"}, {"text": "凝", "is_correct": false, "explanation": "níng 与 nín 只差韵尾（ng 和 n），意思是“凝固”。"}], "explanations": {"您": "正确答案。“您”是“你”的敬称，用于客人、上级等。", "妮": "nī 与 nín 差韵尾 n 且声调不同，“妮”指女孩（如“妮子”），与敬称无关。", "林": "lín 与 nín 只差声母（l 和 n），意思是树林。", "尼": "ní 与 nín 只差韵尾 n，意思是“尼”（如尼姑）。", "凝": "níng 与 nín 只差韵尾（ng 和 n），意思是“凝固”。"}, "sentence_index": null, "correct_answer": "您"}, "level_3": {"options": [{"text": "您", "is_correct": true, "explanation": "正确：“您”是对客人的敬称，与“先生”呼应。"}, {"text": "它", "is_correct": false, "explanation": "搭配：“它”指事物或动物，不能用来指人。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，不能用来询问对方想喝什么。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人一方，不指对话的先生。"}], "explanations": {"您": "正确：“您”是对客人的敬称，与“先生”呼应。", "它": "搭配：“它”指事物或动物，不能用来指人。", "我": "语义：“我”指说话人自己，不能用来询问对方想喝什么。", "我们": "语义：“我们”指说话人一方，不指对话的先生。"}, "sentence_index": 0, "correct_answer": "您"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥俩，您今天很忙吗？", "explanation": "这里应该用〈你们〉。“您”是单数敬称，不能用来称呼两个人。"}, {"text": "同学们，您准备好了吗？", "explanation": "这里应该用〈你们〉。“您”是单数敬称，不能用来称呼一群人。"}, {"text": "小朋友，您们叫什么名字？", "explanation": "这里应该用〈你〉。“您们”不规范，“您”不加“们”；对小朋友也应说“你”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "您", "is_correct": true, "explanation": "正确：“您”是对客人的礼貌称呼，与“客人”呼应。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，不是对客人说话。"}, {"text": "她", "is_correct": false, "explanation": "语义：“她”是第三人称，当面称呼客人时不能用。"}, {"text": "他", "is_correct": false, "explanation": "搭配：当面称呼客人时不用第三人称“他”。"}], "explanations": {"您": "正确：“您”是对客人的礼貌称呼，与“客人”呼应。", "我": "语义：“我”指说话人自己，不是对客人说话。", "她": "语义：“她”是第三人称，当面称呼客人时不能用。", "他": "搭配：当面称呼客人时不用第三人称“他”。"}, "sentence_index": 6, "correct_answer": "您"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书包，您是谁的？", "explanation": "这里不能用〈您〉。“您”只用于尊敬的人，不能称呼物品。"}, {"text": "我的手机，您响了。", "explanation": "这里不能用〈您〉。“您”是对人的敬称，不能指物品。"}, {"text": "小狗，您叫什么名字？", "explanation": "这里不能用〈您〉。“您”只用于尊敬的人，不能称呼动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是您书的。", "corrected_sentence": "这是您的书。", "error_description": "语序错误：“您的书”是定中结构，“的”应紧跟“您”，不能说“您书的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "张经理，您们请坐。", "corrected_sentence": "张经理，您请坐。", "error_description": "数量错误：“您”是单数敬称，不能加“们”变成“您们”，应说“您请坐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
