INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“当然”是说这样做是对的，谁都会这样想。", "primary_collocate": null, "pronunciation": "dāng rán", "ipa": "tɑŋ˥ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "朋友有困难，我们当然要帮他。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了事，当然要说对不起。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人上车，年轻人当然应该让座。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮了我，我当然要谢谢你。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子生病了，妈妈当然很担心。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我的好朋友，我当然相信他。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭以前，当然要先洗手。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛赢了，大家当然都很高兴。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借了别人的东西，当然要还。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有红灯，车当然要停下来。", "target_word": "当然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按道理应该这样做，人人都会这么想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当然", "is_correct": true, "explanation": "正确。“当然”表示按道理应该如此，人人都会这么做。"}, {"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，与“朋友有困难”时理所应当帮忙的常理相悖。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“朋友有困难”时理所应当的帮助不符。"}, {"text": "诚然", "is_correct": false, "explanation": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。"}], "explanations": {"当然": "正确。“当然”表示按道理应该如此，人人都会这么做。", "居然": "语义：“居然”表示出乎意料，与“朋友有困难”时理所应当帮忙的常理相悖。", "竟然": "语义：“竟然”表示出乎意料，与“朋友有困难”时理所应当的帮助不符。", "诚然": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。"}, "sentence_index": 0, "correct_answer": "当然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都没想到，他当然考了第一。", "explanation": "这里应该用〈居然〉。「当然」表示按道理应当如此，与“没想到”的意外语境矛盾。"}, {"text": "大家都不看好我，我当然赢了比赛。", "explanation": "这里应该用〈反而〉。「当然」表示理所应当，与“大家都不看好”的预期相反，语境不合；表示出乎意料时应用〈反而〉。"}, {"text": "这是夏天，天气当然下雪了。", "explanation": "这里表示突然出现的变化，可用〈忽然〉或〈居然〉。「当然」表示理所应当，与“这是夏天”的常理相悖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当然", "is_correct": true, "explanation": "正确。“当然”表示按道理应当先洗手。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已完成，与“吃饭以前”的将来指向矛盾。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“直到……才”，与“吃饭以前”的时间指向不合。"}, {"text": "固然", "is_correct": false, "explanation": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句。"}], "explanations": {"当然": "正确。“当然”表示按道理应当先洗手。", "已经": "语义：“已经”表示动作已完成，与“吃饭以前”的将来指向矛盾。", "才": "语义：“才”表示“直到……才”，与“吃饭以前”的时间指向不合。", "固然": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句。"}, "sentence_index": 6, "correct_answer": "当然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直很冷静，我当然吓了一跳。", "explanation": "这里应该用〈突然〉。「当然」表示理所应当，与“他一直很冷静”的情况不合，此处是突然受惊，应用〈突然〉。"}, {"text": "我以为他会赢，结果他当然输了。", "explanation": "这里应该用〈竟然〉。「当然」表示按道理应当如此，与“以为他会赢”的预期相悖。"}, {"text": "他刚学了三天汉语，当然已经会说中文了。", "explanation": "这里应该用〈居然〉。「当然」表示理所应当，与“刚学了三天”的常理相悖，此处应表示出乎意料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师生病了，我们没当然要去看他。", "corrected_sentence": "老师生病了，我们当然要去看他。", "error_description": "“当然”是副词，表示理所应当，不能受否定副词“没”修饰。应说“我们当然要去看他”，不说“我们没当然要去看他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们累了，当然的要休息。", "corrected_sentence": "孩子们累了，当然要休息。", "error_description": "“当然”作副词时，后面不能直接加结构助词“的”。应说“当然要休息”，不说“当然的要休息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
