INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小姐是对年轻女子的客气叫法。", "primary_collocate": null, "pronunciation": "xiǎo jiě", "ipa": "ɕjɑʊ˨˩ tɕjɛ˨˩", "syllable_count": 2, "sentences": [{"text": "小姐，您的菜来了，请慢用。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姐，请问这条路怎么走？", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位小姐，您的手机掉了。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赵小姐在门口等着您。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马小姐，欢迎您来我们学校。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这位小姐贵姓？", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了那位小姐，她说银行在左边。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周小姐今天有点忙，明天再来吧。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刘小姐，这是您要的书。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位小姐一直笑着跟客人说话。", "target_word": "小姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小姐们", "label": "复数"}], "register": "礼貌", "sense_fingerprint": "客气地称呼年轻女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小姐", "is_correct": true, "explanation": "小姐（xiǎo jiě）：客气地称呼年轻女子，即本条词义。"}, {"text": "小结", "is_correct": false, "explanation": "小结（xiǎo jié）：jié（第二声）与 jiě（第三声）声调不同，意思是简要总结。"}, {"text": "小写", "is_correct": false, "explanation": "小写（xiǎo xiě）：xiě 与 jiě 声母不同（x 与 j），意思是小写字母。"}, {"text": "消解", "is_correct": false, "explanation": "消解（xiāo jiě）：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是消除。"}], "explanations": {"小姐": "小姐（xiǎo jiě）：客气地称呼年轻女子，即本条词义。", "小结": "小结（xiǎo jié）：jié（第二声）与 jiě（第三声）声调不同，意思是简要总结。", "小写": "小写（xiǎo xiě）：xiě 与 jiě 声母不同（x 与 j），意思是小写字母。", "消解": "消解（xiāo jiě）：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是消除。"}, "sentence_index": null, "correct_answer": "小姐"}, "level_3": {"options": [{"text": "小朋友", "is_correct": false, "explanation": "语义：小朋友不是饭店招待的顾客，与“您”的敬称矛盾。"}, {"text": "小姐", "is_correct": true, "explanation": "正确：饭店招待对年轻女顾客可以客气地称“小姐”，只有“小姐”符合。"}, {"text": "宝贝", "is_correct": false, "explanation": "语域：“宝贝”过于亲昵，对客人说话不合适。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”与“您”的敬称不符，不用于称呼成年顾客。"}], "explanations": {"小朋友": "语义：小朋友不是饭店招待的顾客，与“您”的敬称矛盾。", "小姐": "正确：饭店招待对年轻女顾客可以客气地称“小姐”，只有“小姐”符合。", "宝贝": "语域：“宝贝”过于亲昵，对客人说话不合适。", "孩子": "语义：“孩子”与“您”的敬称不符，不用于称呼成年顾客。"}, "sentence_index": 0, "correct_answer": "小姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位小姐的胡子很长，在门口等着您。", "explanation": "这里不能用〈小姐〉。句中说胡子很长，指男性，应称〈先生〉；小姐只用于年轻女子。"}, {"text": "这位小姐每天都在门口等孙子放学。", "explanation": "这里应该用〈老奶奶〉。小姐指年轻女子，句中“孙子”说明是老年人，不能称作小姐。"}, {"text": "这位小姐是我奶奶，在门口等着您。", "explanation": "这里应该用〈奶奶〉。小姐是对年轻女子的尊称，不能用来称呼自己的奶奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先生", "is_correct": false, "explanation": "语义：“先生”指男性，与后面的“她说”指代不一致。"}, {"text": "小姐", "is_correct": true, "explanation": "正确：“那位小姐”指年轻女子，与后面的“她说”一致，只有“小姐”符合。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：“叔叔”指男性，与后面的“她说”矛盾。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”属口语俗称，问路时称陌生女性不合适；且与“她说”不一致。"}], "explanations": {"先生": "语义：“先生”指男性，与后面的“她说”指代不一致。", "小姐": "正确：“那位小姐”指年轻女子，与后面的“她说”一致，只有“小姐”符合。", "叔叔": "语义：“叔叔”指男性，与后面的“她说”矛盾。", "大爷": "语域：“大爷”属口语俗称，问路时称陌生女性不合适；且与“她说”不一致。"}, "sentence_index": 6, "correct_answer": "小姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位小姐才三岁，还不会说话。", "explanation": "这里应该用〈小妹妹〉。小姐指年轻女子，不用于三岁的幼儿。"}, {"text": "那位小姐已经七十多岁了，每天在公园散步。", "explanation": "这里应该用〈老太太〉。小姐是对年轻女子的尊称，句中说她已七十多岁，不能这样称呼。"}, {"text": "那位小姐是个男的，一直笑着跟客人说话。", "explanation": "这里不能用〈小姐〉。句中说是男性，小姐只用于年轻女子，应说〈先生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位小姐们正在整理货架。", "corrected_sentence": "那位小姐正在整理货架。", "error_description": "错在复数标记：“那位”是单数量词，后面的“小姐”不能再加“们”，应为“那位小姐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请问，这位小姐们贵姓？", "corrected_sentence": "请问，这位小姐贵姓？", "error_description": "错误：“这位”指一人，“小姐们”表复数，二者矛盾；去掉“们”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
