INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "视频是在手机或电脑上看的会动的画面。", "primary_collocate": null, "pronunciation": "shì pín", "ipa": "ʂʅ˥˩ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "我在手机上看了一个有趣的视频。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上我常常用电脑看视频。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个视频只有三分钟，很短。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子喜欢看小动物的视频。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把视频发给了我。", "target_word": "视频", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正看着视频笑。", "target_word": "视频", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过这个视频吗？", "target_word": "视频", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频太大，手机存不下了。", "target_word": "视频", "complexity_tier": "T3", "furigana": "shì pín tài dà, shǒu jī cún bù xià le", "sentence_source": "generated"}, {"text": "这个视频里的小狗很可爱。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把这个视频下载到手机里。", "target_word": "视频", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "視頻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在手机或电脑上观看的会动的画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视频", "is_correct": true, "explanation": "正确答案。shì pín，意思是在手机或电脑上看的会动的画面。"}, {"text": "食品", "is_correct": false, "explanation": "shí pǐn（第二、第三声）与 shì pín 两个音节声调都不同，意思是食物。"}, {"text": "饰品", "is_correct": false, "explanation": "pǐn（第三声）与 pín（第二声）声调不同，意思是装饰品。"}, {"text": "市民", "is_correct": false, "explanation": "mín 与 pín 声母不同（m 与 p），意思是城市居民。"}], "explanations": {"视频": "正确答案。shì pín，意思是在手机或电脑上看的会动的画面。", "食品": "shí pǐn（第二、第三声）与 shì pín 两个音节声调都不同，意思是食物。", "饰品": "pǐn（第三声）与 pín（第二声）声调不同，意思是装饰品。", "市民": "mín 与 pín 声母不同（m 与 p），意思是城市居民。"}, "sentence_index": null, "correct_answer": "视频"}, "level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "语义：礼物是实物，不是在手机上能看的画面。"}, {"text": "视频", "is_correct": true, "explanation": "正确答案。“看了一个有趣的视频”指在手机上看的影像。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是可以在手机上观看的画面。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”说看见的画面，声音要说“听”。"}], "explanations": {"礼物": "语义：礼物是实物，不是在手机上能看的画面。", "视频": "正确答案。“看了一个有趣的视频”指在手机上看的影像。", "苹果": "语义：苹果是水果，不是可以在手机上观看的画面。", "声音": "搭配：“看”说看见的画面，声音要说“听”。"}, "sentence_index": 0, "correct_answer": "视频"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去电影院看了一部视频。", "explanation": "这里应该用〈电影〉。电影院里放的是电影，视频指在手机或电脑上看的画面。"}, {"text": "这张视频很有趣。", "explanation": "量词用错。视频用“段”或“个”计量，“张”多用于纸片、照片，不用于视频。"}, {"text": "他的视频很好，看得很远。", "explanation": "这里应该用〈视力〉。视频指影像，说眼睛看得清楚要用视力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "搭配：“看过”说看见的东西，声音要说“听过”。"}, {"text": "视频", "is_correct": true, "explanation": "正确答案。“看过这个视频吗”问对影像是否看过。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：气味要用“闻过”，不能用“看过”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是测量出来的数值，看不见，“看过”不通。"}], "explanations": {"声音": "搭配：“看过”说看见的东西，声音要说“听过”。", "视频": "正确答案。“看过这个视频吗”问对影像是否看过。", "气味": "搭配：气味要用“闻过”，不能用“看过”。", "温度": "语义：温度是测量出来的数值，看不见，“看过”不通。"}, "sentence_index": 6, "correct_answer": "视频"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把视频洗出来了。", "explanation": "这里应该用〈照片〉。“洗”用于照片，视频不能说洗出来。"}, {"text": "他很爱读视频。", "explanation": "这里应该用〈诗〉。“读”用于诗、文章等文字，看视频要说“看”。"}, {"text": "他推开了视频。", "explanation": "这里应该用〈门〉。“推开”用于门、窗等，视频不能推开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上我用平板看了一张视频。", "corrected_sentence": "晚上我用平板看了一段视频。", "error_description": "“视频”的量词应用“段”或“个”，不用“张”（“张”多用于纸片、照片）。应说“看了一段视频”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看过过这个视频，很好笑。", "corrected_sentence": "我看过这个视频，很好笑。", "error_description": "“过”是经历体助词，只用一个，紧跟动词“看”，应说“看过这个视频”，不能重复“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
