INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过电子设备录制或传输的活动影像。", "primary_collocate": null, "pronunciation": "shì pín", "ipa": "ʂʅ˥˩ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "我和奶奶用视频聊天。", "target_word": "视频", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开会时请打开你的视频。", "target_word": "视频", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网速太慢，视频一直不动。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在看路口拍下的视频。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把上课的视频发给了学生。", "target_word": "视频", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天录一段视频，放到网上。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "视频里的声音太小，我听不清。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机拍的视频可以传给朋友。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能关掉视频，只用声音吗？", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我们用视频开了一个会。", "target_word": "视频", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "视频通话", "label": "复合"}, {"form": "视频会议", "label": "复合"}, {"form": "視頻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用电子设备录制或传送的活动影像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86114, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视频", "is_correct": true, "explanation": "正确答案。shì pín，意思是通过电子设备录制或传输的活动影像。"}, {"text": "食品", "is_correct": false, "explanation": "shí pǐn（第二、第三声）与 shì pín 两个音节声调都不同，意思是食物。"}, {"text": "饰品", "is_correct": false, "explanation": "pǐn（第三声）与 pín（第二声）声调不同，意思是装饰品。"}, {"text": "市民", "is_correct": false, "explanation": "mín 与 pín 声母不同（m 与 p），意思是城市居民。"}], "explanations": {"视频": "正确答案。shì pín，意思是通过电子设备录制或传输的活动影像。", "食品": "shí pǐn（第二、第三声）与 shì pín 两个音节声调都不同，意思是食物。", "饰品": "pǐn（第三声）与 pín（第二声）声调不同，意思是装饰品。", "市民": "mín 与 pín 声母不同（m 与 p），意思是城市居民。"}, "sentence_index": null, "correct_answer": "视频"}, "level_3": {"options": [{"text": "筷子", "is_correct": false, "explanation": "语义：筷子是吃饭用的工具，不能用来聊天。"}, {"text": "视频", "is_correct": true, "explanation": "正确答案。“用视频聊天”指用影像通话。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能当作聊天的工具。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在眼睛上的物品，不能用来聊天。"}], "explanations": {"筷子": "语义：筷子是吃饭用的工具，不能用来聊天。", "视频": "正确答案。“用视频聊天”指用影像通话。", "身材": "体貌：“身材”指人的体形，不能当作聊天的工具。", "眼镜": "语义：眼镜是戴在眼睛上的物品，不能用来聊天。"}, "sentence_index": 0, "correct_answer": "视频"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察正在洗路口拍下的视频。", "explanation": "这里应该用〈照片〉。“洗”用于照片，视频不能说洗。"}, {"text": "学生们正在读视频。", "explanation": "这里应该用〈课本〉。“读”用于文字，看视频要说“看”。"}, {"text": "这本视频很有意思。", "explanation": "量词用错。视频用“段”或“个”计量，“本”用于书籍，不用于视频。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图片", "is_correct": false, "explanation": "语义：图片是静态画面，没有声音，不能说图片里的声音。"}, {"text": "视频", "is_correct": true, "explanation": "正确答案。“视频里的声音太小”指影像中的声音。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能有声音。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“声音太小”说的是可听的声音，不能说味道里的声音。"}], "explanations": {"图片": "语义：图片是静态画面，没有声音，不能说图片里的声音。", "视频": "正确答案。“视频里的声音太小”指影像中的声音。", "颜色": "语义：颜色是视觉属性，不能有声音。", "味道": "搭配：“声音太小”说的是可听的声音，不能说味道里的声音。"}, "sentence_index": 6, "correct_answer": "视频"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写了一个视频。", "explanation": "这里应该用〈故事〉。“写”用于文字作品，拍视频要说“拍”或“做”。"}, {"text": "他们在下视频。", "explanation": "这里应该用〈棋〉。“下”用于棋类，视频不能说下。"}, {"text": "他在唱视频。", "explanation": "这里应该用〈歌〉。“唱”用于歌曲，视频不能说唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这张视频传给了他。", "corrected_sentence": "我把这段视频传给了他。", "error_description": "“视频”的量词应用“段”，不用“张”（“张”多用于纸片、照片）。应说“这段视频”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上周用视频了开一次会。", "corrected_sentence": "我们上周用视频开了一次会。", "error_description": "“了”应放在动词“开”之后，说“开了一次会”，不能放在“视频”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
