INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86115, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“真”是说事情确实是这样，一点不假。", "primary_collocate": null, "pronunciation": "zhēn", "ipa": "ʈʂən˥", "syllable_count": 1, "sentences": [{"text": "他真走了，没有等我们。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我真不知道。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我真没骗你，别生气。", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说要来，今天真来了。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真要去北京工作吗？", "target_word": "真", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你别不信，我真看见他了。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他累，看样子他真累。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为他开玩笑，没想到他真买了。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她真生气了，一句话也不说。", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子真不吃饭，怎么办？", "target_word": "真", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "真的", "label": "复合"}], "register": "口语", "sense_fingerprint": "强调事情确实如此，不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '333b1bf0-2b8f-4c29-b4e8-b1f15cb04577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86115, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真", "is_correct": true, "explanation": "正确答案。真 zhēn（第一声），副词，表示确实如此。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是深。"}, {"text": "阵", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵子。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是征收、征服。"}], "explanations": {"真": "正确答案。真 zhēn（第一声），副词，表示确实如此。", "深": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是深。", "阵": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵子。", "诊": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊断。", "征": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是征收、征服。"}, "sentence_index": null, "correct_answer": "真"}, "level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "正确。“真”表示确实如此，强调“走了”是真实发生的。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不走了”与“走了”矛盾，且与后句“没有等我们”的叙述无法衔接。"}, {"text": "诚然", "is_correct": false, "explanation": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。"}, {"text": "固然", "is_correct": false, "explanation": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句。"}], "explanations": {"真": "正确。“真”表示确实如此，强调“走了”是真实发生的。", "不": "语义：“不走了”与“走了”矛盾，且与后句“没有等我们”的叙述无法衔接。", "诚然": "搭配：“诚然”要和后面的“但是”呼应，这里没有转折分句。", "固然": "搭配：“固然”要和后面的“但是”呼应，这里没有转折分句。"}, "sentence_index": 0, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我真高。", "explanation": "这里应该用〈更〉。「真」表示确实如此，不能用在比较句中修饰形容词，比较时要用〈更〉。"}, {"text": "我没有你真努力。", "explanation": "这里应该用〈那么〉。「真」不能用于“没有……那么……”的比较句，此处要用〈那么〉。"}, {"text": "这份报告比那份真完整。", "explanation": "这里应该用〈更〉。「真」不能用于比较句修饰形容词，表示比较时要用〈更〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86115, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真", "is_correct": true, "explanation": "正确答案。真 zhēn（第一声），副词，表示确实如此。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是身体。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是蒸煮。"}], "explanations": {"真": "正确答案。真 zhēn（第一声），副词，表示确实如此。", "身": "shēn（第一声）与 zhēn（第一声）声母不同（sh 与 zh），意思是身体。", "镇": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是城镇。", "枕": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是枕头。", "蒸": "zhēng（第一声）与 zhēn（第一声）韵母不同（eng 与 en），意思是蒸煮。"}, "sentence_index": null, "correct_answer": "真"}, "level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "正确。“真”强调“看样子”所见的疲惫状态是真实的。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”是书面语，与口语化的“看样子”不协调。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“仅仅、刚刚”，与“看样子”的推测语境不合。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，后面须接宾语和动词，“看样子他把累”不成句。"}], "explanations": {"真": "正确。“真”强调“看样子”所见的疲惫状态是真实的。", "甚": "语域：“甚”是书面语，与口语化的“看样子”不协调。", "才": "语义：“才”表示“仅仅、刚刚”，与“看样子”的推测语境不合。", "把": "语法：“把”是介词，后面须接宾语和动词，“看样子他把累”不成句。"}, "sentence_index": 6, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个菜真一些咸。", "explanation": "这里应该用〈有些〉。「真」表示确实，不能表示轻微的程度，与数量词「一些」搭配也不通。"}, {"text": "他真学生，每天都去上学。", "explanation": "这里应该用〈是〉。「真」修饰名词性谓语时要带〈是〉，说“真学生”不合语法。"}, {"text": "这座山很真高，我们爬不上去。", "explanation": "「真」是副词，不能受程度副词「很」修饰，应说“这座山真高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba0f92b-12c5-4c1f-b101-58269dad9b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.