INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几年是好几个一年。", "primary_collocate": null, "pronunciation": "jǐ nián", "ipa": "tɕi˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我学了几年汉语，现在能看懂中文书。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京住了好几年。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个病要治几年才能好？", "target_word": "几年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路修了几年，还没修好。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们认识几年了，从来没吵过架。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练习，练了几年，唱得很好。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这所学校教了几年书。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们结婚几年了？孩子多大了？", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵树长了好几年，才长到这么高。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人在外面生活了几年，已经习惯了。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好几年", "label": "复合"}, {"form": "前几年", "label": "复合"}], "register": "通用", "sense_fingerprint": "好几个一年，用来计算做某事所花的年数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指好几个一年，与“学了……汉语，现在能看懂中文书”的长时间学习相合。"}, {"text": "一会儿", "is_correct": false, "explanation": "语义：“一会儿”只有很短的时间，学不到能看懂中文书的程度。"}, {"text": "半天", "is_correct": false, "explanation": "语义：“半天”时间太短，与“现在能看懂中文书”的结果不符。"}, {"text": "整夜", "is_correct": false, "explanation": "搭配：“学了整夜”只说熬夜，不能用来说长期学习汉语。"}], "explanations": {"几年": "“几年”指好几个一年，与“学了……汉语，现在能看懂中文书”的长时间学习相合。", "一会儿": "语义：“一会儿”只有很短的时间，学不到能看懂中文书的程度。", "半天": "语义：“半天”时间太短，与“现在能看懂中文书”的结果不符。", "整夜": "搭配：“学了整夜”只说熬夜，不能用来说长期学习汉语。"}, "sentence_index": 0, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥修了几年，两天就完工了。", "explanation": "这里应该用〈几天〉。“几年”计算的是很长的时段，与“两天就完工”相冲突。"}, {"text": "这次晚会我唱了几年歌，非常精彩。", "explanation": "这里应该用〈唱了一首〉。“几年”计算的是做某事所花的年数，不能用于一次晚会。"}, {"text": "我的手机用了几年，昨天刚买的。", "explanation": "“几年”与“昨天刚买的”的时间相冲突；若改为“前几年买的”则成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指好几个一年，与“在这所学校教了……书”相合。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”只是一会儿，不能用来计算在学校教书的年数。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“教了清晨书”不成立，“清晨”不能作为教书的时段。"}, {"text": "一晚上", "is_correct": false, "explanation": "语义：“一晚上”指一个夜晚，与在学校任教的长期工作不符。"}], "explanations": {"几年": "“几年”指好几个一年，与“在这所学校教了……书”相合。", "片刻": "语义：“片刻”只是一会儿，不能用来计算在学校教书的年数。", "清晨": "搭配：“教了清晨书”不成立，“清晨”不能作为教书的时段。", "一晚上": "语义：“一晚上”指一个夜晚，与在学校任教的长期工作不符。"}, "sentence_index": 6, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年龄是几年，已经二十岁了。", "explanation": "这里应该用〈几岁〉。“几年”指年数，不能用来说年龄。"}, {"text": "他一个人吃了几年饭，三分钟就吃完了。", "explanation": "这里应该用〈几分钟〉。“几年”指长时段，与“三分钟就吃完”相冲突。"}, {"text": "这辆车他开了几年，一趟就开到了学校。", "explanation": "这里应该用〈几分钟〉。“几年”指长时段，与“一趟就开到学校”的短途相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学着几年钢琴，现在弹得很好。", "corrected_sentence": "他学了几年钢琴，现在弹得很好。", "error_description": "错误：“学着几年”。正确：“学了几年”。“几年”计算已完成的学习时段，要与完成体“了”搭配，不能用持续体“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在北京学了很几年钢琴，现在能给朋友伴奏。", "corrected_sentence": "她在北京学了几年钢琴，现在能给朋友伴奏。", "error_description": "错误：“很几年”。正确：“几年”。“几年”本身表示不确定的数量，前面不能再加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
