INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不确定的若干年。", "primary_collocate": null, "pronunciation": "jǐ nián", "ipa": "tɕi˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他去国外工作了，过了几年才回来。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前几年这里还是一片农田。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再过几年，我就要退休了。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几年前，他在这家公司上班。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他会在这里住几年。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她离开家乡几年后，变了很多。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了几年，这个小镇变得很热闹。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说过，再等几年，孩子就能自己做饭了。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前几年天气没有这么热，现在夏天太难熬了。", "target_word": "几年", "complexity_tier": "T3", "furigana": "jǐ nián", "sentence_source": "generated"}, {"text": "没过几年，他们就搬到了大城市。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "前几年", "label": "复合"}, {"form": "好几年", "label": "复合"}], "register": "通用", "sense_fingerprint": "不确定的若干年，泛指过去或将来的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指不确定的若干年，与“过了……才回来”这种长时段相合。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“半夜”指深夜的一段时间，与“去国外工作”的长时段不符。"}, {"text": "半个钟头", "is_correct": false, "explanation": "语义：“半个钟头”太短，与“去国外工作”的长时段不符。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“过了”后接的时段要与“去国外工作了”相称，“清晨”只指一天的早晨，不能这样搭配。"}], "explanations": {"几年": "“几年”指不确定的若干年，与“过了……才回来”这种长时段相合。", "半夜": "语义：“半夜”指深夜的一段时间，与“去国外工作”的长时段不符。", "半个钟头": "语义：“半个钟头”太短，与“去国外工作”的长时段不符。", "清晨": "搭配：“过了”后接的时段要与“去国外工作了”相称，“清晨”只指一天的早晨，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生日是几年，我忘了。", "explanation": "这里应该用〈某月某日〉。“几年”指不确定的年数，不能指一个具体的日期。"}, {"text": "我昨天下班，花了几年才到家。", "explanation": "这里应该用〈一个小时〉。“几年”指较长的时段，不能用来说一次很短的行程。"}, {"text": "我们明天见面，几年后再说吧。", "explanation": "这里应该用〈过几天〉。“几年后”指很远的将来，与“明天见面”相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指不确定的若干年，与“过了……这个小镇变得很热闹”的渐进变化相合。"}, {"text": "一本书", "is_correct": false, "explanation": "语义：“一本书”是物量，不能作“过了”的时段，句意不通。"}, {"text": "几块钱", "is_correct": false, "explanation": "语义：“几块钱”是金额，不能作“过了”的时段，句意不通。"}, {"text": "一张纸", "is_correct": false, "explanation": "语义：“一张纸”是物量，不能作“过了”的时段，句意不通。"}], "explanations": {"几年": "“几年”指不确定的若干年，与“过了……这个小镇变得很热闹”的渐进变化相合。", "一本书": "语义：“一本书”是物量，不能作“过了”的时段，句意不通。", "几块钱": "语义：“几块钱”是金额，不能作“过了”的时段，句意不通。", "一张纸": "语义：“一张纸”是物量，不能作“过了”的时段，句意不通。"}, "sentence_index": 6, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小学到大学，正好读了几年。", "explanation": "这里应该用〈十几年〉。“几年”是不确定的年数，但“正好”要求精确，两者不能同用。"}, {"text": "他的年龄是几年，已经二十岁了。", "explanation": "这里应该用〈几岁〉。“几年”指年数，不能用来说年龄。"}, {"text": "这件事我想了几年，三分钟就想好了。", "explanation": "这里应该用〈几分钟〉。“几年”指长时段，与“三分钟就想好”相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在北京读书，过着几年才毕业。", "corrected_sentence": "他在北京读书，过了几年才毕业。", "error_description": "错误：“过着几年”。正确：“过了几年”。“过了”表示时段已经过去；“着”表示持续状态，不能与“几年”这样已完成的时段搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在上海工作了很几年，现在才回家。", "corrected_sentence": "她在上海工作了好几年，现在才回家。", "error_description": "错误：“很几年”。正确：“好几年”。“好几”是固定说法，表示数量多，不能用“很”修饰“几”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜里", "is_correct": true, "explanation": "正确：夜里指夜间，与白天（日里）相反。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天指季节，与日里表示的时段不构成反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间指空间，与日里表示的时间不构成反义关系。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是物品，与日里表示的时间无反义关系。"}], "correct_answer": "夜里", "explanations": {"夜里": "正确：夜里指夜间，与白天（日里）相反。", "春天": "语义：春天指季节，与日里表示的时段不构成反义关系。", "房间": "语义：房间指空间，与日里表示的时间不构成反义关系。", "电脑": "语义：电脑是物品，与日里表示的时间无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜里", "is_correct": true, "explanation": "正确：夜里指夜间，与白天（日里）相反。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天指季节，与日里表示的时段不构成反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，与日里表示的时间无反义关系。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园指地点，与日里表示的时间无反义关系。"}], "correct_answer": "夜里", "explanations": {"夜里": "正确：夜里指夜间，与白天（日里）相反。", "冬天": "语义：冬天指季节，与日里表示的时段不构成反义关系。", "书桌": "语义：书桌是家具，与日里表示的时间无反义关系。", "公园": "语义：公园指地点，与日里表示的时间无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "白天；日间。", "primary_collocate": null, "pronunciation": "rì lǐ", "ipa": "ʐɨ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "日里他在外面工作，晚上才回家。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的日里很热，晚上才凉快。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里街上人多，晚上很安静。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她日里在学校教书，夜里写文章。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里天气很好，我们去公园玩儿。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里有太阳，夜里能看见星星。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他日里睡觉，晚上出去上班。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里村里的人都在田里干活。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里我很少在家，常常去图书馆。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店日里不开门，夜里才做生意。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "白天，日间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日里", "is_correct": true, "explanation": "正确：日里指白天，“日里他在外面工作，晚上才回家”成立。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：夜里指夜间，与后半句的“晚上”时间重叠，句意矛盾。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜指深夜，与“在外面工作”的时段冲突，句子不通。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是深夜，与后文“晚上才回家”的安排矛盾，句子不通。"}], "explanations": {"日里": "正确：日里指白天，“日里他在外面工作，晚上才回家”成立。", "夜里": "语义：夜里指夜间，与后半句的“晚上”时间重叠，句意矛盾。", "半夜": "语义：半夜指深夜，与“在外面工作”的时段冲突，句子不通。", "午夜": "语义：午夜是深夜，与后文“晚上才回家”的安排矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "日里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们日里去看星星。", "explanation": "这里应该用〈晚上〉。日里指白天，看星星要在晚上。"}, {"text": "天黑以后，他日里出门散步。", "explanation": "这里应该用〈夜里〉。日里指白天，天黑以后应说夜里。"}, {"text": "她日里凌晨两点还在写文章。", "explanation": "这里应该用〈半夜〉。日里指白天，凌晨两点是夜里，应说半夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日里", "is_correct": true, "explanation": "正确：日里指白天，“他日里睡觉，晚上出去上班”成立。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：夜里睡觉与后文“晚上出去上班”都在夜间，句意矛盾。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜指夜里，与后文“晚上出去上班”的时段冲突。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是一周的单位，不能指睡觉的时段，句子不通。"}], "explanations": {"日里": "正确：日里指白天，“他日里睡觉，晚上出去上班”成立。", "夜里": "语义：夜里睡觉与后文“晚上出去上班”都在夜间，句意矛盾。", "深夜": "语义：深夜指夜里，与后文“晚上出去上班”的时段冲突。", "星期": "语义：星期是一周的单位，不能指睡觉的时段，句子不通。"}, "sentence_index": 6, "correct_answer": "日里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他日里在月光下读书。", "explanation": "这里应该用〈夜里〉。日里指白天，月光下读书应说夜里。"}, {"text": "他日里和朋友一起在夜市吃烧烤。", "explanation": "这里应该用〈晚上〉。日里指白天，夜市要在晚上才开。"}, {"text": "日里的月亮很圆，我们在院子里赏月。", "explanation": "这里应该用〈夜里〉。日里指白天，赏月要在夜里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥日里了在医院上班。", "corrected_sentence": "我哥哥日里在医院上班。", "error_description": "错误：「日里了」，时间词「日里」后不能直接加动态助词「了」。正确说法是「我哥哥日里在医院上班」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家面馆日里的很热闹。", "corrected_sentence": "这家面馆日里很热闹。", "error_description": "错误：「日里的很热闹」，时间词「日里」后多出了结构助词「的」，「的」后面缺少中心语。正确说法是「这家面馆日里很热闹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
