INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "当局是管理一个地方或一件事的人。", "primary_collocate": null, "pronunciation": "dāng jú", "ipa": "taŋ˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "当局已经通知大家，明天不上课。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校当局决定，下个月开始放假。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局请市民不要去那个地方。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园当局说，晚上八点以后不能进去。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局说，这件事他们会马上处理。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场当局告诉旅客，飞机要晚三个小时起飞。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，当局已经知道了。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局正在找那个丢了钱包的人。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球场当局把比赛的时间改到了下午。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当局希望大家在家里等着，不要出门。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "负责管理某地或某事的人，指有权做决定的管理者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当局", "is_correct": true, "explanation": "当局：指有管理权、能发布通知的机关或负责人，符合“通知大家停课”的语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不能向大家发布通知，与“通知大家”的语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“通知”要求能发出信息的主体，“天气”不能作“通知”的主语。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不能通知大家明天不上课。"}], "explanations": {"当局": "当局：指有管理权、能发布通知的机关或负责人，符合“通知大家停课”的语境。", "小猫": "语义：“小猫”不能向大家发布通知，与“通知大家”的语境不符。", "天气": "搭配：“通知”要求能发出信息的主体，“天气”不能作“通知”的主语。", "蛋糕": "语义：“蛋糕”是食物，不能通知大家明天不上课。"}, "sentence_index": 0, "correct_answer": "当局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当局每天接送孩子上学。", "explanation": "这里应该用〈家长〉。当局指负责管理的机关或人员，不负责接送孩子等具体的家庭事务。"}, {"text": "当局每天写小说。", "explanation": "这里应该用〈作家〉。当局指负责管理的机关或人员，不指从事写作的人，也不进行小说创作。"}, {"text": "当局在舞台上表演。", "explanation": "这里应该用〈演员〉。当局指负责管理的机关或人员，不指在舞台上表演的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当局", "is_correct": true, "explanation": "当局：指负责管理的机关或人员，这里指他们已经掌握了这件事的情况。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能知道事情，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不能“知道”事情。"}, {"text": "消息", "is_correct": false, "explanation": "搭配：“知道”的主语要是人或机构，“消息”不能作“知道”的主语。"}], "explanations": {"当局": "当局：指负责管理的机关或人员，这里指他们已经掌握了这件事的情况。", "石头": "语义：“石头”不能知道事情，句意不通。", "雨伞": "语义：“雨伞”是物品，不能“知道”事情。", "消息": "搭配：“知道”的主语要是人或机构，“消息”不能作“知道”的主语。"}, "sentence_index": 6, "correct_answer": "当局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当局每天给我做早饭。", "explanation": "这里应该用〈妈妈〉。当局指负责管理的机关或人员，不做家里的做饭等个人事务。"}, {"text": "当局在院子里玩。", "explanation": "这里应该用〈孩子〉。当局指负责管理的机关或人员，不指在院子里玩耍的小孩。"}, {"text": "当局在路上开车很小心。", "explanation": "这里应该用〈司机〉。当局指管理机关，不指驾驶车辆的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只当局宣布了新的规定。", "corrected_sentence": "这个当局宣布了新的规定。", "error_description": "错误：“这只当局”。“当局”指负责管理的机关或人员，量词应用“个”，不能用“只”（“只”多用于动物等）。正确：“这个当局”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一当局决定暂时关闭这座公园。", "corrected_sentence": "一个当局决定暂时关闭这座公园。", "error_description": "错误：“一当局”。正确：“一个当局”。数词与名词之间需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
