INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指政府、机关等负责管理的部门或人员。", "primary_collocate": null, "pronunciation": "dāng jú", "ipa": "taŋ˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "当地当局决定，在河边建一座新桥。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局对这次事故很重视。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局提高了学校附近的安全要求。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说当局想把这条老街留下来。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关当局说，明年会给老人更多帮助。", "target_word": "当局", "complexity_tier": "T3", "furigana": "yǒu guān dāng jú shuō, míng nián huì gěi lǎo rén gèng duō bāng zhù.", "sentence_source": "generated"}, {"text": "当局要求所有商店都要在晚上十点关门。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国当局正在谈这个问题。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局没有回答记者的问题。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向当局写信，希望他们帮助这个村子。", "target_word": "当局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当局已经把那些旧房子都拆了。", "target_word": "当局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "政府、机关等负责管理的部门，常见于新闻报道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53213dc2-9c6c-47f8-bb86-afaf018223d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当局", "is_correct": true, "explanation": "当局：指当地负责管理的机关，有权决定在河边建桥。"}, {"text": "河水", "is_correct": false, "explanation": "语义：“河水”不能作决定的主体，句意不通。"}, {"text": "大树", "is_correct": false, "explanation": "语义：“大树”不会做决定，与句意不符。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“决定”要求有决策权的主体，“孩子”不能对建桥作决定。"}], "explanations": {"当局": "当局：指当地负责管理的机关，有权决定在河边建桥。", "河水": "语义：“河水”不能作决定的主体，句意不通。", "大树": "语义：“大树”不会做决定，与句意不符。", "孩子": "搭配：“决定”要求有决策权的主体，“孩子”不能对建桥作决定。"}, "sentence_index": 0, "correct_answer": "当局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当局每天在厨房做饭。", "explanation": "这里应该用〈厨师〉。当局指负责管理的机关或人员，不做具体的做饭工作。"}, {"text": "当局在舞台上唱歌。", "explanation": "这里应该用〈歌手〉。当局指负责管理的机关或人员，不指在舞台上唱歌的人。"}, {"text": "当局正在给病人打针。", "explanation": "这里应该用〈医生〉。当局指管理机构，不负责为病人打针等具体医疗工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当局", "is_correct": true, "explanation": "当局：指两国负责管理的机关或人员，这里是正式磋商的一方。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能“谈问题”。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是物品，不能谈论问题。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“谈问题”的主语须是能发言的人或机构，“窗户”不能与“谈”搭配。"}], "explanations": {"当局": "当局：指两国负责管理的机关或人员，这里是正式磋商的一方。", "西瓜": "语义：“西瓜”是水果，不能“谈问题”。", "手套": "语义：“手套”是物品，不能谈论问题。", "窗户": "搭配：“谈问题”的主语须是能发言的人或机构，“窗户”不能与“谈”搭配。"}, "sentence_index": 6, "correct_answer": "当局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当局每天开车接送乘客。", "explanation": "这里应该用〈司机〉。当局指管理机关或人员，不指驾驶车辆的人。"}, {"text": "当局给客人剪头发。", "explanation": "这里应该用〈理发师〉。当局是负责管理的机关，不做剪头发等具体服务。"}, {"text": "当局在画室里画画。", "explanation": "这里应该用〈画家〉。当局指负责管理的机关或人员，不指在画室里画画的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只当局研究了这个方案。", "corrected_sentence": "这个当局研究了这个方案。", "error_description": "“当局”是机构，量词应用“个”，不能用“只”（“只”多用于动物等）。错误形式：这只当局；正确形式：这个当局。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一当局已经同意了这项计划。", "corrected_sentence": "一个当局已经同意了这项计划。", "error_description": "错误：“一当局”。正确：“一个当局”。数词与名词之间需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb1c2a2e-03da-4ed5-bce6-00a598dcbe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和平", "is_correct": true, "explanation": "反义：“和平”与“战争”相对，是这一义项的反义词。"}, {"text": "家庭", "is_correct": false, "explanation": "无关：“家庭”是社会单位，与“战争”没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "无关：“学校”是场所，与“战争”没有反义关系。"}, {"text": "城市", "is_correct": false, "explanation": "无关：“城市”是地点，与“战争”没有反义关系。"}], "correct_answer": "和平", "explanations": {"和平": "反义：“和平”与“战争”相对，是这一义项的反义词。", "家庭": "无关：“家庭”是社会单位，与“战争”没有反义关系。", "学校": "无关：“学校”是场所，与“战争”没有反义关系。", "城市": "无关：“城市”是地点，与“战争”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和平", "is_correct": true, "explanation": "反义：“和平”与“战争”相对，是这一义项的反义词。"}, {"text": "经济", "is_correct": false, "explanation": "无关：“经济”是另一领域的概念，与“战争”没有反义关系。"}, {"text": "科学", "is_correct": false, "explanation": "无关：“科学”是另一领域的概念，与“战争”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”是自然现象，与“战争”没有反义关系。"}], "correct_answer": "和平", "explanations": {"和平": "反义：“和平”与“战争”相对，是这一义项的反义词。", "经济": "无关：“经济”是另一领域的概念，与“战争”没有反义关系。", "科学": "无关：“科学”是另一领域的概念，与“战争”没有反义关系。", "天气": "无关：“天气”是自然现象，与“战争”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "战争是两边的人拿着武器打起来，很多人会受伤。", "primary_collocate": null, "pronunciation": "zhàn zhēng", "ipa": "ʈʂan˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "战争让很多人没有家。", "target_word": "战争", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不喜欢战争。", "target_word": "战争", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家有过一场很长的战争。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争里，很多孩子失去了爸爸妈妈。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候经历过战争。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望世界上没有战争。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争开始以后，人们只能离开家。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的战争，让我觉得很可怕。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束了，大家高兴地回家了。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那场战争打了五年，很多人受伤了。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场战争", "label": "量词"}, {"form": "戰爭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两边的人拿武器打仗，让人受伤、失去家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“战争”是造成人们失去家的原因，句意通顺。"}, {"text": "和平", "is_correct": false, "explanation": "语义：和平不会让很多人失去家，与句中“失去家”的损失之义相反，句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不会让很多人失去家，与句中的损失之义冲突。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不会让人失去家，句意不通。"}], "explanations": {"战争": "正确：“战争”是造成人们失去家的原因，句意通顺。", "和平": "语义：和平不会让很多人失去家，与句中“失去家”的损失之义相反，句意不通。", "音乐": "语义：音乐不会让很多人失去家，与句中的损失之义冲突。", "春天": "语义：“春天”是季节，不会让人失去家，句意不通。"}, "sentence_index": 0, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间打了一座战争，持续了三年。", "explanation": "这里应该用〈场〉。“座”用于山、桥等大型固定物，不能用来数“战争”，应说“一场战争”。"}, {"text": "他们打了一个战争，持续了三年。", "explanation": "这里应该用〈场〉。“战争”的量词是“场”，不说“一个战争”。"}, {"text": "两国之间进行了一场友好的战争。", "explanation": "这里应该用〈和平〉。“战争”指武力斗争，与“友好”的含义相矛盾，两国友好相处应说“和平”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“战争”开始以后，人们只能离开家，句意通顺。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛开始后人们不会被迫离开家，与句中的因果不合。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节不会迫使人们只能离开家，句意不通。"}, {"text": "晚会", "is_correct": false, "explanation": "配价：“晚会”是活动名称，不能表示迫使人离开家的事件。"}], "explanations": {"战争": "正确：“战争”开始以后，人们只能离开家，句意通顺。", "比赛": "语义：比赛开始后人们不会被迫离开家，与句中的因果不合。", "春节": "语义：春节不会迫使人们只能离开家，句意不通。", "晚会": "配价：“晚会”是活动名称，不能表示迫使人离开家的事件。"}, "sentence_index": 6, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们打了一支战争，全国都很紧张。", "explanation": "这里应该用〈场〉。“支”多用于队伍、笔等，不能用来数“战争”，应说“一场战争”。"}, {"text": "他和同学打了一顿战争，常常吵架。", "explanation": "这里应该用〈场〉。“顿”用于吃饭、挨打，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间打了一条战争，持续了三年。", "explanation": "这里应该用〈场〉。“条”用于细长的东西，不能用来数“战争”，应说“一场战争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个时代曾经发生过一个战争。", "corrected_sentence": "那个时代曾经发生过一场战争。", "error_description": "“战争”的量词应为“场”，不能说“一个战争”，应为“一场战争”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那战争持续了五年。", "corrected_sentence": "那场战争持续了五年。", "error_description": "“那”后面的“战争”缺少量词“场”，应为“那场战争”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和平", "is_correct": true, "explanation": "反义：“和平”与“战争”相对，是这一义项的反义词。"}, {"text": "城市", "is_correct": false, "explanation": "无关：“城市”是地点，与“战争”没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "无关：“学校”是场所，与“战争”没有反义关系。"}, {"text": "科学", "is_correct": false, "explanation": "无关：“科学”是知识领域，与“战争”没有反义关系。"}], "correct_answer": "和平", "explanations": {"和平": "反义：“和平”与“战争”相对，是这一义项的反义词。", "城市": "无关：“城市”是地点，与“战争”没有反义关系。", "学校": "无关：“学校”是场所，与“战争”没有反义关系。", "科学": "无关：“科学”是知识领域，与“战争”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和平", "is_correct": true, "explanation": "反义：“和平”与“战争”相对，是这一义项的反义词。"}, {"text": "语言", "is_correct": false, "explanation": "无关：“语言”是交流工具，与“战争”没有反义关系。"}, {"text": "文化", "is_correct": false, "explanation": "无关：“文化”是社会现象，与“战争”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”是自然现象，与“战争”没有反义关系。"}], "correct_answer": "和平", "explanations": {"和平": "反义：“和平”与“战争”相对，是这一义项的反义词。", "语言": "无关：“语言”是交流工具，与“战争”没有反义关系。", "文化": "无关：“文化”是社会现象，与“战争”没有反义关系。", "天气": "无关：“天气”是自然现象，与“战争”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或集团之间用武力进行的斗争。", "primary_collocate": null, "pronunciation": "zhàn zhēng", "ipa": "ʈʂan˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "两国之间的战争持续了三年。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场战争对经济影响很大。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写着这次战争的原因。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给两个国家带来了很大的损失。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用谈判代替战争。", "target_word": "战争", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场战争结束以后，两国签了和平协议。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争会破坏一个国家的发展。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国希望各国停止战争。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家为了资源发动战争。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写过一本关于战争的书。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场战争", "label": "量词"}, {"form": "戰爭", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家或集团之间的武力冲突，常谈原因、影响和结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“两国之间的战争”指两国之间的武力冲突，持续三年符合语境。"}, {"text": "晚餐", "is_correct": false, "explanation": "配价：“晚餐”是一次性的具体事件，不能作“持续了三年”的主语。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是个人的疾病，与两国之间的关系不符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不是两国之间的武力冲突，句意不通。"}], "explanations": {"战争": "正确：“两国之间的战争”指两国之间的武力冲突，持续三年符合语境。", "晚餐": "配价：“晚餐”是一次性的具体事件，不能作“持续了三年”的主语。", "感冒": "语义：“感冒”是个人的疾病，与两国之间的关系不符。", "电影": "语义：“电影”不是两国之间的武力冲突，句意不通。"}, "sentence_index": 0, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间打了一艘战争，持续了三年。", "explanation": "这里应该用〈场〉。“艘”用于船只，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间发生了一场友好的战争。", "explanation": "这里应该用〈和平〉。“战争”指武力斗争，与“友好”的含义相矛盾，友好相处应说“和平”。"}, {"text": "两国之间打了一个战争。", "explanation": "这里应该用〈场〉。“战争”的量词是“场”，不说“一个战争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“战争会破坏一个国家的发展”符合常识，句意通顺。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会破坏一个国家的发展，句意不通。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不会破坏国家发展，与句意不符。"}, {"text": "花朵", "is_correct": false, "explanation": "配价：“花朵”不能作“破坏”的施事，搭配不当。"}], "explanations": {"战争": "正确：“战争会破坏一个国家的发展”符合常识，句意通顺。", "歌曲": "语义：歌曲不会破坏一个国家的发展，句意不通。", "笑声": "语义：笑声不会破坏国家发展，与句意不符。", "花朵": "配价：“花朵”不能作“破坏”的施事，搭配不当。"}, "sentence_index": 6, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国之间打了一条战争，边境很紧张。", "explanation": "这里应该用〈场〉。“条”用于细长的东西，不能用来数“战争”，应说“一场战争”。"}, {"text": "他们之间打了一顿战争，持续了三年。", "explanation": "这里应该用〈场〉。“顿”用于吃饭、挨打，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间进行了一把战争，持续了三年。", "explanation": "这里应该用〈场〉。“把”用于有柄的器具，不能用来数“战争”，应说“一场战争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多国家都希望避免一个战争。", "corrected_sentence": "很多国家都希望避免战争。", "error_description": "错误在于“战争”前多加了“一个”；“避免战争”的“战争”不带数量词，应为“很多国家都希望避免战争”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国之间的那战争结束了。", "corrected_sentence": "两国之间的那场战争结束了。", "error_description": "“那”后面的“战争”缺少量词“场”，应为“那场战争”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
