INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86142, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "关押被判刑的犯人的场所。", "primary_collocate": null, "pronunciation": "jiān yù", "ipa": "tɕjɛn˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "法官说他要在监狱里待三年。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人在监狱里要做工。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所监狱关着两百多个犯人。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出了监狱，找到一份新工作。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱里的饭很简单。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者去监狱采访了一位犯人。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的哥哥在监狱里工作，是警察。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人每天在监狱里学习。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座监狱建在山里，离城很远。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从监狱出来后，当了老师。", "target_word": "监狱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座监狱", "label": "量词"}, {"form": "一所监狱", "label": "量词"}, {"form": "監獄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关押被判刑犯人的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc80c1b1-8ff1-4e63-afc6-b13565b16d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶装不下人，“在花瓶里待三年”句意荒谬。"}, {"text": "监狱", "is_correct": true, "explanation": "正确：监狱是关押被判刑犯人的场所，法官判他待三年，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能让人待三年，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“待在……里”的处所要能容人，“手机”不能让人待在里面。"}], "explanations": {"花瓶": "语义：花瓶装不下人，“在花瓶里待三年”句意荒谬。", "监狱": "正确：监狱是关押被判刑犯人的场所，法官判他待三年，符合句意。", "书包": "语义：书包不能让人待三年，句意不通。", "手机": "搭配：“待在……里”的处所要能容人，“手机”不能让人待在里面。"}, "sentence_index": 0, "correct_answer": "监狱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为打架在一台监狱里待了三天，然后就回家了。", "explanation": "这里应该用〈座〉或〈所〉。“台”用于机器、器械等，监狱是建筑，不能用“台”计量。"}, {"text": "他在一朵监狱里待了很久。", "explanation": "这里应该用〈座〉或〈所〉。“朵”用于花、云等，监狱不能用“朵”计量。"}, {"text": "警察带他走进了一本监狱。", "explanation": "这里应该用〈座〉或〈所〉。“本”用于书籍，监狱不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：警察不会在厨房工作，“警察”与“厨房”的组合不合理。"}, {"text": "监狱", "is_correct": true, "explanation": "正确：警察的工作单位是监狱，符合句意。"}, {"text": "鱼缸", "is_correct": false, "explanation": "搭配：“在……里工作”的处所要是工作场所，鱼缸不是。"}, {"text": "纸箱", "is_correct": false, "explanation": "语义：纸箱不是人工作的地方，句意不通。"}], "explanations": {"厨房": "语义：警察不会在厨房工作，“警察”与“厨房”的组合不合理。", "监狱": "正确：警察的工作单位是监狱，符合句意。", "鱼缸": "搭配：“在……里工作”的处所要是工作场所，鱼缸不是。", "纸箱": "语义：纸箱不是人工作的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "监狱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从一颗监狱出来后，当了老师。", "explanation": "这里应该用〈座〉或〈所〉。“颗”用于圆粒状的东西，监狱是建筑，不能用“颗”。"}, {"text": "他从一片监狱出来后，当了老师。", "explanation": "这里应该用〈座〉或〈所〉。“片”用于平面或大片的景物，监狱不能用“片”计量。"}, {"text": "他从一扇监狱出来后，当了老师。", "explanation": "这里应该用〈座〉或〈所〉。“扇”用于门窗，监狱不能用“扇”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被判了两年，要监狱里服刑。", "corrected_sentence": "他被判了两年，要在监狱里服刑。", "error_description": "错误形式：“要监狱里服刑”；正确形式：“要在监狱里服刑”。表示在某处服刑，处所前要加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个司机因为醉驾被送进了一包监狱。", "corrected_sentence": "那个司机因为醉驾被送进了一所监狱。", "error_description": "错误形式：“一包监狱”；正确形式：“一所监狱”。“包”用于成包的东西，监狱是机构，应用“所”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
