INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "读者是看书、看报的人。", "primary_collocate": null, "pronunciation": "dú zhě", "ipa": "tu˧˥ ʈʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "这本书有很多读者。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是这份报纸的读者。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读者都喜欢看这位作家的书。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老读者知道他每天都看报。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给读者写了一封信。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店来了很多小读者。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读者在图书馆里安静地看书。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位读者想借三本书。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的读者来信很有意思。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好书会有很多读者。", "target_word": "读者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "讀者", "label": "繁体"}, {"form": "小读者", "label": "复合"}], "register": "中性", "sense_fingerprint": "读者：看书、看报的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f931a9f9-e62e-44dc-9fd3-572b2af66ba9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "读者", "is_correct": true, "explanation": "读者：阅读这本书的人，符合“这本书有很多”的语境。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：“观众”指看演出、比赛的人，书没有观众。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校学习的人，不能说一本书有很多学生。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指教人的人，不能说一本书有很多老师。"}], "explanations": {"读者": "读者：阅读这本书的人，符合“这本书有很多”的语境。", "观众": "搭配：“观众”指看演出、比赛的人，书没有观众。", "学生": "语义：“学生”指在校学习的人，不能说一本书有很多学生。", "老师": "语义：“老师”指教人的人，不能说一本书有很多老师。"}, "sentence_index": 0, "correct_answer": "读者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院里坐满了读者。", "explanation": "这里应该用〈观众〉。读者指看书、看报的人，看电影、演出的人要用“观众”。"}, {"text": "医院的手术室里站满了读者。", "explanation": "这里应该用〈医生〉。读者指看书、看报的人，在手术室做手术的人要用“医生”。"}, {"text": "这家超市今天来了很多读者。", "explanation": "这里应该用〈顾客〉。读者指看书、看报的人，到超市买东西的人要用“顾客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读者", "is_correct": true, "explanation": "读者：阅读的人，句中“在图书馆里安静地看书”正指读书的人。"}, {"text": "听众", "is_correct": false, "explanation": "语义：“听众”指听讲座、演出的人，与“看书”冲突。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”与车、船搭配，图书馆里不说乘客。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：“球迷”指喜爱体育的人，不会在图书馆里看书。"}], "explanations": {"读者": "读者：阅读的人，句中“在图书馆里安静地看书”正指读书的人。", "听众": "语义：“听众”指听讲座、演出的人，与“看书”冲突。", "乘客": "搭配：“乘客”与车、船搭配，图书馆里不说乘客。", "球迷": "语义：“球迷”指喜爱体育的人，不会在图书馆里看书。"}, "sentence_index": 6, "correct_answer": "读者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台上的读者表演得很好。", "explanation": "这里应该用〈演员〉。读者指阅读书报刊的人，表演要用“演员”。"}, {"text": "厨房里，读者正在炒菜。", "explanation": "这里应该用〈厨师〉。读者指阅读书报刊的人，在厨房炒菜的人要用“厨师”。"}, {"text": "音乐会上的读者很安静。", "explanation": "这里应该用〈听众〉。读者指阅读书报刊的人，在音乐会上听演奏的人要用“听众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只读者经常来借书。", "corrected_sentence": "这位读者经常来借书。", "error_description": "“这只读者”量词用错：读者指人，量词应用“位”，“只”多用于动物，应改为“这位读者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位读者们每天都来借书。", "corrected_sentence": "一位读者每天都来借书。", "error_description": "错误形式是“一位读者们”，正确形式是“一位读者”。“们”表示复数，不能与数量词“一位”同用，去掉“们”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
