INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总统是有的国家里最大的领导人。", "primary_collocate": null, "pronunciation": "zǒng tǒng", "ipa": "tsʊŋ˧˥ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "总统明天要去中国访问。", "target_word": "总统", "complexity_tier": "T3", "furigana": "zǒngtǒng míngtiān yào qù Zhōngguó fǎngwèn", "sentence_source": "generated"}, {"text": "这个国家的总统是一位女士。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新总统昨天在电视上讲话了。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们选他当国家的总统。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统坐飞机去了很多国家。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统先生请大家安静。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想当总统，所以每天都很忙。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视里的总统笑着和孩子们说话。", "target_word": "总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统的办公室在这座白色的楼里。", "target_word": "总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老总统已经八十岁了，身体很好。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副总统", "label": "复合"}, {"form": "總統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，指某些国家里最大的领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c60b75e-2343-4e04-9358-7c28ad6f9510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总统", "is_correct": true, "explanation": "正确。“总统”是国家的最高领导人，可以去别国访问。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不能以国家领导人的身份去中国访问。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“访问”的主语要是人，“桌子”不能做“访问”的主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能去中国访问。"}], "explanations": {"总统": "正确。“总统”是国家的最高领导人，可以去别国访问。", "猫": "语义：猫是动物，不能以国家领导人的身份去中国访问。", "桌子": "搭配：“访问”的主语要是人，“桌子”不能做“访问”的主语。", "窗户": "语义：窗户是建筑部件，不能去中国访问。"}, "sentence_index": 0, "correct_answer": "总统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的总统每天早上都要讲话。", "explanation": "这里应该用〈校长〉。“总统”指国家元首；学校的负责人要说“校长”。"}, {"text": "这家公司的总统每周都开一次会。", "explanation": "这里应该用〈总裁〉。“总统”只用于国家元首；公司的最高负责人一般说“总裁”。"}, {"text": "这家医院的总统每周都来病房看看病人。", "explanation": "这里应该用〈院长〉。“总统”指国家元首；医院的负责人要说“院长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总统", "is_correct": true, "explanation": "正确。“当”后面接职务名词，“总统”符合句子语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“当”后面要接人的身份或职务，“石头”不能被“当”。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“当”接的是职业或身份，“西瓜”不能这样搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是人，不能说“想当”空气。"}], "explanations": {"总统": "正确。“当”后面接职务名词，“总统”符合句子语境。", "石头": "语义：“当”后面要接人的身份或职务，“石头”不能被“当”。", "西瓜": "搭配：“当”接的是职业或身份，“西瓜”不能这样搭配。", "空气": "语义：“空气”不是人，不能说“想当”空气。"}, "sentence_index": 6, "correct_answer": "总统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们厂的总统每个月都来车间看看工人。", "explanation": "这里应该用〈厂长〉。“总统”指国家元首；工厂的负责人要说“厂长”。"}, {"text": "我们村的总统每年春节都来看望老人。", "explanation": "这里应该用〈村长〉。“总统”指国家元首；村子的负责人要说“村长”。"}, {"text": "这次会议的总统每次都提前十分钟到场。", "explanation": "这里应该用〈主席〉。“总统”指国家元首；主持会议的人要说“主席”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家换了三只总统。", "corrected_sentence": "这个国家换了三位总统。", "error_description": "错误：量词“只”用错了。“总统”指人，量词应为“位”，不能用动物量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当过了总统，所以很有经验。", "corrected_sentence": "他当过总统，所以很有经验。", "error_description": "体标重复：“过”已表示经历，后面不能再加“了”，应写作“当过总统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc820342-f201-4351-941d-52226ac49228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
