INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比赛中的第一名。", "primary_collocate": null, "pronunciation": "guàn jūn", "ipa": "kwan˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "他在这次比赛中得了冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班这次拿到了冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁能得到今年的冠军，大家都在猜。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就想拿游泳比赛的冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队连续三年都拿到了冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了冠军，他每天练习五个小时。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛的冠军奖金是一万块钱。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年他只得了第二名，今年想要冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拿了冠军以后，她很高兴。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冠军的奖杯又大又漂亮。", "target_word": "冠军", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "总冠军", "label": "复合"}, {"form": "冠軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛的第一名这一名次，可以拿、得、争取", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冠军", "is_correct": true, "explanation": "正确：“得了”后接“冠军”，指在比赛中获得第一名。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是比赛中可以“得”到的东西，这里要的是名次。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“得”不搭配“作业”，应说“做作业”或“交作业”。"}, {"text": "脑袋", "is_correct": false, "explanation": "配价：“得”所带的宾语应是可以获得的东西，“脑袋”是身体部位，不能被“得”。"}], "explanations": {"冠军": "正确：“得了”后接“冠军”，指在比赛中获得第一名。", "窗户": "语义：窗户不是比赛中可以“得”到的东西，这里要的是名次。", "作业": "搭配：“得”不搭配“作业”，应说“做作业”或“交作业”。", "脑袋": "配价：“得”所带的宾语应是可以获得的东西，“脑袋”是身体部位，不能被“得”。"}, "sentence_index": 0, "correct_answer": "冠军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她从小就想提高游泳比赛的冠军。", "explanation": "这里应该用〈名次〉。“冠军”指固定的第一名，不能被“提高”；表示排位进步要说“提高名次”。"}, {"text": "这次比赛后，冠军的排名从第五升到了第三。", "explanation": "这里应该用〈排名〉。“冠军”指固定的第一名，不存在从第五升到第三的变化；排名才会升降。"}, {"text": "她在比赛中取得了好冠军。", "explanation": "这里应该用〈成绩〉。冠军是固定名次，不能用“好”来修饰，应说“取得好成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冠军", "is_correct": true, "explanation": "正确：“冠军奖金”指第一名的奖金，句意自然。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是比赛的奖项，不能用来修饰“奖金”。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不能修饰“奖金”，句中需要的是比赛的名次或奖项。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是人的外貌特征，不能修饰“奖金”。"}], "explanations": {"冠军": "正确：“冠军奖金”指第一名的奖金，句意自然。", "课本": "语义：课本不是比赛的奖项，不能用来修饰“奖金”。", "钥匙": "搭配：“钥匙”不能修饰“奖金”，句中需要的是比赛的名次或奖项。", "眉毛": "体貌：眉毛是人的外貌特征，不能修饰“奖金”。"}, "sentence_index": 6, "correct_answer": "冠军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她赢得了一张冠军。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，冠军是名次，不能用“张”来数。"}, {"text": "他拿到了一把冠军。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，冠军是名次，要用“个”。"}, {"text": "我们班赢得了一颗冠军。", "explanation": "这里应该用〈个〉。“颗”用于小而圆的东西，冠军要用“个”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年得了一只冠军。", "corrected_sentence": "她去年得了一个冠军。", "error_description": "量词错误：冠军作为名次要用量词“个”，“只”用于动物或成对物件中的一个，不能用来数“冠军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拿到了一块冠军。", "corrected_sentence": "她拿到了一个冠军。", "error_description": "量词错误：“冠军”作为名次要用量词“个”，“块”用于块状的东西，不能用来数“冠军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
