INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前人是很早以前就有的人。", "primary_collocate": null, "pronunciation": "qián rén", "ipa": "tɕʰjɛn˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "前人留下了很多好书。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要学习前人的经验。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前人早就发现了这个办法。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路是前人走出来的。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把前人的话记在本子上。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前人的故事教我们很多道理。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在前人的肩膀上，我们看得更远。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些房子都是前人盖的。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前人栽树，后人乘凉。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他读了很多前人写的书。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很早以前就生活过的人，指留下经验、作品的上一代人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f931a9f9-e62e-44dc-9fd3-572b2af66ba9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86171, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：很早以前的人，是本题要辨认的词。"}, {"text": "前任", "is_correct": false, "explanation": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。"}, {"text": "千人", "is_correct": false, "explanation": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。"}, {"text": "强人", "is_correct": false, "explanation": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。"}, {"text": "闲人", "is_correct": false, "explanation": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}], "explanations": {"前人": "前人：很早以前的人，是本题要辨认的词。", "前任": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。", "千人": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。", "强人": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。", "闲人": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}, "sentence_index": null, "correct_answer": "前人"}, "level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：很早以前的人，能留下好书，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”与车、船搭配，不会留下好书。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”指看演出、比赛的人，不会写书。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”的职责是开车，不会留下好书。"}], "explanations": {"前人": "前人：很早以前的人，能留下好书，符合句意。", "乘客": "搭配：“乘客”与车、船搭配，不会留下好书。", "观众": "语义：“观众”指看演出、比赛的人，不会写书。", "司机": "语义：“司机”的职责是开车，不会留下好书。"}, "sentence_index": 0, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天，前人来看望我们。", "explanation": "这里应该用〈长辈〉。前人指很早以前的人，不能说今天来看望我们。"}, {"text": "前人会继承我们的事业。", "explanation": "这里应该用〈后人〉。前人是过去的人，继承事业的应是后面的人。"}, {"text": "前人普遍使用智能手机。", "explanation": "这里应该用〈现代人〉。前人指过去的人，不能用来指现在使用智能手机的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：前代的人，其成果可以借鉴，句中“站在……的肩膀上”指借助前人的成就。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：“邻居”指住得近的人，不是可供借鉴的前代成果。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”指来参观的人，不是积累经验的前辈。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“站在……的肩膀上”指借助前人的成果，不与“厨师”搭配。"}], "explanations": {"前人": "前人：前代的人，其成果可以借鉴，句中“站在……的肩膀上”指借助前人的成就。", "邻居": "语义：“邻居”指住得近的人，不是可供借鉴的前代成果。", "游客": "语义：“游客”指来参观的人，不是积累经验的前辈。", "厨师": "搭配：“站在……的肩膀上”指借助前人的成果，不与“厨师”搭配。"}, "sentence_index": 6, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前人在学校教了我们三十年书。", "explanation": "这里应该用〈前辈〉。前人指很早以前的人，指同行中资历较深、教过自己的人要用“前辈”。"}, {"text": "我们的前人校长十年前就退休了。", "explanation": "这里应该用〈前任〉。前人指很早以前的人，指同一职位上的前一任要用“前任”。"}, {"text": "这位前人今年八十岁了。", "explanation": "这里应该用〈老人〉。前人指很早以前的人，指年纪大、仍在世的人要用“老人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在博物馆里看到一只前人的画像。", "corrected_sentence": "我在博物馆里看到一位前人的画像。", "error_description": "“一只前人”量词错误：前人指人，量词应用“位”或“个”，“只”多用于动物，应为“一位前人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥是前人修。", "corrected_sentence": "这座桥是前人修的。", "error_description": "“是……的”句式漏掉“的”：强调动作的施事时，动词后要加“的”，应为“这座桥是前人修的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
