INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古人；以前的人。", "primary_collocate": null, "pronunciation": "qián rén", "ipa": "tɕʰjɛn˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "前人说过，路是走出来的。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前人用石头做工具。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该尊敬前人。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前人没有电灯，晚上用油灯。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是前人写给朋友的。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前人的办法有时候也很好用。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，前人的智慧值得我们学习。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前人怎么过节，我们也怎么过。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里放着前人用过的东西。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前人看着月亮，写下了很多诗。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古人，过去时代的人，常与今人、后人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f931a9f9-e62e-44dc-9fd3-572b2af66ba9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，过去时代的人，是本题要辨认的词。"}, {"text": "前任", "is_correct": false, "explanation": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。"}, {"text": "千人", "is_correct": false, "explanation": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。"}, {"text": "强人", "is_correct": false, "explanation": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。"}, {"text": "闲人", "is_correct": false, "explanation": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}], "explanations": {"前人": "前人：古人，过去时代的人，是本题要辨认的词。", "前任": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。", "千人": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。", "强人": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。", "闲人": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}, "sentence_index": null, "correct_answer": "前人"}, "level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，这句是流传下来的道理，句中“说过”的主体应是前代的人。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”是乘车、船的人，不会说这种道理。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“病人”与看病、住院搭配，不与“说过……”这类道理搭配。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不会说话，不能说房子说过道理。"}], "explanations": {"前人": "前人：古人，这句是流传下来的道理，句中“说过”的主体应是前代的人。", "乘客": "语义：“乘客”是乘车、船的人，不会说这种道理。", "病人": "搭配：“病人”与看病、住院搭配，不与“说过……”这类道理搭配。", "房子": "语义：“房子”不会说话，不能说房子说过道理。"}, "sentence_index": 0, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的前人今天上午来我家做客了。", "explanation": "这里应该用〈朋友〉。前人指古代或过去时代的人，不会今天来我家做客。"}, {"text": "楼上的前人经常弹钢琴。", "explanation": "这里应该用〈邻居〉。前人指古代的人，住在隔壁或楼上的人要用“邻居”。"}, {"text": "前人每天开车送我上班。", "explanation": "这里应该用〈司机〉。前人指古代的人，每天开车工作的人要用“司机”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，其智慧值得学习，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有智慧，不能说石头的智慧。"}, {"text": "门", "is_correct": false, "explanation": "搭配：“智慧”一般不与“门”搭配。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”本身没有智慧，不能说工具的智慧值得学习。"}], "explanations": {"前人": "前人：古人，其智慧值得学习，符合句意。", "石头": "语义：“石头”没有智慧，不能说石头的智慧。", "门": "搭配：“智慧”一般不与“门”搭配。", "工具": "语义：“工具”本身没有智慧，不能说工具的智慧值得学习。"}, "sentence_index": 6, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前人今天上午去超市买菜了。", "explanation": "这里应该用〈邻居〉。前人指古代或过去时代的人，不会今天去超市买菜。"}, {"text": "教室里的前人在认真听讲。", "explanation": "这里应该用〈学生〉。前人指古代的人，在教室里听课的人要用“学生”。"}, {"text": "医院里的前人在输液。", "explanation": "这里应该用〈病人〉。前人指古代的人，在医院输液的人要用“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只前人写的诗很有名。", "corrected_sentence": "这位前人写的诗很有名。", "error_description": "“这只前人”量词错误：前人指人，应用“位”，不能用“只”，应为“这位前人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首诗是前人写。", "corrected_sentence": "这首诗是前人写的。", "error_description": "“是前人写”缺少“的”：“是……的”句式中动作后要加“的”，应为“这首诗是前人写的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。"}, {"text": "中午", "is_correct": false, "explanation": "无关：“中午”是时段名称，与“将来”没有反义关系。"}, {"text": "晚上", "is_correct": false, "explanation": "无关：“晚上”是时段名称，不是反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "无关：“早晨”是时段名称，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。", "中午": "无关：“中午”是时段名称，与“将来”没有反义关系。", "晚上": "无关：“晚上”是时段名称，不是反义词。", "早晨": "无关：“早晨”是时段名称，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "无关：“白天”是时段名称，与“将来”没有反义关系。"}, {"text": "凌晨", "is_correct": false, "explanation": "无关：“凌晨”是时段名称，不是反义词。"}, {"text": "黎明", "is_correct": false, "explanation": "无关：“黎明”是时段名称，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。", "白天": "无关：“白天”是时段名称，与“将来”没有反义关系。", "凌晨": "无关：“凌晨”是时段名称，不是反义词。", "黎明": "无关：“黎明”是时段名称，与“将来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“以后”指从现在往后的时间，即将来。", "primary_collocate": null, "pronunciation": "yǐ hòu", "ipa": "i˨˩˦ xou̯˥˩", "syllable_count": 2, "sentences": [{"text": "以后我每天早上跑步。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你以后别再迟到了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后有问题，可以问我。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我以后想当医生。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在先别说，以后再告诉你。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说以后不会再抽烟了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事以后再说吧，我现在很忙。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后你来北京，一定要找我。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后的日子里，我会更努力地学习。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以后每个周末都去看奶奶。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单独使用，指从现在往后的时间，将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”表示从现在往后，放在句首作时间状语，句意通顺。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”与“每天早上”时间相互矛盾，不能同作时间状语。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”与“每天早上跑步”的时间相互矛盾。"}, {"text": "翌日", "is_correct": false, "explanation": "语域：“翌日”是书面语，与口语化的句子语域不合，且与“每天”冲突。"}], "explanations": {"以后": "正确：“以后”表示从现在往后，放在句首作时间状语，句意通顺。", "夜里": "语义：“夜里”与“每天早上”时间相互矛盾，不能同作时间状语。", "下午": "语义：“下午”与“每天早上跑步”的时间相互矛盾。", "翌日": "语域：“翌日”是书面语，与口语化的句子语域不合，且与“每天”冲突。"}, "sentence_index": 0, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以后三年前就认识他了。", "explanation": "这里应该用〈以前〉。“以后”指将来，与“三年前”这个过去时间矛盾，应说“以前”。"}, {"text": "他以后十岁时就会游泳了。", "explanation": "这里应该用〈以前〉。“以后”指将来，与“十岁时”这个过去时间矛盾，应说“以前”。"}, {"text": "我以后已经吃过晚饭了。", "explanation": "这里应该用〈之前〉。“以后”指将来，与“已经吃过”这种已完成的动作矛盾，应说“之前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”表示从现在往后，句意是“这件事以后再说”，通顺。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与“再说吧”的将来含义相冲突。"}, {"text": "当时", "is_correct": false, "explanation": "语义：“当时”指过去的某一刻，与句中的“现在很忙”相冲突。"}, {"text": "上个月", "is_correct": false, "explanation": "语义：“上个月”指过去，与“再说吧”的将来含义和“现在很忙”的语境相冲突。"}], "explanations": {"以后": "正确：“以后”表示从现在往后，句意是“这件事以后再说”，通顺。", "昨天": "语义：“昨天”指过去，与“再说吧”的将来含义相冲突。", "当时": "语义：“当时”指过去的某一刻，与句中的“现在很忙”相冲突。", "上个月": "语义：“上个月”指过去，与“再说吧”的将来含义和“现在很忙”的语境相冲突。"}, "sentence_index": 6, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以后曾经住在上海。", "explanation": "这里应该用〈以前〉。“以后”指将来，不能和“曾经住过”这种过去的经历一起用，说过去要用“以前”。"}, {"text": "小时候，我以后很害怕狗。", "explanation": "这里应该用〈从前〉。“以后”指现在之后，不能用来描述“小时候”这样的过去情况，此处应说“从前”。"}, {"text": "我以后昨天买了一本书。", "explanation": "这里应该用〈以前〉。“以后”指将来，与“昨天”这个过去时间矛盾，说昨天做过的事要用“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以后了每天下午散步。", "corrected_sentence": "我以后每天下午散步。", "error_description": "“以后”是时间名词，不能带“了”，应说“我以后每天下午散步”；错误在于目标词后多加了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "之以后有空，我们一起吃饭。", "corrected_sentence": "以后有空，我们一起吃饭。", "error_description": "句首的“以后”前面不能加“之”，应为“以后有空”；错误在于目标词前多出了“之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "反义：“以前”与“以后”表示时间上的先后，是这一义项的反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "无关：“早晨”是一天中的时段名称，与“以后”不构成反义。"}, {"text": "中午", "is_correct": false, "explanation": "无关：“中午”只是时段名称，与“以后”没有反义关系。"}, {"text": "夜晚", "is_correct": false, "explanation": "无关：“夜晚”是时段名称，不是“以后”的反义词。"}], "correct_answer": "以前", "explanations": {"以前": "反义：“以前”与“以后”表示时间上的先后，是这一义项的反义词。", "早晨": "无关：“早晨”是一天中的时段名称，与“以后”不构成反义。", "中午": "无关：“中午”只是时段名称，与“以后”没有反义关系。", "夜晚": "无关：“夜晚”是时段名称，不是“以后”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "反义：“以前”与“以后”表示时间上的先后，是这一义项的反义词。"}, {"text": "下午", "is_correct": false, "explanation": "无关：“下午”是时段名称，与“以后”不构成反义。"}, {"text": "傍晚", "is_correct": false, "explanation": "无关：“傍晚”是时段名称，没有反义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "无关：“黎明”是时段名称，不是“以后”的反义词。"}], "correct_answer": "以前", "explanations": {"以前": "反义：“以前”与“以后”表示时间上的先后，是这一义项的反义词。", "下午": "无关：“下午”是时段名称，与“以后”不构成反义。", "傍晚": "无关：“傍晚”是时段名称，没有反义关系。", "黎明": "无关：“黎明”是时段名称，不是“以后”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指某一时间或动作之后的时间。", "primary_collocate": null, "pronunciation": "yǐ hòu", "ipa": "i˨˩˦ xou̯˥˩", "syllable_count": 2, "sentences": [{"text": "下课以后，我们去吃饭。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三年以后，这里会有一条地铁。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到家以后，请给我打电话。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业以后，在北京工作了两年。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了晚饭以后，我常常出去走走。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我到了公司以后才发现，忘带手机了。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上的人一下子少了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡着以后，妈妈才开始做自己的事。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以后，他每天都练习写汉字。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开完会以后，大家一起去了咖啡店。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放在某个动作或时间后面，指那个时间之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”指下课之后，符合先下课、再去吃饭的先后顺序。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指某时之前，“下课以前去吃饭”与“先下课、后吃饭”的顺序相反。"}, {"text": "以来", "is_correct": false, "explanation": "搭配：“以来”多接“自……以来”，表示持续到现在，不用于一次性的“下课”之后。"}, {"text": "以内", "is_correct": false, "explanation": "搭配：“以内”前面要接数量或时段，不能接“下课”这样的事件。"}], "explanations": {"以后": "正确：“以后”指下课之后，符合先下课、再去吃饭的先后顺序。", "以前": "语义：“以前”指某时之前，“下课以前去吃饭”与“先下课、后吃饭”的顺序相反。", "以来": "搭配：“以来”多接“自……以来”，表示持续到现在，不用于一次性的“下课”之后。", "以内": "搭配：“以内”前面要接数量或时段，不能接“下课”这样的事件。"}, "sentence_index": 0, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门以后要关灯。", "explanation": "这里应该用〈以前〉。“以后”指某时之后，关灯应在出门之前，此处的时间顺序与“以后”相反。"}, {"text": "出发以后要检查行李。", "explanation": "这里应该用〈之前〉。“以后”指某时之后，检查行李应在出发之前，说“以后”则时间顺序颠倒。"}, {"text": "我以后去过北京。", "explanation": "这里应该用〈以前〉。此句没有参照的时间或动作，“以后”无所指，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”指下雨之后，符合先下雨、后人变少的先后关系。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”表示“除了……之外”，与句中的因果和先后关系不合。"}, {"text": "以上", "is_correct": false, "explanation": "搭配：“以上”多接数量或范围，“下雨以上”说不通。"}, {"text": "以下", "is_correct": false, "explanation": "语义：“以下”表示位置在……之下，与“下雨之后人少了”的时间先后不符。"}], "explanations": {"以后": "正确：“以后”指下雨之后，符合先下雨、后人变少的先后关系。", "以外": "语义：“以外”表示“除了……之外”，与句中的因果和先后关系不合。", "以上": "搭配：“以上”多接数量或范围，“下雨以上”说不通。", "以下": "语义：“以下”表示位置在……之下，与“下雨之后人少了”的时间先后不符。"}, "sentence_index": 6, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去咖啡店以后，先吃了晚饭。", "explanation": "这里应该用〈以前〉。“以后”表示某时之后，句中“先吃了晚饭”与“去咖啡店以后”的先后顺序矛盾，应说“以前”。"}, {"text": "咖啡店关门以后，我们才到咖啡店。", "explanation": "这里应该用〈之前〉。“以后”表示某时之后，咖啡店关门后才到，与常理的先后顺序矛盾，应说“之前”。"}, {"text": "他以后来过这家咖啡店。", "explanation": "这里应该用〈以前〉。此句没有参照的时间或动作，“以后”无所指，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完午饭以后了，我们去图书馆。", "corrected_sentence": "吃完午饭以后，我们去图书馆。", "error_description": "“以后”后面不能直接加“了”，应为“吃完午饭以后，我们去图书馆”；错误在于目标词“以后”后多出了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班之以后，我们一起吃晚饭。", "corrected_sentence": "下班以后，我们一起吃晚饭。", "error_description": "“以后”前面不能加“之”，应为“下班以后”；错误在于目标词“以后”前多出了“之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
