INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小组是几个人在一起，做同一件事。", "primary_collocate": null, "pronunciation": "xiǎo zǔ", "ipa": "ɕjɑʊ˨˩ tsu˨˩", "syllable_count": 2, "sentences": [{"text": "我们小组有四个人。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我分到了第三小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组每天一起做作业。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组今天要做一个小实验。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组里的同学都很热情。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和小组的朋友一起打扫教室。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的人在图书馆等你。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，小组一起讨论问题。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们小组里年纪最小的同学。", "target_word": "小组", "complexity_tier": "T3", "furigana": "tā shì wǒmen xiǎo zǔ lǐ niánjì zuì xiǎo de tóngxué", "sentence_source": "generated"}, {"text": "她们小组正在练习唱歌。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小組", "label": "繁体"}, {"form": "学习小组", "label": "复合"}], "register": "中性", "sense_fingerprint": "几个人在一起做同一件事的一小群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为同一件事而聚在一起的一小群人。"}, {"text": "小虎", "is_correct": false, "explanation": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。"}, {"text": "小坐", "is_correct": false, "explanation": "zuò（第四声）与 zǔ（第三声）只有声调不同，小坐指坐一会儿，意思不同。"}, {"text": "小赌", "is_correct": false, "explanation": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}], "explanations": {"小组": "正确答案。小组指为同一件事而聚在一起的一小群人。", "小虎": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。", "小鼠": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。", "小暑": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。", "小坐": "zuò（第四声）与 zǔ（第三声）只有声调不同，小坐指坐一会儿，意思不同。", "小赌": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“我们”之后指人的集体，并且可以说“有四个人”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是人的集体，不能说“我们手机有四个人”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指一个人的体形，不能指一群人，“我们身材有四个人”说不通。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，没有人数，不能说“我们句子有四个人”。"}], "explanations": {"小组": "正确答案。“我们”之后指人的集体，并且可以说“有四个人”。", "手机": "语义：手机是电子设备，不是人的集体，不能说“我们手机有四个人”。", "身材": "体貌：身材指一个人的体形，不能指一群人，“我们身材有四个人”说不通。", "句子": "语义：句子是语言单位，没有人数，不能说“我们句子有四个人”。"}, "sentence_index": 0, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的小组很重，一个人搬不动。", "explanation": "这里应该用〈物体〉。小组是一群人，不是有重量、能被搬动的东西，说它“很重”是错的。"}, {"text": "我们国家的小组有一亿人。", "explanation": "这里应该用〈群体〉。小组指几个人一起做事的小集体，一亿人的群体不能叫小组。"}, {"text": "他把小组放进了书包。", "explanation": "这里应该用〈物品〉。小组是一群人，不是可以装进书包的东西，把它当成〈物品〉来放是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为同一件事而聚在一起的一小群人。"}, {"text": "小卒", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。"}, {"text": "小补", "is_correct": false, "explanation": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。"}, {"text": "小主", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。"}, {"text": "小渚", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}], "explanations": {"小组": "正确答案。小组指为同一件事而聚在一起的一小群人。", "小卒": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。", "小补": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。", "小主": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。", "小渚": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“我们”和“的人”之间需要一个人群的名称。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是人群，“我们课本的人”说不通。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是书面谦称，指自己的住所，不能指一群人。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的颜色，不能指一群人，“我们脸色的人”说不通。"}], "explanations": {"小组": "正确答案。“我们”和“的人”之间需要一个人群的名称。", "课本": "语义：课本是书，不是人群，“我们课本的人”说不通。", "寒舍": "语域：“寒舍”是书面谦称，指自己的住所，不能指一群人。", "脸色": "体貌：脸色指面部的颜色，不能指一群人，“我们脸色的人”说不通。"}, "sentence_index": 6, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她们小组昨天结婚了。", "explanation": "这里应该用〈个人〉。小组是为同一件事聚在一起的一群人，结婚的是个人，不能说“小组结婚”。"}, {"text": "她们小组是一家餐厅。", "explanation": "这里把〈营业场所〉的意思用到了小组上。小组是为同一件事而组成的一群人，不是经营的店铺，不能说成餐厅。"}, {"text": "她们小组是一把椅子。", "explanation": "这里把〈家具〉的意思用到了小组上。小组是一群人，不是可以坐的物品，不能说成“一把椅子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班分成了好几只小组。", "corrected_sentence": "我们班分成了好几个小组。", "error_description": "错误形式：好几只小组；正确形式：好几个小组。“小组”是人的集体，计量词要用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校里有三条小组在比赛。", "corrected_sentence": "学校里有三个小组在比赛。", "error_description": "错误形式：三条小组；正确形式：三个小组。“条”用于细长的东西，“小组”是人的集体，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
