INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为工作、学习而组成的少数人的集体。", "primary_collocate": null, "pronunciation": "xiǎo zǔ", "ipa": "ɕjɑʊ˨˩ tsu˨˩", "syllable_count": 2, "sentences": [{"text": "公司成立了一个新小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学习小组里认识了很多朋友。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的任务是研究新产品。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让我加入项目小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组每周开一次会。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在数学小组工作了三年。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的成员都是老师。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师组织了一个读书小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组今天要交报告。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想退出这个小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小組", "label": "繁体"}, {"form": "项目小组", "label": "复合"}], "register": "中性", "sense_fingerprint": "为工作或学习而组成的少数人的集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为工作或学习而组成的少数人的集体。"}, {"text": "小虎", "is_correct": false, "explanation": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。"}, {"text": "小赌", "is_correct": false, "explanation": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}, {"text": "小坐", "is_correct": false, "explanation": "zuò（第四声）与 zǔ（第三声）只有声调不同，小坐指坐一会儿，意思不同。"}], "explanations": {"小组": "正确答案。小组指为工作或学习而组成的少数人的集体。", "小虎": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。", "小鼠": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。", "小暑": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。", "小赌": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。", "小坐": "zuò（第四声）与 zǔ（第三声）只有声调不同，小坐指坐一会儿，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“成立”后面可以接机构或团体。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“成立”搭配机构或团体，不搭配饮料，“成立了一个新汽水”说不通。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，不是机构，不能被成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能被成立。"}], "explanations": {"小组": "正确答案。“成立”后面可以接机构或团体。", "汽水": "搭配：“成立”搭配机构或团体，不搭配饮料，“成立了一个新汽水”说不通。", "句子": "语义：句子是语言单位，不是机构，不能被成立。", "身材": "体貌：身材指人的体形，不能被成立。"}, "sentence_index": 0, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的项目小组有一万人。", "explanation": "这里应该用〈团体〉。小组指少数人为工作组成的集体，一万人的规模不能叫小组。"}, {"text": "经理的小组是项目负责人。", "explanation": "这里应该用〈职位〉。“项目负责人”是职位，小组是人的集体，不能充当职务。"}, {"text": "她把这个小组装进了行李箱。", "explanation": "这里应该用〈物品〉。小组是为工作或学习而组成的一群人，不是可以装进行李箱的东西，把它当成〈物品〉来装是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为工作或学习而组成的少数人的集体。"}, {"text": "小卒", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。"}, {"text": "小补", "is_correct": false, "explanation": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。"}, {"text": "小主", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。"}, {"text": "小渚", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}], "explanations": {"小组": "正确答案。小组指为工作或学习而组成的少数人的集体。", "小卒": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。", "小补": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。", "小主": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。", "小渚": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“这个”和“的成员”之间需要一个团体的名称。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，没有“成员”，“这个汽车的成员”说不通。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是书面谦称，指自己的住所，不能指一个团体。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的颜色，不能指团体的成员。"}], "explanations": {"小组": "正确答案。“这个”和“的成员”之间需要一个团体的名称。", "汽车": "语义：汽车是交通工具，没有“成员”，“这个汽车的成员”说不通。", "寒舍": "语域：“寒舍”是书面谦称，指自己的住所，不能指一个团体。", "脸色": "体貌：脸色指面部的颜色，不能指团体的成员。"}, "sentence_index": 6, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的小组是一本词典。", "explanation": "这里应该用〈物品〉。小组是一群人，不是书，不能说它“是一本词典”，把它当成〈物品〉是错的。"}, {"text": "这个小组的价格很便宜。", "explanation": "这里应该用〈商品〉。小组是为工作或学习而组成的一群人，不是可以标价出售的东西，说它“价格很便宜”是错的。"}, {"text": "这个小组昨天生病了。", "explanation": "这里应该用〈个人〉。生病的是个人，小组是为工作或学习而组成的一群人，不能说“小组生病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司刚成立了一台新小组。", "corrected_sentence": "公司刚成立了一个新小组。", "error_description": "错误形式：一台新小组；正确形式：一个新小组。“小组”是人的集体，计量词要用“个”，“台”用于机器等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块小组的任务很重要。", "corrected_sentence": "这个小组的任务很重要。", "error_description": "错误形式：这块小组；正确形式：这个小组。“块”用于成块的东西，“小组”是人的集体，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
