INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过无线电波或有线线路传播声音节目。", "primary_collocate": null, "pronunciation": "guǎng bō", "ipa": "kwɑŋ˨˩˦ pwɔ˥", "syllable_count": 2, "sentences": [{"text": "爷爷每天早上都听广播。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广播节目很有意思。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在车里听着广播回家。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里有音乐，也有新闻。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在广播里讲了一个故事。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多人不听广播，只看手机。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他晚上十点听广播学汉语。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段广播是昨天播的。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的收音机里总有广播。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢听早上的广播新闻。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "廣播", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过电波或线路传播的声音节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "搭配：“听”的对象要能发出声音，报纸是用来看的，不说听报纸。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播指通过声音播送的节目，爷爷每天早上听的就是它。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁不会发声，无法被听，与句中“听”不合。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在脸上的东西，不发声，爷爷不会去听眼镜。"}], "explanations": {"报纸": "搭配：“听”的对象要能发出声音，报纸是用来看的，不说听报纸。", "广播": "正确：广播指通过声音播送的节目，爷爷每天早上听的就是它。", "墙壁": "语义：墙壁不会发声，无法被听，与句中“听”不合。", "眼镜": "语义：眼镜是戴在脸上的东西，不发声，爷爷不会去听眼镜。"}, "sentence_index": 0, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是电台的广播，每天晚上主持节目。", "explanation": "这里应该用〈主持人〉。广播指节目或播送，不指人；主持节目的人要说“主持人”。"}, {"text": "农民在地里广播种子，很辛苦。", "explanation": "这里应该用〈播种〉。广播在这里是撒种子的义，与节目义不符；此句说的是撒种子。"}, {"text": "这张广播很有意思。", "explanation": "量词错误：“张”用于纸、桌子等平面的东西。广播节目应用“段”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "语义：镜子不发声，他无法通过镜子学习汉语。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播是通过声音播放的节目，他晚上听着它学汉语。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会说话，不能用来一边听一边学汉语。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“听”要配声音，气味应该说“闻”，不能说听气味学汉语。"}], "explanations": {"镜子": "语义：镜子不发声，他无法通过镜子学习汉语。", "广播": "正确：广播是通过声音播放的节目，他晚上听着它学汉语。", "饭菜": "语义：饭菜不会说话，不能用来一边听一边学汉语。", "气味": "搭配：“听”要配声音，气味应该说“闻”，不能说听气味学汉语。"}, "sentence_index": 6, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用手机广播一段话，留给妈妈听。", "explanation": "这里应该用〈录音〉。广播是向很多人传播声音，录给一个人留存要用“录音”，与节目义不符。"}, {"text": "这支广播我每天都听。", "explanation": "量词错误：“支”用于歌曲、笔等。广播节目应用“段”，这里应该用〈段〉。"}, {"text": "我和朋友在电话里广播，聊了一个小时。", "explanation": "这里应该用〈通话〉。广播是对很多人讲话，两人之间打电话聊天要用“通话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只广播很有意思，我常听。", "corrected_sentence": "这段广播很有意思，我常听。", "error_description": "错误：“这只广播”；正确：“这段广播”。“只”用于动物或成对的东西，广播节目应用量词“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上得广播很好听，我常听。", "corrected_sentence": "晚上的广播很好听，我常听。", "error_description": "错误：“晚上得广播很好听”；正确：“晚上的广播很好听”。只改动一处：修饰“广播”的定语标记应为“的”，“得”用于动词后作补语，此处没有动词，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
