INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86191, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“有些”是说在很多里面，有一部分是这样的。", "primary_collocate": null, "pronunciation": "yǒu xiē", "ipa": "joʊ˨˩˦ ɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "班里有些同学喜欢踢足球。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友里，有些住在北京。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书里，有些已经很旧了。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的水果，有些很甜，有些不太甜。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来的客人里有些是我的老师。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有些树已经开花了。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些菜里，有些我没吃过。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的学生有些会说法语。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的花有些是红的。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题有些很难回答。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有一些", "label": "扩展形式"}], "register": "中性", "sense_fingerprint": "在已说出的一群人或事物里，指其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有些", "is_correct": true, "explanation": "“有些”表示在班里的一部分同学中，与“同学喜欢踢足球”相合。"}, {"text": "别人的", "is_correct": false, "explanation": "语义：“别人的同学”指他人所属的同学，与“班里”的范围矛盾。"}, {"text": "自己的", "is_correct": false, "explanation": "语义：“自己的同学”指某人自己的同学，与“班里”指全班同学的所指不相合。"}, {"text": "哪些", "is_correct": false, "explanation": "搭配：“哪些”是疑问代词，陈述句中不能用它表示一部分。"}], "explanations": {"有些": "“有些”表示在班里的一部分同学中，与“同学喜欢踢足球”相合。", "别人的": "语义：“别人的同学”指他人所属的同学，与“班里”的范围矛盾。", "自己的": "语义：“自己的同学”指某人自己的同学，与“班里”指全班同学的所指不相合。", "哪些": "搭配：“哪些”是疑问代词，陈述句中不能用它表示一部分。"}, "sentence_index": 0, "correct_answer": "有些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里一个学生也没有，有些同学在踢足球。", "explanation": "这里前句说班里一个学生也没有，“有些同学”指一部分人，前后矛盾，应删去〈有些〉。"}, {"text": "全班学生有些都及格了。", "explanation": "这里“全班”指全体，应该用〈全部〉。“有些”只指一部分，二者矛盾。"}, {"text": "全班只有一个学生，有些很聪明。", "explanation": "这里只有一个学生，应该用〈他〉指代。“有些”只用于一群中的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有些", "is_correct": true, "explanation": "“有些”指那些菜中的一部分，与“我没吃过”相合。"}, {"text": "这些", "is_correct": false, "explanation": "语义：“这些”指示近处的一群，与前句的“那些菜”指代矛盾。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能指“菜”，与“那些菜里”的所指不合。"}, {"text": "哪一个", "is_correct": false, "explanation": "搭配：“哪一个”是疑问代词，陈述句中不能用它表示一部分。"}], "explanations": {"有些": "“有些”指那些菜中的一部分，与“我没吃过”相合。", "这些": "语义：“这些”指示近处的一群，与前句的“那些菜”指代矛盾。", "谁": "语义：“谁”指人，不能指“菜”，与“那些菜里”的所指不合。", "哪一个": "搭配：“哪一个”是疑问代词，陈述句中不能用它表示一部分。"}, "sentence_index": 6, "correct_answer": "有些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "所有的同学有些都喜欢体育。", "explanation": "这里表示全体同学，应该用〈全部〉。“有些”只能指一部分，二者矛盾。"}, {"text": "他是我们班唯一的男生，有些很高。", "explanation": "这里只有一个男生，“有些”表示一群中的一部分，应删去〈有些〉，改为“他很高”。"}, {"text": "整个班级有些都很认真。", "explanation": "这里表示全班都认真，应该用〈全部〉。“有些”只指一部分，不能用来表示全体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有些的同学喜欢音乐。", "corrected_sentence": "我们班有些同学喜欢音乐。", "error_description": "代词“有些”后不能加“的”，应为“有些同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的同学有些了会弹钢琴。", "corrected_sentence": "我们班的同学有些会弹钢琴。", "error_description": "代词“有些”后不能直接加“了”，应为“有些会弹钢琴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
