INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86192, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指一部分人或事物，不是全部。", "primary_collocate": null, "pronunciation": "yǒu xiē", "ipa": "joʊ˨˩˦ ɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "有些人喜欢早上跑步。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人不喝咖啡，只喝茶。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些书我看过，有些书没看过。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些国家冬天很冷。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些鱼只能在海里生活。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些商店晚上十点就关门了。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些学生喜欢用手机查词典。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些动物白天睡觉，晚上出来。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些问题老师也不会回答。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些衣服太贵，我买不起。", "target_word": "有些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有一些", "label": "扩展形式"}], "register": "中性", "sense_fingerprint": "泛指一部分人或事物，而非全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有些", "is_correct": true, "explanation": "“有些”泛指一部分人，与“人喜欢早上跑步”相合。"}, {"text": "哪些", "is_correct": false, "explanation": "搭配：“哪些”是疑问代词，陈述句中不能用它泛指一部分人。"}, {"text": "谁人", "is_correct": false, "explanation": "语域：“谁人”是书面或文言说法，口语中泛指一部分人不用它。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”指全部，与泛指一部分人的意思相反，“整个人”还指身体。"}], "explanations": {"有些": "“有些”泛指一部分人，与“人喜欢早上跑步”相合。", "哪些": "搭配：“哪些”是疑问代词，陈述句中不能用它泛指一部分人。", "谁人": "语域：“谁人”是书面或文言说法，口语中泛指一部分人不用它。", "整个": "语义：“整个”指全部，与泛指一部分人的意思相反，“整个人”还指身体。"}, "sentence_index": 0, "correct_answer": "有些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间里没有人，有些人在看书。", "explanation": "这里前句说房间里没有人，“有些人”指一部分人，前后矛盾，应删去〈有些〉。"}, {"text": "所有国家有些冬天很冷。", "explanation": "这里说所有国家，表示全部，应该用〈都〉。“有些”只能指一部分，不能用于全体。"}, {"text": "全体员工有些都在加班。", "explanation": "这里说全体员工，表示全部，应该用〈全部〉。“有些”只能表示一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有些", "is_correct": true, "explanation": "“有些”泛指一部分学生，与“喜欢用手机查词典”相合。"}, {"text": "哪个", "is_correct": false, "explanation": "搭配：“哪个”是疑问代词，陈述句中不能用它泛指一部分学生。"}, {"text": "那位", "is_correct": false, "explanation": "语义：“那位”指一个特定的人，与泛指一部分学生的意思不符。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”指全部，与“有些”（一部分）相反，与句意不合。"}], "explanations": {"有些": "“有些”泛指一部分学生，与“喜欢用手机查词典”相合。", "哪个": "搭配：“哪个”是疑问代词，陈述句中不能用它泛指一部分学生。", "那位": "语义：“那位”指一个特定的人，与泛指一部分学生的意思不符。", "所有": "语义：“所有”指全部，与“有些”（一部分）相反，与句意不合。"}, "sentence_index": 6, "correct_answer": "有些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我只有一件大衣，有些我没穿过。", "explanation": "这里只有一件大衣，应该用〈它〉指代。“有些”只能指一群中的一部分。"}, {"text": "每个学生有些都喜欢体育。", "explanation": "这里表示全体学生，应该用〈全部〉。“有些”只指一部分，二者矛盾。"}, {"text": "我家只有一只猫，有些很可爱。", "explanation": "这里只有一只猫，应该用〈它〉指代。“有些”只能指一群中的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有些的人更喜欢在晚上运动。", "corrected_sentence": "有些人更喜欢在晚上运动。", "error_description": "代词“有些”后不能加“的”，应为“有些人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有些了学生会用手机查词典。", "corrected_sentence": "我们班有些学生会用手机查词典。", "error_description": "“有些”后不能直接加“了”，应为“有些学生”；错误在于“有些”后多出了“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
