INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "忙是有很多事要做，没有空。", "primary_collocate": null, "pronunciation": "máng", "ipa": "mɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我今天很忙，没有时间吃饭。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天都很忙。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在忙吗？", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期我特别忙。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙了，没时间看电影。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作很忙的时候，我常常不吃午饭。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别打电话了，爸爸正忙呢。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近你忙不忙？", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生一天到晚都很忙。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近有点儿忙，周末也要工作。", "target_word": "忙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忙着", "label": "体标"}, {"form": "忙碌", "label": "复合"}, {"form": "繁忙", "label": "复合"}], "register": "口语", "sense_fingerprint": "事情多，没有空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忙", "is_correct": true, "explanation": "忙：事情多，没有空，是本题要辨认的词。"}, {"text": "蛮", "is_correct": false, "explanation": "mán（第二声）与 máng 只差韵母 an 与 ang，意思是很、相当（口语）。"}, {"text": "房", "is_correct": false, "explanation": "fáng（第二声）与 máng 声母不同（f 与 m），意思是房子。"}, {"text": "毛", "is_correct": false, "explanation": "máo（第二声）与 máng 韵母不同（ao 与 ang），意思是毛发。"}], "explanations": {"忙": "忙：事情多，没有空，是本题要辨认的词。", "蛮": "mán（第二声）与 máng 只差韵母 an 与 ang，意思是很、相当（口语）。", "房": "fáng（第二声）与 máng 声母不同（f 与 m），意思是房子。", "毛": "máo（第二声）与 máng 韵母不同（ao 与 ang），意思是毛发。"}, "sentence_index": null, "correct_answer": "忙"}, "level_3": {"options": [{"text": "忙", "is_correct": true, "explanation": "忙：事情多，没有空，与“没有时间吃饭”的原因相符。"}, {"text": "闲", "is_correct": false, "explanation": "语义：闲指没有事情做，与“没有时间吃饭”相矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖形容体形，不能用“今天很胖”来说明没有时间吃饭的情况。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：无聊指没有事情可做，与“没有时间吃饭”相矛盾。"}], "explanations": {"忙": "忙：事情多，没有空，与“没有时间吃饭”的原因相符。", "闲": "语义：闲指没有事情做，与“没有时间吃饭”相矛盾。", "胖": "体貌：胖形容体形，不能用“今天很胖”来说明没有时间吃饭的情况。", "无聊": "语义：无聊指没有事情可做，与“没有时间吃饭”相矛盾。"}, "sentence_index": 0, "correct_answer": "忙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车跑得很忙，一下子就到了。", "explanation": "这里应该用〈快〉。忙指事情多、没有空，形容速度快要用“快”。"}, {"text": "屋子里很忙，书和衣服扔得到处都是。", "explanation": "这里应该用〈乱〉。忙指事情多、没有空，形容屋子杂乱要用“乱”。"}, {"text": "这里的天气很忙，一直下雨。", "explanation": "这里应该用〈坏〉。“忙”指事情多、没有空，不能用来形容天气，形容天气不好要用“坏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忙", "is_correct": true, "explanation": "忙：事情多，没有空，是本题要辨认的词。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 máng 只差韵母 a 与 ang，意思是麻木。"}, {"text": "旁", "is_correct": false, "explanation": "páng（第二声）与 máng 声母不同（p 与 m），意思是旁边。"}, {"text": "狼", "is_correct": false, "explanation": "láng（第二声）与 máng 声母不同（l 与 m），意思是狼。"}], "explanations": {"忙": "忙：事情多，没有空，是本题要辨认的词。", "麻": "má（第二声）与 máng 只差韵母 a 与 ang，意思是麻木。", "旁": "páng（第二声）与 máng 声母不同（p 与 m），意思是旁边。", "狼": "láng（第二声）与 máng 声母不同（l 与 m），意思是狼。"}, "sentence_index": null, "correct_answer": "忙"}, "level_3": {"options": [{"text": "忙", "is_correct": true, "explanation": "忙：正在做事，没有空，符合“别打电话了”的原因。"}, {"text": "空", "is_correct": false, "explanation": "语义：空指有空闲，与“别打电话了”的理由相矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：身高是固有特征，不能用“正高呢”来描述当下的状态。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容人正在做什么，句子不通。"}], "explanations": {"忙": "忙：正在做事，没有空，符合“别打电话了”的原因。", "空": "语义：空指有空闲，与“别打电话了”的理由相矛盾。", "高": "体貌：身高是固有特征，不能用“正高呢”来描述当下的状态。", "咸": "语义：“咸”形容味道，不能用来形容人正在做什么，句子不通。"}, "sentence_index": 6, "correct_answer": "忙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最近很忙，每天躺在床上看电视。", "explanation": "这里应该用〈闲〉。忙指事情多、没有空，每天躺着看电视表示空闲要用“闲”。"}, {"text": "这个星期我忙，可以陪你。", "explanation": "这里应该用〈空闲〉。忙表示没有空，与“可以陪你”相矛盾。"}, {"text": "我今天很忙，没有事做。", "explanation": "这里应该用〈空〉。忙指事情多，与“没有事做”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这几天忙很，没有时间休息。", "corrected_sentence": "他这几天很忙，没有时间休息。", "error_description": "程度副词“很”要放在形容词“忙”前面，应说“很忙”，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天他忙地没时间吃饭。", "corrected_sentence": "这几天他忙得没时间吃饭。", "error_description": "“忙”后面接表示程度的补语，要用“得”连接，不用“地”。应说“忙得没时间吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
