INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为了共同目的而联合起来的组织，如企业集团。", "primary_collocate": null, "pronunciation": "jí tuán", "ipa": "tɕi˧˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "这个集团有二十家公司。", "target_word": "集团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个集团旗下有三十多家公司。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个集团的子公司在很多国家都有工厂。", "target_word": "集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家公司合并，成了一个大集团。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "集团总经理明天要开会。", "target_word": "集团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "集团下面的几家公司都在赚钱。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把几家小公司组成一个集团。", "target_word": "集团", "complexity_tier": "T3", "furigana": "tā xiǎng bǎ jǐ jiā xiǎo gōngsī zǔchéng yí ge jítuán", "sentence_source": "generated"}, {"text": "这个集团由三家银行和两家工厂组成。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爸爸是一家大集团的董事长。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个集团有五万多名员工，分在各个公司。", "target_word": "集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集團", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "企业集团", "label": "复合"}], "register": "中性", "sense_fingerprint": "集团：为共同目的联合起来的组织，如企业集团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集团", "is_correct": true, "explanation": "正确：“集团”指多家公司联合起来的大组织，可以拥有二十家公司。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不是公司联合的组织，不会“有二十家公司”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的场所，不会拥有公司。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“水”是不可数的物质名词，不能与“有二十家公司”搭配。"}], "explanations": {"集团": "正确：“集团”指多家公司联合起来的大组织，可以拥有二十家公司。", "学校": "语义：学校是教育机构，不是公司联合的组织，不会“有二十家公司”。", "花园": "语义：花园是种植花草的场所，不会拥有公司。", "水": "搭配：“水”是不可数的物质名词，不能与“有二十家公司”搭配。"}, "sentence_index": 0, "correct_answer": "集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开了一家小集团，只有两个员工。", "explanation": "这里应该用〈公司〉。“集团”指多家公司联合起来的大组织，一家只有两个员工的小店只能说“公司”。"}, {"text": "这座大楼是一个大集团，里面有很多房间。", "explanation": "这里应该用〈大楼〉。“集团”指由人或公司联合起来的组织，不能用来指建筑物。"}, {"text": "这片森林是一个大集团，里面住着很多动物。", "explanation": "这里应该用〈森林〉。“集团”指组织，不能用来指地方或自然景观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集团", "is_correct": true, "explanation": "正确：“组成一个集团”指把几家公司组织成一个大的联合体。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是公司，不能由几家小公司“组成”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，不能由几家公司组成。"}, {"text": "米", "is_correct": false, "explanation": "搭配：“米”是物质名词，不能说“组成一个米”。"}], "explanations": {"集团": "正确：“组成一个集团”指把几家公司组织成一个大的联合体。", "厨房": "语义：厨房不是公司，不能由几家小公司“组成”。", "玩具": "语义：玩具是物品，不能由几家公司组成。", "米": "搭配：“米”是物质名词，不能说“组成一个米”。"}, "sentence_index": 6, "correct_answer": "集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是一个大集团，工作很努力。", "explanation": "这里应该用〈人〉。“集团”指组织，不能用来指一个人。"}, {"text": "我们家是一个集团，全家都很和睦。", "explanation": "这里应该用〈家庭〉。“集团”指为共同目的联合起来的组织，家庭要说“家庭”。"}, {"text": "这个大集团是一座红色的老房子，很漂亮。", "explanation": "这里应该用〈房子〉。“集团”指组织，不能用来指房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想和两集团合作。", "corrected_sentence": "我们想和两个集团合作。", "error_description": "错误：数词“两”与“集团”之间漏掉了量词“个”。应说“两个集团”，不能说“两集团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座集团想进入这个市场。", "corrected_sentence": "这个集团想进入这个市场。", "error_description": "错误：量词用错。“集团”应搭配“个”或“家”，不能用“座”（“座”多用于山、楼、桥等大型固定物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平时", "is_correct": false, "explanation": "不是反义词：“平时”指平常的时候，与“之前”的时间先后没有相对关系。"}, {"text": "之后", "is_correct": true, "explanation": "正确：“之后”与“之前”意思相反，指比某个时间晚的时候。"}, {"text": "日期", "is_correct": false, "explanation": "不是反义词：“日期”指具体的某一天，与“之前”没有相对关系。"}, {"text": "星期", "is_correct": false, "explanation": "不是反义词：“星期”指一周中的某一天，与“之前”没有相对关系。"}], "correct_answer": "之后", "explanations": {"平时": "不是反义词：“平时”指平常的时候，与“之前”的时间先后没有相对关系。", "之后": "正确：“之后”与“之前”意思相反，指比某个时间晚的时候。", "日期": "不是反义词：“日期”指具体的某一天，与“之前”没有相对关系。", "星期": "不是反义词：“星期”指一周中的某一天，与“之前”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时光", "is_correct": false, "explanation": "不是反义词：“时光”指时间的流逝，与“之前”的先后关系无关。"}, {"text": "年龄", "is_correct": false, "explanation": "不是反义词：“年龄”指人活了多少年，与“之前”没有相对关系。"}, {"text": "之后", "is_correct": true, "explanation": "正确：“之后”与“之前”意思相反，指在某个时间以后。"}, {"text": "季节", "is_correct": false, "explanation": "不是反义词：“季节”指春夏秋冬，与“之前”没有相对关系。"}], "correct_answer": "之后", "explanations": {"时光": "不是反义词：“时光”指时间的流逝，与“之前”的先后关系无关。", "年龄": "不是反义词：“年龄”指人活了多少年，与“之前”没有相对关系。", "之后": "正确：“之后”与“之前”意思相反，指在某个时间以后。", "季节": "不是反义词：“季节”指春夏秋冬，与“之前”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“之前”是说比这件事早的时间。", "primary_collocate": null, "pronunciation": "zhī qián", "ipa": "tʂɻ̩˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "之前我住在上海，现在住在北京。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他之前不喜欢吃辣的，现在每天都吃。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我之前不知道，今天才听说。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "之前这里没有地铁，现在很方便。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我之前学过一年汉语，所以会说一点。", "target_word": "之前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她之前很瘦，现在胖了一些。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你之前说今天不下雨，可是下了。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店之前很小，后来才变大。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们之前见过面，你还记得吗？", "target_word": "之前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他之前总是迟到，现在每天都很早。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "单独作时间词，指比所说的时间或事情更早的时期，常放在句首或主语后，与现在对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之间", "is_correct": false, "explanation": "搭配：“之间”表示两者中间，不能作时间状语，“之间我住在上海”不成立。"}, {"text": "之前", "is_correct": true, "explanation": "正确：“之前”指比“现在”更早的时期，与后半句的“现在”形成对比。"}, {"text": "方面", "is_correct": false, "explanation": "搭配：“方面”指某个领域，不表示时间，“方面我住在上海”不成立。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：“时候”不能单独作时间状语，要说“……的时候”。"}], "explanations": {"之间": "搭配：“之间”表示两者中间，不能作时间状语，“之间我住在上海”不成立。", "之前": "正确：“之前”指比“现在”更早的时期，与后半句的“现在”形成对比。", "方面": "搭配：“方面”指某个领域，不表示时间，“方面我住在上海”不成立。", "时候": "搭配：“时候”不能单独作时间状语，要说“……的时候”。"}, "sentence_index": 0, "correct_answer": "之前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把车停在学校之前。", "explanation": "这里“之前”表示位置，不是时间用法，应说“停在学校前面”。"}, {"text": "我站在他之前。", "explanation": "这里用“之前”表示空间上的“在……前面”，这不是“之前”的用法，它只表示时间。"}, {"text": "他在老师之前不敢说话。", "explanation": "这里应该用〈面前〉。“之前”只表示时间，表示在某人面前要说“在老师面前”，不能说“在老师之前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期间", "is_correct": false, "explanation": "搭配：“期间”要接在一段时间后面，“你期间说”不成立。"}, {"text": "之前", "is_correct": true, "explanation": "正确：“之前”表示说话在下雨之前，与“可是下了”的结果相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是将来，与“可是下了”的已发生事实相矛盾。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指以后的一次，与“可是下了”的已发生事实相反。"}], "explanations": {"期间": "搭配：“期间”要接在一段时间后面，“你期间说”不成立。", "之前": "正确：“之前”表示说话在下雨之前，与“可是下了”的结果相符。", "明天": "语义：“明天”是将来，与“可是下了”的已发生事实相矛盾。", "下次": "语义：“下次”指以后的一次，与“可是下了”的已发生事实相反。"}, "sentence_index": 6, "correct_answer": "之前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在父母之前从不说谎。", "explanation": "这里应该用〈面前〉。“之前”只表示时间，表示在某人面前要说“在父母面前”。"}, {"text": "我的书在书架之前。", "explanation": "这里应该用〈前面〉。“之前”只表示时间，表示位置要说“书架前面”。"}, {"text": "我在饭店之前等你。", "explanation": "这里应该用〈门口〉。“之前”只表示时间，表示地点要说“饭店门口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王之前了很忙，现在轻松多了。", "corrected_sentence": "小王之前很忙，现在轻松多了。", "error_description": "错误：“了”不能紧跟时间词“之前”，“之前了很忙”语法不通；应删去“了”，写作“小王之前很忙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事发生在他来很之前。", "corrected_sentence": "这件事发生在他来之前。", "error_description": "“很”是程度副词，不能修饰“之前”这样的时间词，应删去“很”，写作“他来之前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时光", "is_correct": false, "explanation": "不是反义词：“时光”指时间的流逝，与“之前”的先后没有相对关系。"}, {"text": "之后", "is_correct": true, "explanation": "正确：“之后”与“之前”意思相反，指在某件事以后。"}, {"text": "年龄", "is_correct": false, "explanation": "不是反义词：“年龄”指人的岁数，与“之前”没有相对关系。"}, {"text": "季节", "is_correct": false, "explanation": "不是反义词：“季节”指一年中的某段时期，与“之前”没有相对关系。"}], "correct_answer": "之后", "explanations": {"时光": "不是反义词：“时光”指时间的流逝，与“之前”的先后没有相对关系。", "之后": "正确：“之后”与“之前”意思相反，指在某件事以后。", "年龄": "不是反义词：“年龄”指人的岁数，与“之前”没有相对关系。", "季节": "不是反义词：“季节”指一年中的某段时期，与“之前”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平时", "is_correct": false, "explanation": "不是反义词：“平时”指平常的时候，与“之前”的先后没有相对关系。"}, {"text": "日期", "is_correct": false, "explanation": "不是反义词：“日期”指具体的某一天，与“之前”没有相对关系。"}, {"text": "之后", "is_correct": true, "explanation": "正确：“之后”与“之前”意思相反，指在某件事以后。"}, {"text": "星期", "is_correct": false, "explanation": "不是反义词：“星期”指一周中的某一天，与“之前”没有相对关系。"}], "correct_answer": "之后", "explanations": {"平时": "不是反义词：“平时”指平常的时候，与“之前”的先后没有相对关系。", "日期": "不是反义词：“日期”指具体的某一天，与“之前”没有相对关系。", "之后": "正确：“之后”与“之前”意思相反，指在某件事以后。", "星期": "不是反义词：“星期”指一周中的某一天，与“之前”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，表示在某一时间或某件事以前。", "primary_collocate": null, "pronunciation": "zhī qián", "ipa": "tʂɻ̩˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "睡觉之前，我喜欢喝一杯热牛奶。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭之前，请先洗手。", "target_word": "之前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门之前，别忘了关灯。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试之前，他每天都复习到很晚。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课之前，老师把门打开了。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会之前，我们先准备好了材料。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三点之前，你一定要回到家。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨之前，奶奶把衣服收进来了。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "结婚之前，他们一起住了两年。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业之前，我想去一次北京。", "target_word": "之前", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接在动作或时间词后面，构成“……之前”，表示在某个时间点或某件事发生以前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将来", "is_correct": false, "explanation": "语义：“将来”指以后的日子，不能表示睡觉这件事以前的时间。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”表示两者中间，不能接在动作后作时间状语，“睡觉之间”不成立。"}, {"text": "之前", "is_correct": true, "explanation": "正确：“之前”表示睡觉这件事以前，与“喝一杯热牛奶”的睡前习惯相合。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指遥远的以后，与“睡觉”这个每天的习惯不相合。"}], "explanations": {"将来": "语义：“将来”指以后的日子，不能表示睡觉这件事以前的时间。", "之间": "搭配：“之间”表示两者中间，不能接在动作后作时间状语，“睡觉之间”不成立。", "之前": "正确：“之前”表示睡觉这件事以前，与“喝一杯热牛奶”的睡前习惯相合。", "未来": "语义：“未来”指遥远的以后，与“睡觉”这个每天的习惯不相合。"}, "sentence_index": 0, "correct_answer": "之前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把自行车停在教室之前。", "explanation": "这里“之前”表示位置，不是时间用法，应说“停在教室前面”。"}, {"text": "他在朋友之前很害羞。", "explanation": "这里应该用〈面前〉。“之前”只表示时间，表示在别人面前要说“在朋友面前”。"}, {"text": "他在老师之前一直不敢说话。", "explanation": "这里应该用〈面前〉。“之前”只表示时间，表示在老师面前要说“在老师面前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期间", "is_correct": false, "explanation": "搭配：“期间”要接在一段时间后面，“三点期间”不能作时间状语。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指另一天，与“三点”这个当天的时刻不符。"}, {"text": "之前", "is_correct": true, "explanation": "正确：“之前”表示三点这个时刻以前，与“一定要回到家”的期限相合。"}, {"text": "下次", "is_correct": false, "explanation": "搭配：“下次”指将来的一次，不能用来限定具体的钟点。"}], "explanations": {"期间": "搭配：“期间”要接在一段时间后面，“三点期间”不能作时间状语。", "明天": "语义：“明天”指另一天，与“三点”这个当天的时刻不符。", "之前": "正确：“之前”表示三点这个时刻以前，与“一定要回到家”的期限相合。", "下次": "搭配：“下次”指将来的一次，不能用来限定具体的钟点。"}, "sentence_index": 6, "correct_answer": "之前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在同学之前站了起来。", "explanation": "这里应该用〈面前〉。“之前”只表示时间，表示在同学面前要说“在同学面前”。"}, {"text": "我的书在窗户之前。", "explanation": "这里应该用〈前面〉。“之前”只表示时间，表示位置要说“窗户前面”。"}, {"text": "我们在图书馆之前见面吧。", "explanation": "这里应该用〈门口〉。“之前”只表示时间，表示地点要说“图书馆门口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃饭了之前，他先洗了手。", "corrected_sentence": "吃饭之前，他先洗了手。", "error_description": "“了”不能加在“之前”前面，应删去，写作“吃饭之前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出门很之前，他要检查一下门。", "corrected_sentence": "出门之前，他要检查一下门。", "error_description": "“很”是程度副词，不能修饰“之前”，应删去“很”，写作“出门之前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
