INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "方位词，指某一范围之外，与“内”“里”相对。", "primary_collocate": null, "pronunciation": "wài", "ipa": "wai˥˩", "syllable_count": 1, "sentences": [{"text": "他住在十公里外。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请站在白线外，别进来。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山外有山，人外有人。", "target_word": "外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城很小，城外都是田地。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在三百米外就听到了声音。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事在我们的计划外。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球落在了线外，不能算分。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圈里的人都知道，圈外的人不知道。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从学校出发，一公里外有一个地铁站。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把车停在了五十米外的路边。", "target_word": "外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外边", "label": "复合"}, {"form": "外面", "label": "复合"}], "register": "中性", "sense_fingerprint": "外：方位词，某一范围之外，与内、里相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86204, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“外”（wài）表示某一范围之外，与“内”相对。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 wài（第四声）声母不同，意思是“害”（伤害）。"}, {"text": "拜", "is_correct": false, "explanation": "bài（第四声）与 wài（第四声）声母不同，意思是“拜访”。"}, {"text": "赖", "is_correct": false, "explanation": "lài（第四声）与 wài（第四声）声母不同，意思是“赖”（抵赖或依赖）。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 wài（第四声）声母不同，意思是“盖子”或“覆盖”。"}], "explanations": {"外": "正确：“外”（wài）表示某一范围之外，与“内”相对。", "害": "hài（第四声）与 wài（第四声）声母不同，意思是“害”（伤害）。", "拜": "bài（第四声）与 wài（第四声）声母不同，意思是“拜访”。", "赖": "lài（第四声）与 wài（第四声）声母不同，意思是“赖”（抵赖或依赖）。", "盖": "gài（第四声）与 wài（第四声）声母不同，意思是“盖子”或“覆盖”。"}, "sentence_index": null, "correct_answer": "外"}, "level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“十公里外”表示距离在十公里之外。"}, {"text": "里", "is_correct": false, "explanation": "搭配：“十公里里”不成立，表示距离要说“十公里外”。"}, {"text": "上", "is_correct": false, "explanation": "搭配：“十公里上”不是表示距离的常用说法。"}, {"text": "旁", "is_correct": false, "explanation": "语义：“旁”指紧挨着的近处，不能表示相距十公里。"}], "explanations": {"外": "正确：“十公里外”表示距离在十公里之外。", "里": "搭配：“十公里里”不成立，表示距离要说“十公里外”。", "上": "搭配：“十公里上”不是表示距离的常用说法。", "旁": "语义：“旁”指紧挨着的近处，不能表示相距十公里。"}, "sentence_index": 0, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙装进了口袋外。", "explanation": "这里应该用〈里〉。“装进”表示放入容器内部，说“口袋外”意思相反，应说“口袋里”。"}, {"text": "他把书放进了书架外。", "explanation": "这里应该用〈里〉。“放进”表示放到容器或空间内部，说“书架外”意思相反，应说“书架里”。"}, {"text": "他把几支笔塞进了盒子外。", "explanation": "这里应该用〈里〉。“塞进”表示放入容器内部，说“盒子外”意思相反，应说“盒子里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86204, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“外”（wài）表示某一范围之外，与“内”相对。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 wài（第四声）声母不同，意思是“太”（很、过于）。"}, {"text": "再", "is_correct": false, "explanation": "zài（第四声）与 wài（第四声）声母不同，意思是“再”。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 wài（第四声）声母不同，意思是“卖”。"}, {"text": "戴", "is_correct": false, "explanation": "dài（第四声）与 wài（第四声）声母不同，意思是“戴”（戴帽子）。"}], "explanations": {"外": "正确：“外”（wài）表示某一范围之外，与“内”相对。", "太": "tài（第四声）与 wài（第四声）声母不同，意思是“太”（很、过于）。", "再": "zài（第四声）与 wài（第四声）声母不同，意思是“再”。", "卖": "mài（第四声）与 wài（第四声）声母不同，意思是“卖”。", "戴": "dài（第四声）与 wài（第四声）声母不同，意思是“戴”（戴帽子）。"}, "sentence_index": null, "correct_answer": "外"}, "level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“线外”指界线之外，球落在界外不计分。"}, {"text": "里", "is_correct": false, "explanation": "语义：“线里”指界线之内，球落在界内有效，与“不能算分”矛盾。"}, {"text": "内", "is_correct": false, "explanation": "语义：“线内”指界线之内，球落在界内有效，与“不能算分”矛盾。"}, {"text": "底", "is_correct": false, "explanation": "语义：“线底”指线的下部，与球的界内外判定无关。"}], "explanations": {"外": "正确：“线外”指界线之外，球落在界外不计分。", "里": "语义：“线里”指界线之内，球落在界内有效，与“不能算分”矛盾。", "内": "语义：“线内”指界线之内，球落在界内有效，与“不能算分”矛盾。", "底": "语义：“线底”指线的下部，与球的界内外判定无关。"}, "sentence_index": 6, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把饼干藏进了箱子外。", "explanation": "这里应该用〈里〉。“藏进”表示放到容器内部，说“箱子外”意思相反，应说“箱子里”。"}, {"text": "他把包背在了身外。", "explanation": "这里应该用〈上〉。“背在身上”才表示物体贴着身体，说“身外”意思相反。"}, {"text": "他把书签夹进了本子外。", "explanation": "这里应该用〈里〉。“夹进”表示放到本子里面，说“本子外”意思相反，应说“本子里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站学校外一公里。", "corrected_sentence": "车站在学校外一公里。", "error_description": "错误：漏掉了介词“在”。表示地点要说“车站在学校外一公里”，不能说“车站学校外一公里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭店火车站外。", "corrected_sentence": "饭店在火车站外。", "error_description": "错误：漏掉了介词“在”。地点要说“饭店在火车站外”，不能直接说“饭店火车站外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
