INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86211, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“中和”是说两样不同的东西放在一起，味道或力量变得平和了。", "primary_collocate": null, "pronunciation": "zhōng hé", "ipa": "tʂʊŋ˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "加点糖可以中和柠檬的酸味。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶能中和咖啡的苦味。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好脾气中和了她的急脾气。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加一些水，就能中和汤里的咸味。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃点甜水果，能中和嘴里的辣味。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜中和了茶的苦味，喝着很顺口。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浅色窗帘中和了房间里太重的红色。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭能中和辣椒的辣味。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲的冷静中和了母亲的着急。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放点奶油，把辣味中和一下。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中和了", "label": "体标（了）"}, {"form": "中和过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "两样东西放在一起，味道或力量变得平和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 浅色 (Zipf 3.19), 窗帘 (Zipf 3.65), 太重 (Zipf 3.57)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 米饭 (Zipf 3.68), 辣椒 (Zipf 3.83), 辣味 (Zipf 3.02)']::text[], 'fad93ff1-e83a-46ed-abe7-7c4d40942d3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中和", "is_correct": true, "explanation": "正确：加糖使酸味变得平和，「中和」指味道变得平和，符合句意。"}, {"text": "加强", "is_correct": false, "explanation": "语义：加强是使酸味更重，与「加点糖」减弱酸味的作用相反。"}, {"text": "增添", "is_correct": false, "explanation": "语义：增添是添加，加糖后酸味不会增多，与句中的作用相反。"}, {"text": "刺激", "is_correct": false, "explanation": "搭配：「刺激」一般带感官或人作宾语，不能说「刺激酸味」。"}], "explanations": {"中和": "正确：加糖使酸味变得平和，「中和」指味道变得平和，符合句意。", "加强": "语义：加强是使酸味更重，与「加点糖」减弱酸味的作用相反。", "增添": "语义：增添是添加，加糖后酸味不会增多，与句中的作用相反。", "刺激": "搭配：「刺激」一般带感官或人作宾语，不能说「刺激酸味」。"}, "sentence_index": 0, "correct_answer": "中和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用清水中和蔬菜。", "explanation": "这里应该用〈清洗〉。中和是使味道或力量变得平和，洗掉蔬菜上的脏东西要说「清洗」，不能说「中和」。"}, {"text": "用小火慢慢中和汤。", "explanation": "这里应该用〈加热〉。中和是使味道或力量变得平和，用火给汤升温要说「加热」，不能说「中和」。"}, {"text": "老师中和了事故的原因。", "explanation": "这里应该用〈分析〉。中和是使味道或力量变得平和，剖析事故的起因要说「分析」，不能说「中和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中和", "is_correct": true, "explanation": "正确：浅色窗帘使太重的红色变得平和，与「中和」的意思一致。"}, {"text": "加深", "is_correct": false, "explanation": "语义：浅色窗帘应使红色变淡，「加深」与句中的「浅色」相反。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大是扩大范围或体积，颜色不能被放大，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能带「红色」作宾语，句子说不通。"}], "explanations": {"中和": "正确：浅色窗帘使太重的红色变得平和，与「中和」的意思一致。", "加深": "语义：浅色窗帘应使红色变淡，「加深」与句中的「浅色」相反。", "放大": "语义：放大是扩大范围或体积，颜色不能被放大，句子说不通。", "唱": "搭配：「唱」不能带「红色」作宾语，句子说不通。"}, "sentence_index": 6, "correct_answer": "中和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "锅底被火中和了。", "explanation": "这里应该用〈烧焦〉。中和是使味道或力量变得平和，火把锅底烧黑变焦要说「烧焦」，不能说「中和」。"}, {"text": "雨水中和了街上的灰尘。", "explanation": "这里应该用〈冲走〉。中和是使味道或力量变得平和，把灰尘冲掉要说「冲走」，不能说「中和」。"}, {"text": "音箱把声音中和了。", "explanation": "这里应该用〈放大〉。中和是使味道或力量变平和，音箱是让声音变大，不能用「中和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜂蜜正在中和了茶的苦味。", "corrected_sentence": "蜂蜜正在中和茶的苦味。", "error_description": "体标错误：「正在」表示动作进行，不能与「了」同用，应说「蜂蜜正在中和茶的苦味」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放一些奶油，可以把中和汤里的辣味。", "corrected_sentence": "放一些奶油，可以中和汤里的辣味。", "error_description": "“把”字句中，“把”后应先接宾语再接动词，不能直接接“中和”；应说“可以中和汤里的辣味”或“可以把汤里的辣味中和”，错误在于多加了“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
