INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86215, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“多少”是用来问数目有多大的。", "primary_collocate": null, "pronunciation": "duō shao", "ipa": "tuɔ˥ ʂɑʊ", "syllable_count": 2, "sentences": [{"text": "这本书多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们班有多少个学生？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家有多少口人？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一斤苹果多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天花了多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这个手机多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买多少个杯子？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个月看多少本书？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来了多少客人？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路有多少公里？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用来询问数目大小的疑问词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多少", "is_correct": true, "explanation": "正确：「多少钱」是问价格的常用说法，「多少」询问数目或价格的多少。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：问价格不说「什么钱」，应说「多少钱」。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，书的价格不能用「谁」来问。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：「怎样」问性质或方式，不能用来问价钱，应说「多少钱」。"}], "explanations": {"多少": "正确：「多少钱」是问价格的常用说法，「多少」询问数目或价格的多少。", "什么": "搭配：问价格不说「什么钱」，应说「多少钱」。", "谁": "语义：「谁」问人，书的价格不能用「谁」来问。", "怎样": "搭配：「怎样」问性质或方式，不能用来问价钱，应说「多少钱」。"}, "sentence_index": 0, "correct_answer": "多少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天星期多少？", "explanation": "这里应该用〈几〉。问星期要说「星期几」，「多少」不用于询问星期。"}, {"text": "今天多少号？", "explanation": "这里应该用〈几〉。问日期的号数要说「几号」，「多少」不用于询问日期。"}, {"text": "这个月是多少月？", "explanation": "这里应该用〈几〉。问月份要说「几月」，「多少」不用于询问月份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多少", "is_correct": true, "explanation": "正确：「多少个杯子」用来问杯子的数目。"}, {"text": "多久", "is_correct": false, "explanation": "语义：「多久」问时间的长短，这里问的是杯子的数目。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」表示从几个中挑选，这里问的是数量，不是选择。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：「怎么」问方式，不能直接修饰「个杯子」来问数量。"}], "explanations": {"多少": "正确：「多少个杯子」用来问杯子的数目。", "多久": "语义：「多久」问时间的长短，这里问的是杯子的数目。", "哪些": "语义：「哪些」表示从几个中挑选，这里问的是数量，不是选择。", "怎么": "搭配：「怎么」问方式，不能直接修饰「个杯子」来问数量。"}, "sentence_index": 6, "correct_answer": "多少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天多少点出发？", "explanation": "这里应该用〈几〉。问钟点要说「几点」，「多少」不用于询问时刻。"}, {"text": "开学是多少号？", "explanation": "这里应该用〈几〉。问日期要说「几号」，「多少」不用于询问日期。"}, {"text": "你是多少年级的学生？", "explanation": "这里应该用〈几〉。问年级要说「几年级」，「多少」不用于询问年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个公司有多少本员工？", "corrected_sentence": "这个公司有多少名员工？", "error_description": "量词错误：「员工」是人，「多少」后的量词应为「名」，「本」只用于书籍等，写成「多少本员工」不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件大衣多少了钱？", "corrected_sentence": "这件大衣多少钱？", "error_description": "词内插入错误：「多少钱」是固定的问价格说法，「了」不能插在「多少」和「钱」之间，应说「这件大衣多少钱？」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
