INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "日常生活中使用的。", "primary_collocate": null, "pronunciation": "rì yòng", "ipa": "ɻ̩˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "牙刷和毛巾都是日用的东西。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖很多日用的东西。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店专门卖日用的物品。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家时，我先买了一些日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西都是日用的，不贵。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈周末去市场买日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友寄了一箱日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些日用的东西，家里不能少。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗发水、肥皂都是日用的。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，只带日用的东西就够了。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日用品", "label": "复合"}, {"form": "日用百货", "label": "复合"}], "register": "通用", "sense_fingerprint": "日常生活中使用的（修饰物品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e76b94-2d0b-469a-847a-d9083859c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日用", "is_correct": true, "explanation": "正确：牙刷和毛巾都是日常生活中使用的物品，与“日用”的含义相符。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：牙刷和毛巾价格低廉，说它们“昂贵”与常识相反。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：牙刷和毛巾不是易碎品，说它们“易碎”与其材质和用途不符。"}, {"text": "珍奇", "is_correct": false, "explanation": "语域：“珍奇”偏书面，指稀罕之物，与平常的牙刷、毛巾不相称。"}], "explanations": {"日用": "正确：牙刷和毛巾都是日常生活中使用的物品，与“日用”的含义相符。", "昂贵": "语义：牙刷和毛巾价格低廉，说它们“昂贵”与常识相反。", "易碎": "语义：牙刷和毛巾不是易碎品，说它们“易碎”与其材质和用途不符。", "珍奇": "语域：“珍奇”偏书面，指稀罕之物，与平常的牙刷、毛巾不相称。"}, "sentence_index": 0, "correct_answer": "日用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚持日用锻炼，身体很好。", "explanation": "这里应该用〈日常〉。日用只修饰日常使用的物品，“锻炼”要用“日常”。"}, {"text": "这是一个日用的理论。", "explanation": "这里应该用〈实用〉。日用指物品在日常生活中使用，“理论”不是物品，要用“实用”。"}, {"text": "这是一项日用的检查。", "explanation": "这里应该用〈常规〉。日用指物品在日常生活中使用，“检查”要用“常规”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日用", "is_correct": true, "explanation": "正确：“日用”修饰日常使用的物品，与“寄一箱东西”的语境相符。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫的东西不能装箱寄送，与“寄一箱”的语境矛盾。"}, {"text": "无形", "is_correct": false, "explanation": "语义：无形的东西无法装进箱子，与“一箱”的具体数量矛盾。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：“年迈”多形容人或动物，不用来修饰“东西”。"}], "explanations": {"日用": "正确：“日用”修饰日常使用的物品，与“寄一箱东西”的语境相符。", "滚烫": "语义：滚烫的东西不能装箱寄送，与“寄一箱”的语境矛盾。", "无形": "语义：无形的东西无法装进箱子，与“一箱”的具体数量矛盾。", "年迈": "搭配：“年迈”多形容人或动物，不用来修饰“东西”。"}, "sentence_index": 6, "correct_answer": "日用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个日用的周末。", "explanation": "这里应该用〈平常〉。日用只修饰日常使用的物品，“周末”要用“平常”。"}, {"text": "他是一个日用的学生。", "explanation": "这里应该用〈普通〉。日用只修饰日常使用的物品，不能用来修饰人。"}, {"text": "我日用的工作很多。", "explanation": "这里应该用〈每日〉。日用修饰物品，“工作”要用“每日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了几件很日用的东西。", "corrected_sentence": "我买了几件日用的东西。", "error_description": "区别词误用：“日用”修饰名词时不能受“很”修饰，应说“日用的东西”，不说“很日用的东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行时，我们只带日用的品就够了。", "corrected_sentence": "旅行时，我们只带日用品就够了。", "error_description": "结构错误：“日用品”是固定复合词，“品”不能单独与“日用的”组合，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慢", "is_correct": false, "explanation": "不是反义词：“慢”指速度低，与“美”没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, {"text": "长", "is_correct": false, "explanation": "不是反义词：“长”指距离或时间大，与“美”没有相对关系。"}, {"text": "厚", "is_correct": false, "explanation": "不是反义词：“厚”指厚度大，与“美”没有相对关系。"}], "correct_answer": "丑", "explanations": {"慢": "不是反义词：“慢”指速度低，与“美”没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。", "长": "不是反义词：“长”指距离或时间大，与“美”没有相对关系。", "厚": "不是反义词：“厚”指厚度大，与“美”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": false, "explanation": "不是反义词：“硬”指不软，与“美”没有相对关系。"}, {"text": "轻", "is_correct": false, "explanation": "不是反义词：“轻”指重量小，与“美”没有相对关系。"}, {"text": "远", "is_correct": false, "explanation": "不是反义词：“远”指距离长，与“美”没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}], "correct_answer": "丑", "explanations": {"硬": "不是反义词：“硬”指不软，与“美”没有相对关系。", "轻": "不是反义词：“轻”指重量小，与“美”没有相对关系。", "远": "不是反义词：“远”指距离长，与“美”没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“美”是说看起来很好看，让人高兴。", "primary_collocate": null, "pronunciation": "měi", "ipa": "meɪ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条裙子真美，我想买下来。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿红色的衣服很美。", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这朵花开得很美，我拍了一张照片。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的那幅画真美。", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新娘今天太美了，大家都看着她。", "target_word": "美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的字写得很美，老师常常夸她。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里的花那么美，我每天都去看。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小鸟的羽毛真美，红红绿绿的。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，她的眼睛多美啊！", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件旗袍很美，她穿着更好看。", "target_word": "美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美丽", "label": "复合"}, {"form": "美美", "label": "重叠"}], "register": "中性", "sense_fingerprint": "单用作谓语，形容人、衣物、花、画等外表看起来漂亮好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是外表好看。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。"}, {"text": "没", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。"}, {"text": "煤", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是煤。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是外表好看。", "妹": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。", "没": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。", "煤": "méi（第二声）与 měi（第三声）声调不同，意思是煤。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "脏", "is_correct": false, "explanation": "语义：“脏”表示不干净，与“我想买下来”的喜爱相反。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不能用来形容裙子，这里不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容裙子好看，与“我想买下来”的喜欢相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不能用来形容裙子，这里不成立。"}], "explanations": {"脏": "语义：“脏”表示不干净，与“我想买下来”的喜爱相反。", "矮": "搭配：“矮”说高度，不能用来形容裙子，这里不成立。", "美": "正确：“美”形容裙子好看，与“我想买下来”的喜欢相合。", "高": "搭配：“高”说高度，不能用来形容裙子，这里不成立。"}, "sentence_index": 0, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的结果很美。", "explanation": "这里应该用〈好〉。“美”形容外观，不用于考试结果，结果好要说“好”。"}, {"text": "这次考试的分数很美，我考了满分。", "explanation": "这里应该用〈高〉。“美”形容外观，不用于分数，分数高要说“高”。"}, {"text": "我的牙很美，今天不能吃东西。", "explanation": "这里应该用〈疼〉。“美”不用于身体的疼痛，牙疼要说“疼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是外表好看。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。"}, {"text": "眉", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。"}, {"text": "梅", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是外表好看。", "北": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。", "眉": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。", "梅": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。", "买": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不能用来形容花的样子，“花那么吵”不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容花好看，与“我每天都去看”的喜爱相合。"}, {"text": "旧", "is_correct": false, "explanation": "搭配：“旧”说物品新旧，不能用来形容花的外貌，这里不成立。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”说温度，不能用来形容花的外貌，这里不成立。"}], "explanations": {"吵": "搭配：“吵”形容声音，不能用来形容花的样子，“花那么吵”不成立。", "美": "正确：“美”形容花好看，与“我每天都去看”的喜爱相合。", "旧": "搭配：“旧”说物品新旧，不能用来形容花的外貌，这里不成立。", "冷": "搭配：“冷”说温度，不能用来形容花的外貌，这里不成立。"}, "sentence_index": 6, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差的开销很美，我们付不起。", "explanation": "这里应该用〈贵〉。“美”不用于开销，开销高要说“贵”。"}, {"text": "这次作业的难度很美，我做不完。", "explanation": "这里应该用〈难〉。“美”形容外观，不用于难度，难度大要说“难”。"}, {"text": "我很美，想吃饭了。", "explanation": "这里应该用〈饿〉。“美”形容外貌，不能表示饥饿的感觉，饿了要说“饿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗前的花真很美。", "corrected_sentence": "窗前的花真美。", "error_description": "“真”和“很”不能同时修饰“美”，应删去“很”，写作“真美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小鸟美真。", "corrected_sentence": "那只小鸟真美。", "error_description": "“真”是程度副词，要放在“美”前面，应为“真美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": false, "explanation": "不是反义词：“冷”指温度低，与“美”的意思没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, {"text": "快", "is_correct": false, "explanation": "不是反义词：“快”指速度高，与“美”没有相对关系。"}, {"text": "硬", "is_correct": false, "explanation": "不是反义词：“硬”指不软，与“美”没有相对关系。"}], "correct_answer": "丑", "explanations": {"冷": "不是反义词：“冷”指温度低，与“美”的意思没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。", "快": "不是反义词：“快”指速度高，与“美”没有相对关系。", "硬": "不是反义词：“硬”指不软，与“美”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": false, "explanation": "不是反义词：“甜”指味道，与“美”没有相对关系。"}, {"text": "远", "is_correct": false, "explanation": "不是反义词：“远”指距离长，与“美”没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, {"text": "轻", "is_correct": false, "explanation": "不是反义词：“轻”指重量小，与“美”没有相对关系。"}], "correct_answer": "丑", "explanations": {"甜": "不是反义词：“甜”指味道，与“美”没有相对关系。", "远": "不是反义词：“远”指距离长，与“美”没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。", "轻": "不是反义词：“轻”指重量小，与“美”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
